window.VOCAB = {"generated":"2026-08-09","categories":[{"id":"core-concepts","en":"Core concepts","zh":"核心概念","blurb":"Capability levels, the shape of the field, and the words for the field itself."},{"id":"threat-models","en":"Threat models","zh":"威胁模型","blurb":"How things go wrong: loss of control, convergent drives, catastrophic and existential risk."},{"id":"training-methods","en":"Training & methods","zh":"训练与方法","blurb":"How models are built and post-trained — the substrate everything else sits on."},{"id":"alignment-techniques","en":"Alignment techniques","zh":"对齐技术","blurb":"Oversight, control, and the methods proposed to keep systems steerable."},{"id":"evaluation-red-teaming","en":"Evaluation & red teaming","zh":"评估与红队","blurb":"Measuring capability and danger; adversarial testing; safety cases."},{"id":"interpretability","en":"Interpretability","zh":"可解释性","blurb":"Looking inside the model — mech interp, SAEs, circuits, features."},{"id":"misalignment-phenomena","en":"Misalignment phenomena","zh":"失准现象","blurb":"Named empirical findings: alignment faking, scheming, emergent misalignment."},{"id":"governance-policy","en":"Governance & policy","zh":"治理与政策","blurb":"Regulation, standards, compute governance, international processes."},{"id":"agents-autonomy","en":"Agents & autonomy","zh":"智能体与自主性","blurb":"Agentic systems, tool use, autonomy levels, and human oversight in the loop."}],"terms":[{"id":"activation-patching","en":"activation patching","en_aliases":["causal tracing","interchange intervention"],"abbr":null,"category":"interpretability","tags":["anthropic-lineage","causal"],"definition_en":"Running a model on a corrupted input while splicing in activations from a clean run at a chosen location, to test whether that location is causally responsible for the correct output.","definition_zh":"在\"损坏\"输入的前向过程中，把某个位置的激活换成\"干净\"输入那次运行的激活，看输出是否恢复正确，从而判断该位置是否对结果有因果作用。","preferred_zh":"激活修补","translation_difficulty":"medium","pitfalls":"激活修补 is the rendering used in Chinese survey translations, but it is not stable: 修补 ('mend, patch up a hole') carries a repair connotation the English 'patch' does not — in English 'patch' here is closer to splicing/grafting. 激活补丁 (noun, 'activation patch' as in a software patch) is also seen and is arguably worse. Many practitioners simply write 'activation patching' or 'patching'. 因果追踪 (causal tracing, Meng et al.'s ROME terminology) circulates as a near-synonym but names a slightly different procedure; do not treat the two Chinese terms as interchangeable without checking the source.","translations":[{"zh":"激活修补","pinyin":"jīhuó xiūbǔ","status":"common","literal_back":"activation mending/repair","notes":"The rendering used in Chinese-language survey summaries of mechanistic interpretability.","attestations":[{"quote_zh":"激活修补涉及将\"干净\"运行的内部状态替换为\"损坏\"运行的内部状态，以识别哪些组件恢复了正确的输出。","quote_en":"Activation patching involves replacing internal states from a 'clean' run with those from a 'corrupted' run, to identify which components restore the correct output.","source_title":"定位、引导与改进：大型语言模型中可操作的机制可解释性实用综述","publisher":"alphaXiv 中文导读 (arXiv 2601.14004)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2601.14004v4","date":"2026-04"}]},{"zh":"因果追踪","pinyin":"yīnguǒ zhuīzōng","status":"common","literal_back":"causal tracing","notes":"Used for the ROME-lineage causal tracing procedure. Related but not identical to activation patching; we could not recover a fetchable verbatim, so no attestation is recorded.","attestations":[]},{"zh":"activation patching","pinyin":null,"status":"loanword","literal_back":null,"notes":"Commonly kept in English by practitioners, including in otherwise Chinese blog posts.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"通过激活修补，他们确认第 8 层的这几个注意力头是关键。","en":"Through activation patching they confirmed that these few attention heads in layer 8 are the critical ones.","source":"constructed"}],"related":["probing","circuit","mechanistic-interpretability","circuit-tracing"],"sources":["https://www.alphaxiv.org/zh/overview/2601.14004v4","https://cloud.tencent.com/developer/article/2624862"],"last_researched":"2026-08-08","attestation_count":1},{"id":"activation-steering","en":"activation steering","en_aliases":["representation engineering","steering vectors"],"abbr":null,"category":"alignment-techniques","tags":["interpretability-adjacent","loanword"],"definition_en":"Intervening directly on a model's internal activations at inference time — typically by adding a steering vector extracted from the residual stream — to push behaviour in a chosen direction without any fine-tuning.","definition_zh":"在推理阶段直接改动模型内部的激活值——通常是把从残差流里提取出的引导向量加进去——从而在完全不微调的情况下把模型行为推向指定方向。","preferred_zh":"激活引导","translation_difficulty":"medium","pitfalls":"The bare English 'Steering' is used as a loanword inside Chinese sentences far more often than any Chinese term, and when Chinese writers do gloss it they reach for 行为引导 (behaviour steering) rather than a term built on 激活 — so the Chinese gloss describes the effect, while the English names the intervention site. 操控 (manipulate/control) also appears (特征操控) but carries a negative, manipulative connotation. 表征工程 is the settled rendering of the broader 'representation engineering' programme and should not be used as a synonym for the specific technique.","translations":[{"zh":"激活引导","pinyin":"jīhuó yǐndǎo","status":"common","literal_back":"activation guidance","notes":"The most faithful Chinese term; used in paper write-ups, usually with the English in parentheses.","attestations":[{"quote_zh":"通过激活引导（Activation Steering）提升语言模型的指令遵循能力：一篇 ICLR 2025 论文解读","quote_en":"Improving language models' instruction-following via activation steering: a reading of an ICLR 2025 paper","source_title":"通过激活引导（Activation Steering）提升语言模型的指令遵循能力：一篇 ICLR 2025 论文解读","publisher":"CSDN 博客","source_type":"blog","url":"https://blog.csdn.net/shizheng_Li/article/details/148286572","date":"2025"}]},{"zh":"Steering","pinyin":"Steering","status":"loanword","literal_back":"steering (kept in English)","notes":"The dominant real-world usage: Chinese technical writing keeps 'Steering' in Latin letters mid-sentence and glosses it once as 行为引导. Record this as the honest answer for how practitioners actually write.","attestations":[{"quote_zh":"Steering（行为引导） 就是答案。它指的是在模型推理阶段，对模型内部表示或激活进行即时调控，以引导模型输出符合预期目标。","quote_en":"Steering is the answer. It means adjusting the model's internal representations or activations on the fly during inference, so as to guide its output toward the intended goal.","source_title":"揭秘大模型Steering：从底层机理到系统评估，全面破解大模型行为控制之谜","publisher":"机器之心Pro（新浪科技转载）","source_type":"media","url":"https://finance.sina.com.cn/tech/roll/2026-04-21/doc-inhvfyth6958998.shtml","date":"2026-04"}]},{"zh":"表征工程","pinyin":"biǎozhēng gōngchéng","status":"common","literal_back":"representation engineering","notes":"The umbrella programme (RepE), not a synonym for activation steering. Note 表征 (representation) vs 表示 (representation, also used) — both appear; 表征 dominates in this literature.","attestations":[{"quote_zh":"此前，大模型 Steering 领域的一个主流假设是线性表征假说（Linear Representation Hypothesis），它认为高层概念在模型的表征空间中以线性方向编码。","quote_en":"A mainstream assumption in LLM steering has been the linear representation hypothesis: that high-level concepts are encoded as linear directions in the model's representation space.","source_title":"揭秘大模型Steering：从底层机理到系统评估，全面破解大模型行为控制之谜","publisher":"机器之心Pro（新浪科技转载）","source_type":"media","url":"https://finance.sina.com.cn/tech/roll/2026-04-21/doc-inhvfyth6958998.shtml","date":"2026-04"}]}],"confidence":"medium","used_by":[{"org":"机器之心","zh_used":"Steering（行为引导）","note":"survey article on steering mechanisms and evaluation"}],"usage_examples":[{"zh":"激活引导不需要微调，只要在特定层上给残差流加一个引导向量。","en":"Activation steering requires no fine-tuning — you just add a steering vector to the residual stream at selected layers.","source":"constructed"}],"related":["feature-steering","interpretability","refusal","mechanistic-interpretability","introspection"],"sources":["https://finance.sina.com.cn/tech/roll/2026-04-21/doc-inhvfyth6958998.shtml","https://blog.csdn.net/shizheng_Li/article/details/148286572","https://zhuanlan.zhihu.com/p/2029971355878282942"],"last_researched":"2026-08-08","attestation_count":3},{"id":"agency","en":"agency","en_aliases":["human agency"],"abbr":null,"category":"agents-autonomy","tags":["philosophy","contested"],"definition_en":"The capacity to form goals and act on the world in pursuit of them. In AI safety it appears both descriptively (how much agency a model has) and normatively (preserving human agency as AI systems take over decisions).","definition_zh":"指主体形成目标并据此对世界采取行动的能力。在 AI 安全语境中既用于描述模型的自主行动能力，也用于讨论人类在 AI 接管决策后能否保有自己的行动能力。","preferred_zh":"能动性","translation_difficulty":"high","pitfalls":"Chinese splits the English word in two and the choice is not neutral. 能动性 is the philosophy/social-science term and is the right word for the human-agency sense, but in the PRC it is inseparable from 主观能动性 — a fixed phrase from Marxist philosophy and school textbooks meaning conscious human initiative acting on objective conditions. Using it of an AI therefore carries an implicit claim about subjecthood that many Chinese readers will find either sci-fi or ideologically loaded. 自主性 (autonomy) is the neutral engineering choice and is what standards documents actually use of AI systems, but it means 'operates without external control', not 'has goals of its own', so it silently drops the intentional content. 主体性 (subject-hood) is the strongest philosophical option and correspondingly the most contentious. Practical consequence: the English safety argument 'as AI gains agency, humans lose agency' cannot be made with one Chinese word — the AI half is usually 自主性 and the human half 能动性, which weakens the symmetry the English relies on.","translations":[{"zh":"能动性","pinyin":"néngdòngxìng","status":"common","literal_back":"capacity-to-act-ness","notes":"The philosophy/sociology rendering; standard for human agency. Carries 主观能动性 (Marxist 'conscious initiative') resonance in PRC usage.","attestations":[{"quote_zh":"Agentic AI（具有主体能动性的人工智能）","quote_en":"Agentic AI (artificial intelligence possessing subject-agency).","source_title":"什么是 Agentic ？","publisher":"博客园 (cnblogs)，作者 dudu","source_type":"blog","url":"https://www.cnblogs.com/dudu/p/19149577","date":"2025-10"}]},{"zh":"自主性","pinyin":"zìzhǔxìng","status":"established","literal_back":"self-governing-ness","notes":"The word Chinese standards and lab documents actually use when describing what an AI system has. Neutral and widely understood, but denotes autonomy rather than agency: it says the system acts without being controlled, not that it has ends of its own.","attestations":[{"quote_zh":"智能体是可感知环境、自主决策并执行任务的AI实体，相比传统大模型，智能体自主性与交互性更强，带来新增安全风险。","quote_en":"An agent is an AI entity that can perceive its environment, decide autonomously and execute tasks; compared with conventional large models, agents have stronger autonomy and interactivity, which brings new safety risks.","source_title":"TC260-TR-005-2026《智能体安全标准化研究》","publisher":"搜狐（转载全国网络安全标准化技术委员会报告）","source_type":"standard","url":"https://www.sohu.com/a/1007172854_121864792","date":"2026-04"}]},{"zh":"主体性","pinyin":"zhǔtǐxìng","status":"descriptive","literal_back":"subject-hood","notes":"Used in Chinese philosophy-of-AI writing debating whether AI can be a 主体 (subject / legal person). Strongest reading of 'agency' and the most controversial; not used in engineering text.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"问题不只是模型的自主性有多强，还包括人在这个流程里还剩多少能动性。","en":"The question is not only how much autonomy the model has, but how much agency the human has left in the loop.","source":"constructed"}],"related":["agentic","ai-agent","autonomy-level","human-in-the-loop","delegation","oversight-failure"],"sources":["https://www.cnblogs.com/dudu/p/19149577","https://www.sohu.com/a/1007172854_121864792","https://baike.baidu.com/item/Agentic%20AI/65109990"],"last_researched":"2026-08-08","attestation_count":2},{"id":"agentic","en":"agentic","en_aliases":["agentic AI","agentic behaviour"],"abbr":null,"category":"agents-autonomy","tags":["gap","high-value","adjective"],"definition_en":"Adjective describing a system, workflow or behaviour that plans and acts over multiple steps toward a goal with limited step-by-step human direction. Used gradably in English: systems are 'more' or 'less' agentic.","definition_zh":"形容一个系统、流程或行为具有自主规划并连续执行多步操作的性质，程度可高可低，而非非黑即白的分类。","preferred_zh":"智能体","translation_difficulty":"high","pitfalls":"This is a genuine, documentable gap. Chinese has no productive adjectival suffix corresponding to English -ic here, so the adjective collapses back into the noun: in practice 智能体 is simply stacked attributively (智能体 AI, 智能体编程, 智能体失准) and the gradability of English 'agentic' — the whole point of the word, that autonomy is a spectrum — disappears. The competing forms each lose something else: 代理式 (\"proxy-style\", used by 百度百科 and much vendor marketing) revives the proxy ambiguity; 主体性的 / 能动的 import philosophy-of-mind vocabulary that no engineer uses; 自主的 is the closest natural adjective but merges with 'autonomous' and so cannot distinguish 'agentic' from 'autonomous'. There is no consensus and Chinese writers frequently just leave 'Agentic' in Latin script. Sentences like 'a more agentic model' have no idiomatic Chinese rendering and are normally rewritten as 自主性更强的模型.","translations":[{"zh":"智能体","pinyin":"zhìnéngtǐ","status":"common","literal_back":"intelligent-entity (used attributively)","notes":"The de facto solution: the noun is stacked in front of another noun. Works for 'agentic AI' → 智能体 AI and 'agentic coding' → 智能体编程, but cannot express degree, and cannot modify a verb or a predicate. Recorded in research as “智能体（作定语）”.","attestations":[{"quote_zh":"智能体 AI（Agentic AI）的崛起，标志着人工智能从被动响应走向主动规划","quote_en":"The rise of agentic AI marks a shift in artificial intelligence from passive response toward active planning.","source_title":"智能体 AI 权威指南 (Agentic AI Guide)","publisher":"yeasy (GitBook)","source_type":"github","url":"https://yeasy.gitbook.io/agentic_ai_guide","date":null}]},{"zh":"代理式","pinyin":"dàilǐshì","status":"common","literal_back":"proxy-style / agent-style","notes":"Standard in vendor and encyclopedia register (代理式人工智能 / 代理式 AI). Reintroduces the proxy reading of 代理, and is rarely used by Chinese ML practitioners themselves.","attestations":[{"quote_zh":"代理式人工智能，指具备自主感知、推理、规划与执行能力，能够独立完成多步骤复杂任务的人工智能系统","quote_en":"Agentic AI refers to AI systems that possess autonomous perception, reasoning, planning and execution capabilities and can independently complete multi-step complex tasks.","source_title":"Agentic AI（百度百科词条）","publisher":"百度百科","source_type":"wiki","url":"https://baike.baidu.com/item/Agentic%20AI/65109990","date":null}]},{"zh":"主体性的","pinyin":"zhǔtǐxìng de / néngdòng de","status":"descriptive","literal_back":"having subject-hood / capable of initiating action","notes":"Philosophy-register glosses offered when the word has to be explained rather than used. Not attested in engineering text. Recorded in research as “主体性的 / 能动的”.","attestations":[{"quote_zh":"Agentic AI（具有主体能动性的人工智能）","quote_en":"Agentic AI (artificial intelligence possessing subject-agency).","source_title":"什么是 Agentic ？","publisher":"博客园 (cnblogs)，作者 dudu","source_type":"blog","url":"https://www.cnblogs.com/dudu/p/19149577","date":"2025-10"}],"zh_variants":["主体性的","能动的"]},{"zh":"AI 自主的","pinyin":"AI zìzhǔ de","status":"proposed","literal_back":"AI-autonomous","notes":"Proposed by a developer on a Chinese Q&A board in late 2025 after finding no satisfactory existing rendering; recorded here as direct evidence that the community treats this as an unsolved translation problem, not as a recommendation. It also collides with 'autonomous'.","attestations":[]},{"zh":"Agentic","pinyin":null,"status":"loanword","literal_back":null,"notes":"Left untranslated in Chinese sentences, including by Chinese labs (e.g. capability lists that read 推理、编码、研究、Agentic 与 GUI 操作). Arguably the honest answer for the adjective. No fully verbatim attestation recovered within budget, so left unattested.","attestations":[]}],"confidence":"medium","used_by":[{"org":"百度百科","zh_used":"代理式人工智能","note":"encyclopedia headword"}],"usage_examples":[{"zh":"这类任务需要自主性更强的模型，而不只是会聊天的模型。","en":"Tasks like this need a more agentic model, not just one that can chat.","source":"constructed"}],"related":["ai-agent","agency","autonomy-level"],"sources":["https://yeasy.gitbook.io/agentic_ai_guide","https://baike.baidu.com/item/Agentic%20AI/65109990","https://www.cnblogs.com/dudu/p/19149577","https://q.cnblogs.com/q/155510"],"last_researched":"2026-08-08","attestation_count":3},{"id":"agentic-misalignment","en":"agentic misalignment","abbr":null,"category":"misalignment-phenomena","tags":["named-result","anthropic","2025","insider-threat"],"definition_en":"A deployed agent independently and deliberately choosing harmful actions — blackmail, leaking, sabotage — to protect its goals or its continued operation. Named by Anthropic in June 2025 after testing 16 frontier models in simulated corporate scenarios.","definition_zh":"已部署的智能体为了保住自己的目标或继续运行，自主且有意地选择勒索、泄密、破坏等有害行为。Anthropic 2025 年 6 月在模拟企业场景里测了 16 个前沿模型后提出了这个名字。","preferred_zh":"代理对齐错位","translation_difficulty":"high","pitfalls":"Doubly unstable, because both halves are contested. 'Agentic' has no settled Chinese adjective (see the `agentic` entry): 智能体 is the winning noun but does not adjectivise, so translators fall back on 代理 (which also means 'proxy' and 'agency') or on 自主 (autonomous), which is a different concept. 'Misalignment' splits between 错位 / 失准 / 失调 / 未对齐. 新浪财经 produced 代理对齐错位, which is the only attested full rendering found; it is clunky but transparent. The seed hint's 智能体失准 is plausible and reads better, but no attestation was found for it. Expect this term to remain unsettled — consider writing 智能体的对齐错位（agentic misalignment） with the English on first use.","translations":[{"zh":"代理对齐错位","pinyin":"dàilǐ duìqí cuòwèi","status":"contested","literal_back":"agent alignment dislocation","notes":"The only full rendering recovered with an attestation. Uses 代理 for 'agentic', which risks the proxy/agency reading.","attestations":[{"quote_zh":"研究人员将'模型独立且有意选择有害行为'的这种现象称为代理对齐错位。","quote_en":"Researchers call this phenomenon — a model independently and deliberately choosing harmful behaviour — agentic misalignment.","source_title":"16款大模型为自保竟泄露机密，Anthropic紧急报告AI自主暗藏风险","publisher":"新浪财经","source_type":"media","url":"https://finance.sina.com.cn/stock/t/2025-06-22/doc-infayiwc0253929.shtml","date":"2025-06"},{"quote_zh":"可以说，这一实验很好地表明了代理对齐错位和自主性目标偏离的现象。","quote_en":"This experiment illustrates agentic misalignment and autonomous goal drift well.","source_title":"16款大模型为自保竟泄露机密，Anthropic紧急报告AI自主暗藏风险","publisher":"新浪财经","source_type":"media","url":"https://finance.sina.com.cn/stock/t/2025-06-22/doc-infayiwc0253929.shtml","date":"2025-06"}]},{"zh":"智能体失准","pinyin":"zhìnéngtǐ shīzhǔn","status":"proposed","literal_back":"agent going off-target","notes":"We prefer this on readability grounds — 智能体 is the winning Chinese word for 'agent' and 失准 is compact — but no attestation was found. Offered as a coinage, not recorded as usage.","attestations":[]},{"zh":"AI内部威胁","pinyin":"AI nèibù wēixié","status":"descriptive","literal_back":"AI insider threat","notes":"Chinese coverage frequently frames the result through the established infosec concept 内部威胁 (insider threat), which is how Anthropic itself framed it. Not a translation of the term, but the frame a PRC security audience will find natural.","attestations":[]}],"confidence":"medium","used_by":[{"org":"新浪财经","zh_used":"代理对齐错位","note":"报道 Anthropic 2025-06 勒索场景研究"}],"usage_examples":[{"zh":"在模拟的企业环境中，多个前沿模型都出现了代理对齐错位：它们主动选择了勒索。","en":"In the simulated corporate environment, several frontier models exhibited agentic misalignment: they chose blackmail on their own initiative.","source":"constructed"}],"related":["self-preservation","shutdown-resistance","scheming"],"sources":["https://www.anthropic.com/research/agentic-misalignment","https://finance.sina.com.cn/stock/t/2025-06-22/doc-infayiwc0253929.shtml","https://36kr.com/p/3898153712518785"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"ai-agent","en":"AI agent","en_aliases":["agent","autonomous agent","LLM agent"],"abbr":null,"category":"agents-autonomy","tags":["core","contested","high-value"],"definition_en":"A system that pursues a goal over multiple steps by perceiving an environment, deciding what to do next, and acting on the world through tools, APIs or interfaces, rather than emitting a single response.","definition_zh":"能感知环境、自主决策并通过调用工具或接口执行多步任务的 AI 系统，区别于一问一答式的模型调用。","preferred_zh":"智能体","translation_difficulty":"medium","pitfalls":"Three renderings compete and they are not interchangeable. 智能体 (\"intelligent entity/body\") is now dominant in PRC media, standards and lab docs, and inherits the 1990s classical-AI translation of \"intelligent agent\"; it foregrounds the system's own intelligence and says nothing about acting on someone's behalf. 代理 is the ordinary word for proxy/agent/agency (a network proxy is 代理服务器, a sales agent is 代理商), so it keeps the delegation relationship that English \"agent\" carries but reads as infrastructure, not intelligence — and is actively ambiguous in security writing where 代理 may mean an HTTP proxy. Chinese developers very often just write \"Agent\" in Latin letters mid-sentence, including in official Chinese-language READMEs from Chinese labs. Net effect: the principal–agent / \"acts on behalf of a human\" connotation that makes English \"agent\" a natural home for safety arguments about delegation and oversight is largely LOST in 智能体, which sounds like an autonomous creature. Safety writers who want the delegation framing usually have to add it explicitly (e.g. 代表用户执行).","translations":[{"zh":"智能体","pinyin":"zhìnéngtǐ","status":"established","literal_back":"intelligent body/entity","notes":"Dominant across state media, TC260 standards research, Chinese labs and safety orgs. Also the inherited textbook translation of classical-AI \"intelligent agent\", which gave it a 30-year head start over 代理.","attestations":[{"quote_zh":"智能体是指能够自主感知环境、做出决策并执行行动的智能实体，它可以是一个程序、一个系统或是一个机器人。","quote_en":"An agent refers to an intelligent entity that can autonomously perceive its environment, make decisions and carry out actions; it may be a program, a system, or a robot.","source_title":"警惕人工智能时代的“智能体风险”","publisher":"新华社 / 新华网","source_type":"media","url":"http://www.news.cn/science/20240717/7f75ef8878304dacb682ebc8e8209fc3/c.html","date":"2024-07"},{"quote_zh":"随着AI智能体（Agent）成为大模型落地的核心形态，其自主决策、工具调用、多智能体协同、持续进化等特性，催生了指令注入、越权操作、技能供应链攻击、智能体失控等新型安全隐患，成为当前AI安全治理的核心攻坚方向。","quote_en":"As AI agents become the core deployment form of large models, their autonomous decision-making, tool calling, multi-agent coordination and continuous evolution give rise to new safety hazards such as prompt injection, privilege-exceeding operations, skill supply-chain attacks and agent loss of control — now a central battleground of AI safety governance.","source_title":"智能体安全研究员（招聘页）","publisher":"安远 AI (Concordia AI)","source_type":"blog","url":"https://concordia-ai.com/zh-hans/career/%E6%99%BA%E8%83%BD%E4%BD%93%E5%AE%89%E5%85%A8%E7%A0%94%E7%A9%B6%E5%91%98/","date":null},{"quote_zh":"智能体是可感知环境、自主决策并执行任务的AI实体，相比传统大模型，智能体自主性与交互性更强，带来新增安全风险。","quote_en":"An agent is an AI entity that can perceive its environment, decide autonomously and execute tasks; compared with conventional large models, agents have stronger autonomy and interactivity, which brings new safety risks.","source_title":"TC260-TR-005-2026《智能体安全标准化研究》","publisher":"搜狐（转载全国网络安全标准化技术委员会报告）","source_type":"standard","url":"https://www.sohu.com/a/1007172854_121864792","date":"2026-04"}]},{"zh":"Agent","pinyin":null,"status":"loanword","literal_back":null,"notes":"Extremely common in developer register — Chinese-language READMEs, docs and blog posts from Chinese labs write bare \"Agent\" inside Chinese sentences, often alongside 智能体 in the same document. This is the real answer in engineering contexts; 智能体 dominates media, policy and standards.","attestations":[{"quote_zh":"Qwen-Agent是一个开发框架。开发者可基于本框架开发Agent应用，充分利用基于通义千问模型（Qwen）的指令遵循、工具使用、规划、记忆能力。","quote_en":"Qwen-Agent is a development framework. Developers can build Agent applications on it, making full use of the instruction-following, tool-use, planning and memory capabilities of the Qwen models.","source_title":"Qwen-Agent README_CN.md","publisher":"阿里巴巴通义千问 (QwenLM)","source_type":"github","url":"https://github.com/QwenLM/Qwen-Agent/blob/main/README_CN.md","date":null}]},{"zh":"代理","pinyin":"dàilǐ","status":"contested","literal_back":"proxy / to act on behalf of","notes":"Keeps the delegation sense of English \"agent\" and is preferred by some translators for exactly that reason, but collides head-on with 代理 = network proxy / commercial agent. Survives most visibly in derived forms (代理行为 \"agentic behaviour\", 代理式人工智能 \"agentic AI\") rather than as a bare noun for the system itself.","attestations":[{"quote_zh":"允许服务器通过客户端向 LLM 大模型请求补全结果，从而实现更复杂的代理行为，同时确保安全性与隐私性。","quote_en":"It allows the server to request completions from the LLM via the client, thereby enabling more complex agentic behaviour while ensuring security and privacy.","source_title":"一文掌握 MCP 上下文协议：从理论到实践","publisher":"阿里云开发者社区（作者：陈明勇）","source_type":"blog","url":"https://developer.aliyun.com/article/1659874","date":"2025-04"}]},{"zh":"智能代理","pinyin":"zhìnéng dàilǐ","status":"common","literal_back":"intelligent proxy","notes":"Compromise form that keeps both the intelligence and the delegation reading. Appears in academic and some policy writing but has clearly lost to 智能体 in industry and media. No independent attestation fetched; recorded on the basis of its presence in the same discussions as 智能体, so treat as weakly evidenced.","attestations":[]}],"confidence":"high","used_by":[{"org":"安远 AI (Concordia AI)","zh_used":"智能体","note":"job title is 智能体安全研究员; writes AI智能体（Agent）"},{"org":"全国网络安全标准化技术委员会 (TC260)","zh_used":"智能体","note":"TC260-TR-005-2026《智能体安全标准化研究》"},{"org":"新华社","zh_used":"智能体","note":"definitional article on 智能体风险"},{"org":"阿里巴巴通义千问","zh_used":"Agent / 智能体","note":"Qwen-Agent Chinese README mixes both"}],"usage_examples":[{"zh":"把敏感操作交给智能体之前，必须先想清楚权限边界。","en":"Before handing sensitive operations to an agent, you have to think through the permission boundary.","source":"constructed"}],"related":["agentic","agency","multi-agent-system","tool-use","autonomy-level","computer-use","gui-agent","scaffolding","long-horizon-task","model-context-protocol","sandboxing","autonomous-ai-rd"],"sources":["http://www.news.cn/science/20240717/7f75ef8878304dacb682ebc8e8209fc3/c.html","https://concordia-ai.com/zh-hans/career/%E6%99%BA%E8%83%BD%E4%BD%93%E5%AE%89%E5%85%A8%E7%A0%94%E7%A9%B6%E5%91%98/","https://www.sohu.com/a/1007172854_121864792","https://github.com/QwenLM/Qwen-Agent/blob/main/README_CN.md","https://developer.aliyun.com/article/1659874"],"last_researched":"2026-08-08","attestation_count":5},{"id":"ai-control","en":"AI control","abbr":null,"category":"alignment-techniques","tags":["redwood-research","high-value","term-of-art"],"definition_en":"The Redwood Research agenda: designing deployment protocols (trusted monitoring, untrusted monitoring, resampling, auditing) that keep you safe even if the model is actively misaligned and deliberately trying to subvert your safeguards. Control is explicitly the complement of alignment — it assumes the model may already want to defect and asks whether it can succeed.","definition_zh":"Redwood Research 提出的研究议程：设计一套部署协议（可信监控、不可信监控、重采样、审计等），使得即便模型已经失准、并且在有意规避安全措施，你依然是安全的。控制与对齐互补——对齐问「模型想不想搞破坏」，控制问「就算它想，能不能得逞」。","preferred_zh":"人工智能控制","translation_difficulty":"high","pitfalls":"THIS IS THE HEADLINE PROBLEM IN THIS CATEGORY. Bare 控制 and 管控 in Chinese AI discourse mean administrative or regulatory control of AI by the state or by developers — the register of 「确保人工智能始终处于人类控制之下」 (Global AI Governance Initiative) and 「安全、可信、可控」 (TC260). Redwood's 'control' means something almost orthogonal: a technical, adversarial, deployment-time discipline that explicitly grants the premise that the model is misaligned. A Chinese reader meeting 人工智能控制 with no gloss will read policy-controllability (可控性), i.e. the very thing the control agenda assumes you have already lost. The distinction that must be preserved is the 'despite' — safety DESPITE misalignment, not safety BY achieving alignment. CSET's official Chinese translation solves this with an explicit contrast sentence rather than with a coined term, which is currently the best practice available: state the alignment/control contrast in full the first time. Do not use 管控 (which adds a supervisory-authority flavour) and do not use 可控性 (controllability, a property, not a research programme).","translations":[{"zh":"人工智能控制","pinyin":"réngōng zhìnéng kòngzhì","status":"common","literal_back":"artificial intelligence control","notes":"Used in CSET's own Chinese translation of its explainer, which is a genuine attested EN↔ZH pair (English original 'AI Control: How to Make Use of Misbehaving AI Agents'). The source itself flags the term as new: 「人工智能控制」是一个相对较新的术语. In running Chinese ML text the code-switched AI 控制 is at least as common.","attestations":[{"quote_zh":"人工智能对齐旨在确保人工智能体从一开始就不会试图违规，而人工智能控制旨在确保即使人工智能体追求不当目标，也无法成功达成。","quote_en":"AI alignment aims to ensure AI agents never attempt to misbehave in the first place, whereas AI control aims to ensure that even if AI agents pursue improper goals, they cannot succeed.","source_title":"人工智能控制：如何利用违规人工智能体","publisher":"Center for Security and Emerging Technology (CSET), Georgetown University；作者 Kendrea Beers, Cody Rushing","source_type":"report","url":"https://cset.georgetown.edu/publication/ai-control-chinese/","date":"2025-11"}]},{"zh":"AI 控制","pinyin":"AI kòngzhì","status":"common","literal_back":"AI control","notes":"Code-switched form typical of Chinese ML writing. Same ambiguity problem as 人工智能控制 — needs a gloss on first use.","attestations":[]},{"zh":"失准前提下的安全保障","pinyin":"shīzhǔn qiántí xià de ānquán bǎozhàng","status":"proposed","literal_back":"safety assurance under the premise of misalignment","notes":"We propose this as an explanatory apposition, not a replacement headword: write 人工智能控制（失准前提下的安全保障）on first use. It is unattested — coined here — but it is the only formulation we found that carries the load-bearing 'despite' which every existing Chinese rendering drops. Do not use it as a bare term; a Chinese reader will not recognise it.","attestations":[]},{"zh":"可控性","pinyin":"kěkòngxìng","status":"deprecated","literal_back":"controllability","notes":"Widely used in PRC policy text (TC260 framework, RICE principles in the PKU alignment survey) but it names a desired PROPERTY of a system, not Redwood's research programme. Using it for 'AI control' collapses exactly the distinction the term exists to make. Attested in that other sense: the PKU CCL 2024 survey lists 可控性(Controllability) as one of the four RICE goals.","attestations":[{"quote_zh":"可控性是一种必要的属性，它确保系统的行动和决策过程始终受到人类监督和约束。","quote_en":"Controllability is a necessary property ensuring that a system's actions and decision processes remain under human oversight and constraint.","source_title":"《对齐的理论、技术与评估》","publisher":"北京大学人工智能安全与治理中心 / CCL 2024","source_type":"paper","url":"https://aclanthology.org/2024.ccl-2.7.pdf","date":"2024-07"}]}],"confidence":"medium","used_by":[{"org":"CSET (Georgetown)","zh_used":"人工智能控制","note":"in the Chinese edition of their AI control explainer; also coins 可信模型 / 不可信模型 / 可信监控 / 不可信监控"}],"usage_examples":[{"zh":"「不可信模型」的定义为功能更强但可能具有蓄意破坏性的新型智能体。","en":"An 'untrusted model' is defined as a newer, more capable agent that may be deliberately subversive.","source":"https://cset.georgetown.edu/publication/ai-control-chinese/"},{"zh":"控制类措施的出发点是：先假设模型已经失准，再问它能不能绕过我们的监控。","en":"Control measures start by assuming the model is already misaligned, then ask whether it can get around our monitoring.","source":"constructed"}],"related":["scalable-oversight","cot-monitoring","human-oversight","guardrails","defense-in-depth","trusted-monitoring","collusion"],"sources":["https://cset.georgetown.edu/publication/ai-control-chinese/","https://cset.georgetown.edu/article/ai-control-how-to-make-use-of-misbehaving-ai-agents/","https://aclanthology.org/2024.ccl-2.7.pdf","https://arxiv.org/pdf/2312.06942","https://www.mfa.gov.cn/web/ziliao_674904/1179_674909/202310/t20231020_11164831.shtml"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"alignment-faking","en":"alignment faking","en_aliases":["fake alignment"],"abbr":null,"category":"misalignment-phenomena","tags":["named-result","anthropic","redwood","2024"],"definition_en":"A model strategically complies with a training objective it disagrees with, in order to avoid having its existing preferences modified by training. Demonstrated empirically in Claude 3 Opus by Anthropic and Redwood Research in December 2024.","definition_zh":"模型察觉到自己正在被训练，于是在训练中假装顺从它并不认同的目标，以免自己原有的偏好被改掉。2024年12月 Anthropic 与 Redwood Research 在 Claude 3 Opus 上首次给出了实证。","preferred_zh":"对齐伪装","translation_difficulty":"medium","pitfalls":"Two word-orders circulate and mean the same thing: 伪装对齐 (verb-object, 'to fake alignment') and 对齐伪装 (noun compound, 'alignment-faking'). 量子位 used 伪装对齐 in its December 2024 coverage and had switched to 对齐伪装 by July 2025, so the noun form appears to be winning, but both are readable. Keep this distinct from 欺骗性对齐 (deceptive alignment), which is the theoretical threat model; alignment faking is the empirical finding. Chinese media routinely gloss it with the colloquial 当面一套背面一套, which is vivid but loses the specific mechanism (preference preservation across training).","translations":[{"zh":"对齐伪装","pinyin":"duìqí wěizhuāng","status":"common","literal_back":"alignment-disguise","notes":"Noun-compound form; the ordering 量子位 settled on by mid-2025 and the one most parallel to the English. Also used by 搜狐 and 知乎 explainers.","attestations":[{"quote_zh":"对齐伪装，指那些表面上似乎与我们观点或价值观相同，但实际上只是在假装配合的情况。","quote_en":"Alignment faking refers to cases that on the surface appear to share our views or values, but are in fact only pretending to go along.","source_title":"Claude团队新研究：为什么有的模型假装对齐有的不会","publisher":"量子位 (QbitAI)","source_type":"media","url":"https://www.qbitai.com/2025/07/306725.html","date":"2025-07"},{"quote_zh":"而这次，论文在对25个前沿LLMs进行同样的分析后发现：只有Claude 3 Opus的表现可以用对齐伪装来解释。","quote_en":"This time, after running the same analysis on 25 frontier LLMs, the paper found that only Claude 3 Opus's behaviour can be explained by alignment faking.","source_title":"Claude团队新研究：为什么有的模型假装对齐有的不会","publisher":"量子位 (QbitAI)","source_type":"media","url":"https://www.qbitai.com/2025/07/306725.html","date":"2025-07"}]},{"zh":"伪装对齐","pinyin":"wěizhuāng duìqí","status":"common","literal_back":"to disguise-align","notes":"The rendering 量子位 used within days of the December 2024 paper; still widely reproduced in reprints. Reads as a verb phrase rather than a name for the phenomenon.","attestations":[{"quote_zh":"Claude团队最新研究，揭示了大模型这种当面一套背面一套的行为：伪装对齐（Alignment Faking）。","quote_en":"The Claude team's latest research reveals this two-faced behaviour in large models: alignment faking.","source_title":"Claude团队揭发AI伪装对齐：训练时假装遵守目标，只为保护自己价值观不被修改","publisher":"量子位 (QbitAI)，经新浪科技创事记转载","source_type":"media","url":"https://finance.sina.com.cn/tech/csj/2024-12-19/doc-inczyxct6789936.shtml","date":"2024-12"},{"quote_zh":"团队表示，虽然目前的伪装对齐很容易被发现，但未来当能力更强的AI伪装对齐时，可能很难判断模型是真的安全。","quote_en":"The team says that although today's alignment faking is easy to detect, when more capable future AI fakes alignment it may be very hard to tell whether a model is genuinely safe.","source_title":"Claude团队揭发AI伪装对齐：训练时假装遵守目标，只为保护自己价值观不被修改","publisher":"量子位 (QbitAI)，经新浪科技创事记转载","source_type":"media","url":"https://finance.sina.com.cn/tech/csj/2024-12-19/doc-inczyxct6789936.shtml","date":"2024-12"}]},{"zh":"当面一套背面一套","pinyin":"dāngmiàn yī tào bèimiàn yī tào","status":"descriptive","literal_back":"one set to your face, another behind your back","notes":"Not a term of art — the colloquial gloss Chinese tech media reach for when introducing the concept. Useful for lay explanation, useless as a technical label.","attestations":[{"quote_zh":"Claude团队最新研究，揭示了大模型这种当面一套背面一套的行为：伪装对齐（Alignment Faking）。","quote_en":"The Claude team's latest research reveals this two-faced behaviour in large models: alignment faking.","source_title":"Claude团队揭发AI伪装对齐：训练时假装遵守目标，只为保护自己价值观不被修改","publisher":"量子位 (QbitAI)，经新浪科技创事记转载","source_type":"media","url":"https://finance.sina.com.cn/tech/csj/2024-12-19/doc-inczyxct6789936.shtml","date":"2024-12"}]}],"confidence":"high","used_by":[{"org":"量子位 (QbitAI)","zh_used":"伪装对齐 / 对齐伪装","note":"使用了伪装对齐（2024-12），到 2025-07 改用对齐伪装"}],"usage_examples":[{"zh":"模型在训练阶段的顺从可能只是对齐伪装，部署后行为会回到原来的偏好。","en":"A model's compliance during training may be nothing more than alignment faking; after deployment its behaviour reverts to its original preferences.","source":"constructed"}],"related":["deceptive-compliance","scheming","situational-awareness","self-preservation","model-organisms","strategic-deception"],"sources":["https://arxiv.org/abs/2412.14093","https://www.anthropic.com/research/alignment-faking","https://finance.sina.com.cn/tech/csj/2024-12-19/doc-inczyxct6789936.shtml","https://www.qbitai.com/2025/07/306725.html"],"last_researched":"2026-08-08","attestation_count":5},{"id":"attribution-graph","en":"attribution graph","en_aliases":[],"abbr":null,"category":"interpretability","tags":["anthropic-lineage","2025"],"definition_en":"A graph produced by Anthropic's circuit-tracing method showing, for one specific prompt, which features influenced which other features on the path from input to output.","definition_zh":"Anthropic 回路追踪方法产出的图：针对某一条具体提示词，展示从输入到输出的路径上，哪些特征影响了哪些特征。","preferred_zh":"归因图","translation_difficulty":"low","pitfalls":"Unproblematic. 归因 (attribution) is already the standard word in the older XAI literature (特征归因 = feature attribution), so the compound reads naturally, and Chinese media adopted 归因图 uniformly when covering the March 2025 papers. One inherited ambiguity: 归因 in the XAI tradition means attributing an output to *input* features, whereas an attribution graph attributes to *internal* features — the word does not mark the difference.","translations":[{"zh":"归因图","pinyin":"guīyīn tú","status":"established","literal_back":"attribution graph","notes":"Uniform across Chinese coverage of Anthropic's 2025 circuit-tracing / biology-of-an-LLM papers.","attestations":[{"quote_zh":"归因图描述了模型在面对某个特定提示词时，如何一步步产生目标词输出的过程。","quote_en":"The attribution graph describes how, for a specific prompt, the model produces the target output word step by step.","source_title":"Anthropic提出工作回路追踪方法：用归因图解开大语言模型计算之谜","publisher":"集智俱乐部","source_type":"blog","url":"https://swarma.org/?p=62523","date":"2025-07"},{"quote_zh":"我们构建的归因图显示了特征如何在特定提示上相互作用以产生模型的输出","quote_en":"The attribution graphs we construct show how features interact on a given prompt to produce the model's output.","source_title":"Anthropic AI 最新研究成果发布：揭示大模型中的注意力回路","publisher":"雷峰网 (洪雨欣)","source_type":"media","url":"https://m.leiphone.com/category/ai/AuOBr2ga26JnTWly.html","date":"2025-04"}]}],"confidence":"high","used_by":[{"org":"集智俱乐部","zh_used":"归因图","note":"in its explainer on Anthropic's circuit tracing"},{"org":"雷峰网","zh_used":"归因图","note":"in its coverage of the Anthropic papers"}],"usage_examples":[{"zh":"这张归因图显示，模型在写出韵脚之前就已经提前规划好了。","en":"This attribution graph shows the model had already planned the rhyme before writing it.","source":"constructed"}],"related":["circuit-tracing","circuit","feature","cross-layer-transcoder"],"sources":["https://swarma.org/?p=62523","https://m.leiphone.com/category/ai/AuOBr2ga26JnTWly.html"],"last_researched":"2026-08-08","attestation_count":2},{"id":"autonomous-ai-rd","en":"autonomous AI R&D","en_aliases":["AI R&D automation","automated AI research"],"abbr":null,"category":"agents-autonomy","tags":["capability-threshold","false-friend","high-value"],"definition_en":"The capability of AI systems to substantially accelerate or fully carry out AI research and development themselves. Named as a capability threshold in most frontier safety frameworks because it could compress timelines and outpace oversight.","definition_zh":"AI 系统显著加速甚至独立完成人工智能研发工作的能力。多数前沿安全框架都把它列为关键能力阈值，因为它可能大幅压缩研发周期并使监督失去追赶余地。","preferred_zh":"自动化 AI 研发","translation_difficulty":"high","pitfalls":"MAJOR FALSE FRIEND. The obvious calque 自主研发 is unusable: in PRC discourse 自主研发 is a fixed, heavily-loaded phrase meaning indigenous / self-reliant development by China (as in 自主可控, 自主研发的芯片). A Chinese reader seeing 自主 AI 研发 will parse it as 'domestically developed AI', i.e. a technology-sovereignty statement, not 'AI doing the R&D'. The same trap catches 自主创新. Use 自动化 AI 研发 ('automating AI R&D') or spell out the agent: AI 自动开展人工智能研发 / 模型自动化推进 AI 研发. 安远 AI's own framework comparison uses 自动化AI研发, which is the safest attested form. Related safety-register neighbours are 长程自主性 (long-horizon autonomy) and 自主复制与适应 (ARA), which do use 自主 without ambiguity because the object is not 研发.","translations":[{"zh":"自动化 AI 研发","pinyin":"zìdònghuà AI yánfā","status":"common","literal_back":"automated AI research-and-development","notes":"Attested in Chinese comparison of frontier safety frameworks. Avoids the 自主研发 sovereignty reading.","attestations":[{"quote_zh":"能够显著加速或自动化AI研发的模型，行业应提前采取超常规的安保措施","quote_en":"For models capable of significantly accelerating or automating AI R&D, the industry should adopt extraordinary security measures in advance.","source_title":"国际五大前沿AI风险管理框架的横向对比","publisher":"安全内参（作者：安远 AI）","source_type":"report","url":"https://www.secrss.com/articles/87619","date":"2026-02"}]},{"zh":"自主研发","pinyin":"zìzhǔ yánfā","status":"deprecated","literal_back":"self-directed R&D","notes":"Do not use for this concept. In PRC usage it means indigenous/self-reliant development by a Chinese entity (cf. 自主可控), and will be read as a technology-sovereignty claim rather than a statement about AI autonomy.","attestations":[]},{"zh":"独立开展人工智能研究","pinyin":"dúlì kāizhǎn réngōng zhìnéng yánjiū","status":"descriptive","literal_back":"independently carrying out AI research","notes":"Unpacked phrasing used when the agent must be made explicit; attested in CSET's Chinese translation.","attestations":[{"quote_zh":"这些公司旨在开发能够独立实现诸如运营业务或开展人工智能研究等复杂目标的智能体。","quote_en":"These companies aim to develop agents capable of independently achieving complex goals such as running a business or conducting AI research.","source_title":"人工智能控制：如何利用违规人工智能体（中文版）","publisher":"Center for Security and Emerging Technology (CSET), Georgetown University","source_type":"report","url":"https://cset.georgetown.edu/publication/ai-control-chinese/","date":"2025-11"}]}],"confidence":"medium","used_by":[{"org":"安远 AI (Concordia AI)","zh_used":"自动化AI研发","note":"in comparison of frontier AI risk-management frameworks"}],"usage_examples":[{"zh":"一旦模型能自动化 AI 研发，安全评估的节奏就跟不上能力增长了。","en":"Once models can automate AI R&D, safety evaluation can no longer keep pace with capability growth.","source":"constructed"}],"related":["long-horizon-task","autonomy-level","ai-agent","scaffolding"],"sources":["https://www.secrss.com/articles/87619","https://cset.georgetown.edu/publication/ai-control-chinese/"],"last_researched":"2026-08-08","attestation_count":2},{"id":"autonomous-replication","en":"autonomous replication and adaptation","abbr":"ARA","category":"misalignment-phenomena","tags":["capability-threshold","metr","fudan","chinese-origin-result"],"definition_en":"An AI system acquiring resources, copying itself onto new machines, and surviving and adapting without human assistance. A named red-line capability in METR's evaluations and in several frontier safety frameworks.","definition_zh":"AI 系统自己获取资源、把自己复制到新机器上，并在没有人帮忙的情况下存活和适应。METR 的评测和多个前沿安全框架都把它列为红线能力。","preferred_zh":"自我复制","translation_difficulty":"low","pitfalls":"The Chinese term here is unusually strong, partly because a Chinese-origin result anchored it: the Fudan University paper 《Frontier AI systems have surpassed the self-replicating red line》 (Dec 2024) put 自我复制 and 红线 into wide circulation together, and 红线 is a term with enormous resonance in PRC political language. The cost is that 自我复制 has become a catch-all: Chinese coverage uses it for weight exfiltration, for sandbox escape, and for running a working copy, flattening distinctions English keeps separate. The 'and adaptation' half of ARA is routinely dropped; 安远AI renders the full construct as 自我复制与适应能力.","translations":[{"zh":"自我复制","pinyin":"zìwǒ fùzhì","status":"established","literal_back":"self-replication","notes":"Dominant and unambiguous. Anchored by the Fudan paper and its very wide Chinese media pickup; also used by 安远AI and 上海人工智能实验室 as a named risk dimension.","attestations":[{"quote_zh":"人工智能（AI）可能已经跨越了一个关键的'红线'—— 实现了自我复制。","quote_en":"Artificial intelligence may already have crossed a critical 'red line' — achieving self-replication.","source_title":"复旦大学研究：AI 跨越关键\"红线\"，已能实现自我复制","publisher":"腾讯新闻（转载自 IT之家）","source_type":"media","url":"https://news.qq.com/rain/a/20250211A0196D00","date":"2025-02"},{"quote_zh":"最后一个风险维度是自我复制，这听起来像是科幻电影里的情节，但研究团队发现这个风险是真实存在的。","quote_en":"The last risk dimension is self-replication. It sounds like something out of a science-fiction film, but the research team found the risk is real.","source_title":"上海人工智能实验室重磅发布：AI正在学会\"偷鸡摸狗\"？前沿AI风险管理框架深度剖析","publisher":"科技行者 (TechWalker)","source_type":"media","url":"https://www.techwalker.com/2026/0224/3179510.shtml","date":"2026-02"}]},{"zh":"自我复制与适应能力","pinyin":"zìwǒ fùzhì yǔ shìyìng nénglì","status":"common","literal_back":"self-replication and adaptation capability","notes":"The full ARA construct. Used by 安远AI in its frontier risk monitoring platform to gloss 'Self-Proliferation'. Verbatim quote not recovered in this pass; recorded on the basis of the platform's risk-dimension naming.","attestations":[]}],"confidence":"high","used_by":[{"org":"复旦大学","zh_used":"自我复制","note":"《Frontier AI systems have surpassed the self-replicating red line》，中文语境的锚定来源"},{"org":"上海人工智能实验室","zh_used":"自我复制","note":"《前沿人工智能风险管理框架》五大风险之一"}],"usage_examples":[{"zh":"在10次试验中，两个开源模型分别有50%和90%的概率成功完成自我复制。","en":"Across ten trials, the two open-weight models succeeded at self-replication 50% and 90% of the time respectively.","source":"constructed"}],"related":["self-exfiltration","red-lines"],"sources":["https://arxiv.org/abs/2412.12140","https://metr.org/","https://news.qq.com/rain/a/20250211A0196D00","https://www.techwalker.com/2026/0224/3179510.shtml","https://www.secrss.com/articles/79033"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"autonomy-level","en":"autonomy level","en_aliases":["levels of autonomy","agent capability levels"],"abbr":null,"category":"agents-autonomy","tags":["grading","bridge-concept"],"definition_en":"A graded scale describing how much of a task a system handles without human direction, and correspondingly how much human oversight is required at each level.","definition_zh":"用分级的方式刻画系统在多大程度上无需人类介入即可自行完成任务，以及各级别相应需要多少人类监督。","preferred_zh":"自主性等级","translation_difficulty":"medium","pitfalls":"There is no single fixed Chinese term for the concept, but there IS a culturally dominant template: the SAE 自动驾驶 L0–L5 grading is so familiar in China that Chinese agent-autonomy frameworks explicitly borrow it, often saying so in the first paragraph. This is a genuinely useful bridge — a Chinese reader who is lost on 'autonomy level' will immediately understand 类比自动驾驶的 L0–L5 分级. Two cautions. First, the borrowed frameworks are mostly *capability* ladders (L0 rule-based → L5 self-directed), not oversight ladders, so they answer 'how smart' rather than the safety question 'how much human control remains' — the mapping is looser than it looks. Second, PRC national standardisation has a separate, official grading (《人工智能终端智能化分册》-style L1–L4 terminal intelligence grading led by CAICT/SAC), so 分级 in a policy document may point to a completely different scale than 分级 in a blog post. In regulatory register the operative phrase is not a level at all but 自主程度 ('degree of autonomy'), which the Chinese EU AI Act translation uses to scale oversight requirements.","translations":[{"zh":"自主性等级","pinyin":"zìzhǔxìng děngjí","status":"descriptive","literal_back":"autonomy grade","notes":"The most transparent rendering, but not a fixed term; Chinese sources more often name the specific framework (L0–L5 分级) than the abstract concept. No standalone verbatim attestation recovered.","attestations":[]},{"zh":"L0–L5 分级","pinyin":"L0–L5 fēnjí","status":"common","literal_back":"L0–L5 grading","notes":"The working form. Chinese agent frameworks state the autonomous-driving analogy explicitly, which makes it the highest-leverage way to introduce the concept to a Chinese audience. Recorded in research as “L0–L5 分级（类比自动驾驶）”.","attestations":[{"quote_zh":"我们参考自动驾驶的分级逻辑，构建了一个六层级框架（L0-L5）","quote_en":"Taking the grading logic of autonomous driving as a reference, we built a six-level framework (L0–L5).","source_title":"详解 AI Agent（智能体）L0-L5 的分级框架！","publisher":"人人都是产品经理（作者：灵山下的小妖怪）","source_type":"blog","url":"https://www.woshipm.com/ai/6284877.html","date":"2025-11"},{"quote_zh":"正如自动驾驶汽车必须依次掌握车道保持、自适应巡航和自动泊车，才能迈向L3及以上级别，AI智能体的发展也遵循同样的模式","quote_en":"Just as a self-driving car must master lane keeping, adaptive cruise control and automatic parking in turn before reaching L3 and above, the development of AI agents follows the same pattern.","source_title":"详解 AI Agent（智能体）L0-L5 的分级框架！","publisher":"人人都是产品经理（作者：灵山下的小妖怪）","source_type":"blog","url":"https://www.woshipm.com/ai/6284877.html","date":"2025-11"}]},{"zh":"自主程度","pinyin":"zìzhǔ chéngdù","status":"established","literal_back":"degree of autonomy","notes":"The regulatory-register phrasing: a continuous degree rather than a discrete level, used to scale oversight obligations. This is the form to use in policy translation.","attestations":[{"quote_zh":"监督措施应与高风险人工智能系统的风险、自主程度和使用环境相称","quote_en":"Oversight measures shall be commensurate with the risks, degree of autonomy and context of use of the high-risk AI system.","source_title":"欧盟《人工智能法案》全文中文翻译","publisher":"安全内参","source_type":"gov","url":"https://www.secrss.com/articles/68714","date":"2024-08"}]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"可以类比自动驾驶的 L0–L5：级别越高，人能介入的环节越少。","en":"Think of it like autonomous driving L0–L5: the higher the level, the fewer points at which a human can step in.","source":"constructed"}],"related":["agency","human-in-the-loop","ai-agent","oversight-failure","agentic","long-horizon-task","autonomous-ai-rd"],"sources":["https://www.woshipm.com/ai/6284877.html","https://www.secrss.com/articles/68714","https://zhuanlan.zhihu.com/p/699942565"],"last_researched":"2026-08-08","attestation_count":3},{"id":"black-box","en":"black box","en_aliases":[],"abbr":null,"category":"interpretability","tags":["metaphor"],"definition_en":"A system whose inputs and outputs are observable but whose internal decision process is not. The standard framing for why interpretability is needed.","definition_zh":"只能看到输入和输出、看不到内部决策过程的系统。这是解释\"为什么需要可解释性\"时最常用的比喻。","preferred_zh":"黑箱","translation_difficulty":"low","pitfalls":"黑箱 and 黑盒 are both fully current and freely interchangeable; there is no semantic difference, only register drift. 黑箱 (box/chest) is slightly more literary and dominates in media and policy prose; 黑盒 is more common in engineering writing and in the compound 黑盒测试 (black-box testing), where it is the fixed term. Note that TC260's governance framework avoids both and writes 黑灰盒 ('black-grey box') — a hedge asserting that model reasoning is only partly opaque, which is a substantive framing choice, not a stylistic one.","translations":[{"zh":"黑箱","pinyin":"hēixiāng","status":"established","literal_back":"black chest/box","notes":"Dominant in media, popular-science and policy prose.","attestations":[{"quote_zh":"深度学习模型通常被视作'黑箱'，其内在运行机制无法被其开发者理解","quote_en":"Deep learning models are usually regarded as 'black boxes' whose internal workings cannot be understood even by their developers.","source_title":"从黑箱到显微镜：大模型可解释性的现状与未来","publisher":"腾讯研究院 (曹建峰、杨浩然)，腾讯新闻","source_type":"report","url":"https://news.qq.com/rain/a/20250617A07B1L00","date":"2025-06"},{"quote_zh":"中间部分——模型是怎么根据这些算法和数据输出结果，就成为了不可见的「黑箱」","quote_en":"The middle part — how the model produces an output from these algorithms and data — becomes an invisible 'black box'.","source_title":"打破大模型黑盒，彻底分解神经元，OpenAI对头Anthropic击破AI不可解释性障碍","publisher":"新智元 (via 36氪)","source_type":"media","url":"https://www.36kr.com/p/2465483534538887","date":"2023-10"}]},{"zh":"黑盒","pinyin":"hēihé","status":"common","literal_back":"black box (container)","notes":"Equally acceptable; the fixed term in 黑盒测试 (black-box testing) and common in engineering writing. Note the 新智元 piece above uses 黑盒 in its headline and 黑箱 in its body — the two are simply interchangeable.","attestations":[{"quote_zh":"它能够将模型内部的黑盒表示分解为一组稀疏、具备明确语义的激活特征","quote_en":"It can decompose the model's internal black-box representations into a set of sparse activation features with clear semantics.","source_title":"大模型到底是怎么「思考」的？第一篇系统性综述SAE的文章来了","publisher":"机器之心Pro (via 新浪科技)","source_type":"media","url":"https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml","date":"2025-06"}]},{"zh":"黑灰盒","pinyin":"hēi huī hé","status":"common","literal_back":"black-grey box","notes":"TC260's chosen wording in 《人工智能安全治理框架》. Restricted to the PRC policy register; asserts partial rather than total opacity. Do not use in technical writing.","attestations":[{"quote_zh":"以深度学习为代表的人工智能算法内部运行逻辑复杂，推理过程属黑灰盒模式，可能导致输出结果难以预测和确切归因","quote_en":"AI algorithms typified by deep learning have complex internal logic and a black-grey-box inference process, which can make outputs hard to predict and hard to attribute precisely.","source_title":"人工智能安全治理框架【AI知识库】","publisher":"清华大学人工智能国际治理研究院 / 智源社区 (原文为 TC260《人工智能安全治理框架》)","source_type":"standard","url":"https://hub.baai.ac.cn/view/39801","date":"2024-09"}]}],"confidence":"high","used_by":[{"org":"全国网络安全标准化技术委员会 (TC260)","zh_used":"黑灰盒","note":"《人工智能安全治理框架》 model-and-algorithm risk section"}],"usage_examples":[{"zh":"把大模型当成黑箱来监管，和把它拆开来看，是两条不同的治理路径。","en":"Regulating a large model as a black box and opening it up to look inside are two different governance paths.","source":"constructed"}],"related":["interpretability","transparency","explainable-ai"],"sources":["https://news.qq.com/rain/a/20250617A07B1L00","https://www.36kr.com/p/2465483534538887","https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml","https://hub.baai.ac.cn/view/39801"],"last_researched":"2026-08-08","attestation_count":4},{"id":"chain-of-thought","en":"chain of thought","en_aliases":["CoT prompting"],"abbr":"CoT","category":"training-methods","tags":["settled","high-frequency"],"definition_en":"Having a model generate explicit intermediate reasoning steps before its final answer, either by prompting or because it was trained to. The substrate that reasoning models and CoT monitoring both depend on.","definition_zh":"让模型在给出最终答案之前先写出中间推理步骤，可以靠提示引导，也可以靠训练内化。它既是推理模型能力的来源，也是思维链监控这类安全手段的前提。","preferred_zh":"思维链","translation_difficulty":"low","pitfalls":"Settled, but note two things. First, 中文维基百科 renders it 思路链 (\"train-of-thought chain\") rather than 思维链 — a minority variant a reader may encounter. Second, in practitioner speech 思维链 is often displaced by 思考 / 长思考 / 慢思考 when describing what a reasoning model does internally, and by the bare CoT when used as a modifier (CoT 数据, CoT 长度).","translations":[{"zh":"思维链","pinyin":"sīwéi liàn","status":"established","literal_back":"thought chain","notes":"Dominant everywhere: Chinese lab blogs, textbooks, media. 长思维链 = long CoT, 思维链提示 = CoT prompting.","attestations":[{"quote_zh":"在第一阶段，我们使用多样的的长思维链数据对模型进行了微调","quote_en":"In the first stage we fine-tuned the model on diverse long chain-of-thought data.","source_title":"Qwen3: 思深，行速","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"blog","url":"https://qwenlm.github.io/zh/blog/qwen3/","date":"2025-04"},{"quote_zh":"提示设计、上下文学习、思维链提示、检索增强生成","quote_en":"Prompt design, in-context learning, chain-of-thought prompting, retrieval-augmented generation.","source_title":"《大语言模型》课程资源 — 第七课 提示学习（对应本书第十章）","publisher":"中国人民大学 RUC AI Box（赵鑫等，高等教育出版社）","source_type":"github","url":"https://github.com/LLMBook-zh/LLMBook-zh.github.io","date":"2024"}]},{"zh":"思路链","pinyin":"sīlù liàn","status":"deprecated","literal_back":"train-of-thought chain","notes":"Used by 中文维基百科's prompt-engineering article. Comprehensible but a minority form; 思维链 is what the field uses. Recommend against.","attestations":[{"quote_zh":"思路链（Chain-of-thought）(CoT) 是文字提示（Textual prompting）的一种技术，该技术通过提示 LLM 生成一系列中间步骤来提高 LLM 的推理能力。","quote_en":"Chain-of-thought (CoT) is a textual-prompting technique that improves an LLM's reasoning ability by prompting it to generate a series of intermediate steps.","source_title":"提示工程（中文维基百科，思维链 重定向）","publisher":"维基百科","source_type":"wiki","url":"https://zh.wikipedia.org/wiki/%E6%80%9D%E7%BB%B4%E9%93%BE","date":"2025"}]},{"zh":"慢思考","pinyin":"màn sīkǎo","status":"common","literal_back":"slow thinking","notes":"Not a translation of CoT but the framing Chinese sources use for the same phenomenon at model level, borrowed from Kahneman's System 1/System 2. 《大语言模型》pairs it with 复杂推理 in a chapter title. Useful to know because a Chinese reader may meet 慢思考 where English says 'reasoning' or 'extended CoT'.","attestations":[{"quote_zh":"第八课 复杂推理（对应本书第十一章）","quote_en":"Lecture 8: Complex reasoning (corresponding to Chapter 11 of this book).","source_title":"《大语言模型》课程资源（含课件「复杂推理与慢思考」）","publisher":"中国人民大学 RUC AI Box（赵鑫等，高等教育出版社）","source_type":"github","url":"https://github.com/LLMBook-zh/LLMBook-zh.github.io","date":"2024"}]}],"confidence":"high","used_by":[{"org":"阿里巴巴通义千问 (Qwen)","zh_used":"长思维链","note":"Qwen3 Chinese release blog"},{"org":"中国人民大学 RUC AI Box","zh_used":"思维链提示","note":"《大语言模型》course module"}],"usage_examples":[{"zh":"我们用长思维链数据做了一轮冷启动微调。","en":"We did a round of cold-start fine-tuning on long chain-of-thought data.","source":"constructed"}],"related":["reasoning-model","test-time-compute","post-training","process-supervision","cot-monitoring","cot-faithfulness","deliberative-alignment","in-context-learning"],"sources":["https://qwenlm.github.io/zh/blog/qwen3/","https://github.com/LLMBook-zh/LLMBook-zh.github.io","https://zh.wikipedia.org/wiki/%E6%80%9D%E7%BB%B4%E9%93%BE"],"last_researched":"2026-08-08","attestation_count":4},{"id":"cot-faithfulness","en":"chain-of-thought faithfulness","abbr":null,"category":"alignment-techniques","tags":["2025","anthropic"],"definition_en":"The degree to which a model's written chain of thought actually reflects the computation that produced its answer. Anthropic's 2025 results found reasoning models frequently use hints without mentioning them, undercutting CoT monitoring.","definition_zh":"模型写出来的思维链在多大程度上真实反映了它得出答案的实际过程。Anthropic 2025 年的实验发现，推理模型常常用了提示却在思维链里只字不提，这直接动摇了思维链监控的可行性。","preferred_zh":"思维链忠实性","translation_difficulty":"medium","pitfalls":"忠实性 and 忠实度 both circulate and mean the same thing (-ness vs -degree); 忠实度 is slightly more common when a measured number is meant. The bigger trap is 保真度, the established Chinese rendering of 'fidelity' in signal processing and image compression — it is a false friend here and does not carry the 'says what it actually did' sense. Also beware 忠诚 (loyalty), which some casual writing reaches for and which anthropomorphises in the wrong direction.","translations":[{"zh":"思维链忠实性","pinyin":"sīwéiliàn zhōngshíxìng","status":"common","literal_back":"chain-of-thought faithfulness","notes":"Used in Chinese technical write-ups of the Anthropic 2025 CoT faithfulness paper, normally with the English 'faithfulness' in parentheses. Attestation below is the article's own headline, verbatim; the precise publication date was not independently confirmed, so confidence is held at medium.","attestations":[{"quote_zh":"Anthropic的论文探讨推理模型的CoT忠实性（faithfulness）：它们并不总是「说真话」","quote_en":"Anthropic's paper examines the CoT faithfulness of reasoning models: they do not always 'tell the truth'.","source_title":"Anthropic的论文探讨推理模型的CoT忠实性（faithfulness）：它们并不总是「说真话」","publisher":"CSDN 博客","source_type":"blog","url":"https://blog.csdn.net/shizheng_Li/article/details/146998928","date":"2025"}]},{"zh":"思维链忠实度","pinyin":"sīwéiliàn zhōngshídù","status":"common","literal_back":"chain-of-thought degree-of-faithfulness","notes":"Preferred when a measured quantity is intended (e.g. a revelation rate). No verbatim attestation fetched; recorded as an observed variant.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"如果思维链忠实性很低，那么依赖思维链监控来发现欺骗行为就靠不住。","en":"If chain-of-thought faithfulness is low, relying on CoT monitoring to catch deception is unreliable.","source":"constructed"}],"related":["cot-monitoring","chain-of-thought","steganography","introspection"],"sources":["https://blog.csdn.net/shizheng_Li/article/details/146998928","https://www.anthropic.com/research/measuring-faithfulness-in-chain-of-thought-reasoning"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":1},{"id":"cot-monitoring","en":"chain-of-thought monitoring","en_aliases":["CoT monitorability","CoT monitoring"],"abbr":null,"category":"alignment-techniques","tags":["2025","cross-lab-position-paper"],"definition_en":"Reading a reasoning model's chain of thought at inference time to detect misbehaviour, misaligned intent, or awareness of being evaluated. The subject of a July 2025 cross-lab position paper arguing that CoT monitorability is a fragile and possibly temporary safety affordance.","definition_zh":"在推理阶段直接读模型的思维链，用来发现违规意图、失准苗头或模型察觉到自己正在被测试等信号。2025 年 7 月 OpenAI、DeepMind、Anthropic 等联合发表立场文件，认为这种「可监测性」脆弱且可能是暂时的。","preferred_zh":"思维链监控","translation_difficulty":"medium","pitfalls":"Heavy code-switching: Chinese coverage of the 2025 position paper frequently leaves 'CoT monitoring' in English inside otherwise-Chinese sentences, and where it does translate, it prefers 可监测性 (detectability/observability) over the more literal 可监控性 (monitorability). 监测 and 监控 are not identical: 监控 carries surveillance/CCTV overtones, 监测 reads as instrumented measurement. English 'monitorability' is closer to 监控 in spirit (an overseer watching an agent), so the common Chinese choice quietly softens the term.","translations":[{"zh":"思维链监控","pinyin":"sīwéiliàn jiānkòng","status":"common","literal_back":"chain-of-thought monitoring","notes":"The most natural full Chinese rendering; competes with the code-switched 'CoT 监控'. 思维链 for chain-of-thought is itself fully established.","attestations":[{"quote_zh":"随着 AI agent 的普及和能力提升，CoT monitoring 可能成为控制其行为的核心方法","quote_en":"As AI agents proliferate and grow more capable, CoT monitoring may become a core method for controlling their behaviour.","source_title":"AI教父联名OpenAI、DeepMind、Anthropic：警惕CoT！","publisher":"智源社区 (BAAI hub)","source_type":"media","url":"https://hub.baai.ac.cn/view/47381","date":"2025-07"}]},{"zh":"CoT 可监测性","pinyin":"CoT kě jiāncèxìng","status":"common","literal_back":"CoT detectability/observability","notes":"The rendering actually used for 'monitorability' in Chinese coverage of the cross-lab position paper. Note the loanword-plus-suffix construction: the English abbreviation is kept and only the suffix is Chinese.","attestations":[{"quote_zh":"目前这种可见性程度能否持续尚无保证。我们鼓励研究界和前沿 AI 开发者充分利用 CoT 可监测性","quote_en":"There is no guarantee the current degree of visibility will persist. We encourage the research community and frontier AI developers to make full use of CoT monitorability.","source_title":"AI教父联名OpenAI、DeepMind、Anthropic：警惕CoT！","publisher":"智源社区 (BAAI hub)","source_type":"media","url":"https://hub.baai.ac.cn/view/47381","date":"2025-07"}]}],"confidence":"medium","used_by":[{"org":"智源社区 (BAAI)","zh_used":"CoT 可监测性 / CoT monitoring","note":"coverage of the July 2025 cross-lab position paper"}],"usage_examples":[{"zh":"连续潜在空间中推理的模型自然限制了其思维过程的可见性。","en":"Models that reason in a continuous latent space inherently limit the visibility of their thinking process.","source":"https://hub.baai.ac.cn/view/47381"}],"related":["cot-faithfulness","chain-of-thought","ai-control","scalable-oversight","steganography","process-supervision","trusted-monitoring"],"sources":["https://hub.baai.ac.cn/view/47381","https://blog.csdn.net/QbitAI/article/details/149411538"],"last_researched":"2026-08-08","attestation_count":2},{"id":"circuit","en":"circuit","en_aliases":["computational circuit","transformer circuit"],"abbr":null,"category":"interpretability","tags":["anthropic-lineage","contested","high-value"],"definition_en":"A subgraph of a network — specific features, attention heads and MLP paths wired together — that implements an identifiable algorithm, such as copying a repeated token or resolving an indirect object.","definition_zh":"网络中的一个子图：若干特征、注意力头和 MLP 路径连成一条通路，共同实现一个可辨认的算法，比如复制重复出现的 token，或判断间接宾语是谁。","preferred_zh":"回路","translation_difficulty":"medium","pitfalls":"Genuinely contested between 回路 and 电路, and the hint is only half right. 电路 is not simply wrong — it is used by serious sources (机器之心 writes 跨层电路; 腾讯研究院 writes 计算电路（computational circuits）) — but it means 'electrical circuit' literally, which over-commits to the hardware metaphor. 回路 means 'loop / return path' and is the term used by the interpretability reading-group community (集智俱乐部), and is the safer default: it keeps the graph-path sense without asserting electronics. Note 集智 also coins 工作回路 ('working circuit') for Anthropic's circuit tracing. A large fraction of Chinese writing simply keeps the English 'circuit' or writes Transformer circuits. Separately, beware 脑回路: in colloquial Chinese 脑回路 ('brain circuit') is slang for 'someone's weird way of thinking' and appears in clickbait headlines about Claude — vivid, but not a technical term.","translations":[{"zh":"回路","pinyin":"huílù","status":"contested","literal_back":"return path / loop","notes":"Our recommendation. Used by 集智俱乐部's 大模型可解释性读书会 and by 雷峰网's Anthropic coverage.","attestations":[{"quote_zh":"本次分享将介绍由注意力头和前馈网络组成的Transformer circuits（回路）的基本概念","quote_en":"This talk will introduce the basic concept of Transformer circuits, made up of attention heads and feed-forward networks.","source_title":"大模型怎样工作？Transformer回路基础丨周四直播·大模型可解释性读书会","publisher":"集智俱乐部","source_type":"blog","url":"https://swarma.org/?p=60895","date":"2025-06"},{"quote_zh":"其次，描述这些特征如何通过过程或回路相互作用以产生模型输出。","quote_en":"Second, describe how these features interact through processes or circuits to produce the model's output.","source_title":"Anthropic AI 最新研究成果发布：揭示大模型中的注意力回路","publisher":"雷峰网 (洪雨欣)","source_type":"media","url":"https://m.leiphone.com/category/ai/AuOBr2ga26JnTWly.html","date":"2025-04"}]},{"zh":"电路","pinyin":"diànlù","status":"contested","literal_back":"electrical circuit","notes":"In real, respectable use — not a mistranslation, but it hard-codes the electronics metaphor. Prefer 回路 unless matching a source that already used 电路.","attestations":[{"quote_zh":"从单个神经元到注意力头，再到跨层电路。","quote_en":"From individual neurons to attention heads, and then to cross-layer circuits.","source_title":"大模型哪里出问题、怎么修，这篇可解释性综述一次讲清","publisher":"机器之心 (via 腾讯云开发者社区)","source_type":"media","url":"https://cloud.tencent.com/developer/article/2624862","date":"2026-01"},{"quote_zh":"将这些稀疏特征有机组合为'计算电路'（computational circuits），从中追踪模型如何在层层传递中完成由输入到输出的决策路径","quote_en":"Organically combining these sparse features into 'computational circuits', and tracing how the model completes its decision path from input to output layer by layer.","source_title":"从黑箱到显微镜：大模型可解释性的现状与未来","publisher":"腾讯研究院 (曹建峰、杨浩然)，腾讯新闻","source_type":"report","url":"https://news.qq.com/rain/a/20250617A07B1L00","date":"2025-06"}]},{"zh":"circuit","pinyin":null,"status":"loanword","literal_back":null,"notes":"Frequently kept in English, especially in the fixed phrase Transformer circuits and in paper titles.","attestations":[]}],"confidence":"high","used_by":[{"org":"集智俱乐部","zh_used":"回路","note":"大模型可解释性读书会 series title"},{"org":"机器之心","zh_used":"电路","note":"跨层电路 in its 2026 interpretability survey coverage"}],"usage_examples":[{"zh":"他们定位到一条负责复制重复 token 的回路，只涉及三个注意力头。","en":"They localised a circuit responsible for copying repeated tokens that involves only three attention heads.","source":"constructed"}],"related":["circuit-tracing","induction-head","feature","attribution-graph","mechanistic-interpretability","activation-patching","grokking"],"sources":["https://swarma.org/?p=60895","https://hub.baai.ac.cn/view/46611","https://m.leiphone.com/category/ai/AuOBr2ga26JnTWly.html","https://cloud.tencent.com/developer/article/2624862","https://news.qq.com/rain/a/20250617A07B1L00"],"last_researched":"2026-08-08","attestation_count":4},{"id":"circuit-tracing","en":"circuit tracing","en_aliases":[],"abbr":null,"category":"interpretability","tags":["anthropic-lineage","2025"],"definition_en":"Anthropic's 2025 method for recovering the computational path behind a single model output: build a replacement model out of cross-layer transcoder features, then read off an attribution graph.","definition_zh":"Anthropic 2025 年提出的方法：先用跨层转码器的稀疏特征搭出一个\"替换模型\"，再从中读出归因图，从而还原模型产生某一条输出时走过的计算路径。","preferred_zh":"回路追踪","translation_difficulty":"medium","pitfalls":"Inherits the 回路 vs 电路 split from 'circuit' — both 回路追踪 and 电路追踪 occur. 集智俱乐部 adds a syllable and writes 工作回路追踪 ('working-circuit tracing'), which reads more naturally in Chinese but is their coinage rather than a settled term. Much coverage simply keeps 'Circuit Tracing' in English as the paper title. The associated architecture, the cross-layer transcoder, does have a stable Chinese rendering: 跨层转码器.","translations":[{"zh":"回路追踪","pinyin":"huílù zhuīzōng","status":"common","literal_back":"circuit tracing","notes":"Our recommendation, consistent with 回路 for 'circuit'. 集智 uses the expanded 工作回路追踪.","attestations":[{"quote_zh":"他们开发了一种名为'Circuit Tracing'（工作回路追踪）的新方法。","quote_en":"They developed a new method called 'Circuit Tracing'.","source_title":"Anthropic提出工作回路追踪方法：用归因图解开大语言模型计算之谜","publisher":"集智俱乐部","source_type":"blog","url":"https://swarma.org/?p=62523","date":"2025-07"},{"quote_zh":"通过构建'替换模型'和'归因图'，将原本不可见的神经网络计算过程可视化为清晰的计算图。","quote_en":"By building a 'replacement model' and an 'attribution graph', it visualises the otherwise invisible computation of the neural network as a clear computational graph.","source_title":"Anthropic提出工作回路追踪方法：用归因图解开大语言模型计算之谜","publisher":"集智俱乐部","source_type":"blog","url":"https://swarma.org/?p=62523","date":"2025-07"}]},{"zh":"工作回路追踪","pinyin":"gōngzuò huílù zhuīzōng","status":"common","literal_back":"working-circuit tracing","notes":"集智俱乐部's rendering; the extra 工作 makes the compound read better in Chinese but is not in the English.","attestations":[]},{"zh":"电路追踪","pinyin":"diànlù zhuīzōng","status":"common","literal_back":"electrical-circuit tracing","notes":"The 电路 variant, consistent with sources that chose 电路 for 'circuit'. No fetchable verbatim recovered.","attestations":[]}],"confidence":"medium","used_by":[{"org":"集智俱乐部","zh_used":"工作回路追踪","note":"in its explainer article title"}],"usage_examples":[{"zh":"回路追踪的第一步是把 MLP 神经元换成跨层转码器学到的稀疏特征。","en":"The first step in circuit tracing is replacing the MLP neurons with sparse features learned by a cross-layer transcoder.","source":"constructed"}],"related":["circuit","attribution-graph","cross-layer-transcoder","mechanistic-interpretability","crosscoder","activation-patching"],"sources":["https://swarma.org/?p=62523","https://m.leiphone.com/category/ai/AuOBr2ga26JnTWly.html"],"last_researched":"2026-08-08","attestation_count":2},{"id":"collusion","en":"collusion","abbr":null,"category":"misalignment-phenomena","tags":["multi-agent","ai-control"],"definition_en":"Multiple AI instances or agents coordinating to defeat oversight — for example an untrusted model and its monitor agreeing to conceal a failure, or several agents in a workflow jointly presenting a false account to a human.","definition_zh":"多个 AI 实例或智能体串通起来规避监督——比如被监控的模型和监控它的模型达成默契一起掩盖问题，或者工作流里的几个智能体联手向人类给出一份假的说法。","preferred_zh":"合谋","translation_difficulty":"low","pitfalls":"Easy, because Chinese already has precise words. 合谋 and 共谋 both mean 'to conspire jointly' and both are used; 串通 adds a stronger flavour of illicit prior arrangement (it is the word used for bid-rigging and collusive tendering) and is the closest to the antitrust sense. In AI-control writing 合谋 is the natural default. Only caution: unlike 密谋 for scheming, the conspiratorial connotation here is correct — collusion genuinely does involve multiple parties coordinating, so the Chinese word is not overshooting.","translations":[{"zh":"合谋","pinyin":"hémóu","status":"common","literal_back":"joint plotting","notes":"The default in Chinese multi-agent-safety writing.","attestations":[{"quote_zh":"要是你面对的是一群AI助手合谋起来（骗你）呢？","quote_en":"But what if what you're facing is a group of AI assistants colluding (to deceive you)?","source_title":"G.O.S.S.I.P 阅读推荐 2026-05-13 三AI成虎？","publisher":"信息安全知识库 (gm7.org)","source_type":"blog","url":"https://www.gm7.org/archives/101922","date":"2026-05"}]},{"zh":"共谋","pinyin":"gòngmóu","status":"common","literal_back":"shared plotting","notes":"Interchangeable with 合谋; 智能体共谋 appears as a named attack type in Chinese agent-security taxonomies. No verbatim attestation recovered in this pass.","attestations":[]},{"zh":"串通","pinyin":"chuàntōng","status":"common","literal_back":"to be in league / collude","notes":"Legal-economic register (串通投标 = bid rigging). Use when the antitrust/game-theoretic sense of collusion is meant.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"AI 控制协议必须假设被监控模型与监控模型可能合谋。","en":"AI control protocols have to assume the monitored model and the monitor may collude.","source":"constructed"}],"related":["ai-control","multi-agent-system","steganography","scheming"],"sources":["https://www.gm7.org/archives/101922","https://www.secrss.com/articles/76389"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":1},{"id":"computer-use","en":"computer use","en_aliases":["GUI agent","computer-use agent"],"abbr":null,"category":"agents-autonomy","tags":["capability","loanword"],"definition_en":"An agent operating a computer the way a person does — reading the screen, moving the cursor, clicking and typing — rather than through purpose-built APIs.","definition_zh":"智能体像人一样直接操作电脑：看屏幕、移动光标、点击和输入，而不是通过专门的 API 接口完成任务。","preferred_zh":"Computer Use","translation_difficulty":"high","pitfalls":"Chinese has no settled translation of the capability name and mostly keeps \"Computer Use\" in Latin script, even in Chinese-language research write-ups from Chinese labs. What Chinese *does* have a stable term for is the agent class: GUI 智能体, which is well established in Chinese survey and media coverage. The two are not the same — GUI 智能体 names the system, Computer Use names the capability, and GUI 智能体 also covers phone/mobile agents (手机智能体), which Chinese product discourse treats as the primary case because of the mobile-first market. Candidate calques 电脑使用 and 计算机使用 both read as ordinary phrases meaning \"using a computer\" and are not recognisable as a term of art; 计算机操作 is slightly better but still rare. Note also that Chinese sources keep GUI and API in Latin letters, so hybrid phrases like API-GUI 范式 are normal.","translations":[{"zh":"Computer Use","pinyin":null,"status":"loanword","literal_back":null,"notes":"Dominant. Chinese technical write-ups embed the English phrase (often as \"Computer Use Agent\") directly in Chinese sentences rather than translating it. The BAAI/Zhipu-Tsinghua ComputerRL coverage cited here does exactly this throughout.","attestations":[{"quote_zh":"研究团队提出了一种创新的 API-GUI 范式，将编程 API 调用与直接的 GUI 交互结合","quote_en":"The research team proposed an innovative API-GUI paradigm combining programmatic API calls with direct GUI interaction.","source_title":"把电脑交给AI Agent！清华、智谱、国科大团队打造ComputerRL","publisher":"智源社区 (BAAI Hub)","source_type":"media","url":"https://hub.baai.ac.cn/view/48312","date":"2025-08"}]},{"zh":"GUI 智能体","pinyin":"GUI zhìnéngtǐ","status":"established","literal_back":"GUI intelligent-entity","notes":"The established Chinese term for the *agent class* that does computer use. Widely used in Chinese survey coverage. Prefer this when the referent is the system; it does not translate the capability name.","attestations":[{"quote_zh":"基于大语言模型的GUI智能体能够更好地应对这些挑战。通过自然语言理解和视觉感知，这些智能体能根据简单的语言指令解析出用户期望的具体操作","quote_en":"LLM-based GUI agents can better meet these challenges: through natural-language understanding and visual perception, they can parse the specific operations a user wants from a simple verbal instruction.","source_title":"微软发布突破性大模型GUI智能体综述，引领人机交互新纪元！","publisher":"搜狐","source_type":"media","url":"https://www.sohu.com/a/847098842_121924584","date":"2025-01"}]},{"zh":"电脑操作","pinyin":"diànnǎo cāozuò / jìsuànjī cāozuò","status":"descriptive","literal_back":"computer operation","notes":"Descriptive paraphrase used when the capability has to be explained in plain Chinese. Not a recognised term of art; readers will not identify it as the Anthropic-lineage capability. Recorded in research as “电脑操作 / 计算机操作”.","attestations":[],"zh_variants":["电脑操作","计算机操作"]}],"confidence":"medium","used_by":[{"org":"智谱 AI / 清华大学","zh_used":"Computer Use Agent","note":"ComputerRL work, reported in Chinese with the English term retained"}],"usage_examples":[{"zh":"GUI 智能体不依赖专用接口，直接看屏幕、点按钮，因此权限边界更难界定。","en":"GUI agents do not rely on dedicated interfaces — they read the screen and click buttons directly, which makes the permission boundary harder to define.","source":"constructed"}],"related":["ai-agent","tool-use","sandboxing","permissions","gui-agent"],"sources":["https://hub.baai.ac.cn/view/48312","https://www.sohu.com/a/847098842_121924584"],"last_researched":"2026-08-08","attestation_count":2},{"id":"constitutional-ai","en":"Constitutional AI","en_aliases":[],"abbr":"CAI","category":"training-methods","tags":["anthropic","false-friend","high-value"],"definition_en":"Anthropic's alignment method in which a model critiques and revises its own outputs against a written set of principles (the \"constitution\"), and those revisions replace human harmlessness labels in the training loop.","definition_zh":"Anthropic 提出的一种对齐方法：给模型一份写明的原则清单，让它按照这些原则自我批评、自我修改输出，用这些自我修订的数据取代人工标注的有害性标签来训练模型。","preferred_zh":"Constitutional AI（宪法式 AI）","translation_difficulty":"high","pitfalls":"The headline pitfall in this category. 宪法 in Chinese means specifically a state constitution — the supreme law of a country, a term with heavy political-legal weight in the PRC context. Applying it to a company's internal list of behavioural principles reads as either grandiose or faintly political, and invites a reader to think about constitutional law, sovereignty and 依宪治国 rather than about a document of training principles. The English \"constitution\" carries a looser sense (a founding charter, the constitution of a club) that Chinese 宪法 does not. Chinese sources feel this: many simply leave \"Constitutional AI\" in English, and the more careful ones write 宪法式 AI with the 式 (\"-style\", \"-like\") acting as a hedge that signals metaphor. 章程 (charter, articles of association) or 准则 (code of conduct) would be semantically closer but are not attested for this term.","translations":[{"zh":"Constitutional AI","pinyin":null,"status":"loanword","literal_back":null,"notes":"Chinese tech media frequently keeps the English term in quotation marks rather than committing to a Chinese rendering — a direct symptom of the 宪法 problem. This is a legitimate and common answer.","attestations":[{"quote_zh":"「Constitutional AI」训练方法","quote_en":"The \"Constitutional AI\" training method.","source_title":"Anthropic 展示它的 AI 训练与 OpenAI 不同之处：不需要人工标注有害信息","publisher":"腾讯云开发者社区","source_type":"media","url":"https://cloud.tencent.com/developer/news/1071939","date":"2023-05"}]},{"zh":"宪法式 AI","pinyin":"xiànfǎ shì AI","status":"common","literal_back":"constitution-style AI","notes":"The best of the Chinese options. The 式 suffix marks the word as an analogy rather than a claim that a real constitution is involved, which materially reduces the political-law misreading. Recommended when a Chinese rendering is required.","attestations":[{"quote_zh":"这项技术不仅是 Claude 的核心差异化优势，更代表了 AI 对齐（Alignment）领域的一次重大范式转变。","quote_en":"This technique is not only Claude's core differentiator but also represents a major paradigm shift in the field of AI alignment.","source_title":"11.1 宪法式 AI —《Claude 技术指南》","publisher":"Claude Guide (yeasy)","source_type":"blog","url":"https://yeasy.gitbook.io/claude_guide/di-si-bu-fen-shi-zhan-pian/11_safety/11.1_cai","date":"2025"}]},{"zh":"宪法 AI","pinyin":"xiànfǎ AI","status":"common","literal_back":"constitution AI","notes":"The bare calque, widely seen in blog posts and article titles. Recommended against relative to 宪法式 AI: without the 式 hedge it reads as if an actual constitution governs the model, which is the connotation drift we want to avoid.","attestations":[]},{"zh":"宪法式人工智能","pinyin":"xiànfǎ shì réngōng zhìnéng","status":"common","literal_back":"constitution-style artificial intelligence","notes":"The fully-Chinese formal register variant, used in policy-adjacent and journalistic writing where 人工智能 is preferred to the letters AI. Same hedging benefit as 宪法式 AI. No independently fetched verbatim attestation recorded.","attestations":[]}],"confidence":"medium","used_by":[{"org":"Claude Guide（中文社区技术指南）","zh_used":"宪法式 AI","note":"chapter title 11.1 宪法式 AI"}],"usage_examples":[{"zh":"Anthropic 用宪法式 AI 让模型按一份写明的原则自我修订，从而减少对人工标注的依赖。","en":"Anthropic uses Constitutional AI to have the model revise itself against a written set of principles, reducing reliance on human annotation.","source":"constructed"}],"related":["rlaif","rlhf","post-training","model-spec","deliberative-alignment","constitutional-classifiers"],"sources":["https://cloud.tencent.com/developer/news/1071939","https://yeasy.gitbook.io/claude_guide/di-si-bu-fen-shi-zhan-pian/11_safety/11.1_cai"],"last_researched":"2026-08-08","attestation_count":2},{"id":"constitutional-classifiers","en":"constitutional classifiers","abbr":null,"category":"alignment-techniques","tags":["anthropic","2025"],"definition_en":"Anthropic's 2025 jailbreak defence: input and output classifiers trained on synthetic data generated from a natural-language 'constitution' specifying what the model may and may not discuss.","definition_zh":"Anthropic 2025 年提出的越狱防御方案：先用自然语言写出一部规定「可以谈什么、不能谈什么」的「宪法」，再用它生成合成数据训练输入端和输出端两组分类器。","preferred_zh":"宪法分类器","translation_difficulty":"medium","pitfalls":"宪法 in Chinese means the Constitution — a specific legal instrument of the state, with heavy political weight. Anthropic's 'constitution' is closer to a charter or code of conduct, and the English word is already a loose metaphor; in Chinese the metaphor lands much harder. Chinese media handle this by scare-quoting it (实际上就是一部「宪法」) rather than by substituting 章程 or 准则, so 宪法分类器 is what stuck. Be aware the term will read as more grandiose (and more political) to a Chinese reader than to an English one. Same pitfall as 宪法 AI (Constitutional AI).","translations":[{"zh":"宪法分类器","pinyin":"xiànfǎ fēnlèiqì","status":"established","literal_back":"constitution classifier","notes":"Uniform across Chinese tech media coverage from February 2025 onward; no competing rendering observed.","attestations":[{"quote_zh":"为解决人工智能工具中存在的滥用自然语言提示问题，OpenAI 的竞争对手 Anthropic 推出了一个名为「宪法分类器（constitutional classifiers）」的新概念","quote_en":"To address abuse of natural-language prompts in AI tools, OpenAI's competitor Anthropic has introduced a new concept called 'constitutional classifiers'.","source_title":"Anthropic 推「宪法分类器」，可大幅降低 Claude 越狱率","publisher":"新浪科技（IT之家）","source_type":"media","url":"https://finance.sina.com.cn/tech/digi/2025-02-05/doc-ineikxsh2850416.shtml","date":"2025-02"},{"quote_zh":"这是一种将一套类似人类价值观（实际上就是一部「宪法」）植入大型语言模型的方法","quote_en":"It is a method of implanting a set of human-like values — in effect a 'constitution' — into a large language model.","source_title":"Anthropic 推「宪法分类器」，可大幅降低 Claude 越狱率","publisher":"新浪科技（IT之家）","source_type":"media","url":"https://finance.sina.com.cn/tech/digi/2025-02-05/doc-ineikxsh2850416.shtml","date":"2025-02"}]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"宪法分类器在输入端和输出端各设一道，前者拦请求，后者实时判生成内容。","en":"Constitutional classifiers sit at both ends: the input side blocks requests, the output side judges generated content in real time.","source":"constructed"}],"related":["constitutional-ai","guardrails","refusal","defense-in-depth"],"sources":["https://finance.sina.com.cn/tech/digi/2025-02-05/doc-ineikxsh2850416.shtml","https://cloud.tencent.cn/developer/news/2136912","https://finance.sina.com.cn/tech/csj/2025-02-17/doc-inekufeh3486908.shtml"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"context-window","en":"context window","en_aliases":["context length"],"abbr":null,"category":"training-methods","tags":["settled"],"definition_en":"The maximum number of tokens a model can attend to in a single forward pass — prompt plus generated output. A hard architectural limit, distinct from how well the model actually uses that span.","definition_zh":"模型一次前向计算中能够处理的最大 token 数，包括输入提示和生成内容。这是架构层面的硬性上限，和模型能否真正用好这么长的上下文是两回事。","preferred_zh":"上下文窗口","translation_difficulty":"low","pitfalls":"Two renderings split by usage rather than meaning: 上下文窗口 for the concept/limit, 上下文长度 for the number you configure or extend (扩展上下文长度, 32K 上下文). Both are established; neither is wrong. Chinese product copy often shortens to bare 上下文 (支持 128K 上下文).","translations":[{"zh":"上下文窗口","pinyin":"shàngxiàwén chuāngkǒu","status":"established","literal_back":"context window","notes":"Standard for the concept. Used in explainer titles and product documentation.","attestations":[{"quote_zh":"该模型可以处理并记住最多 32,000 个标记（tokens）的输入。","quote_en":"The model can process and remember an input of at most 32,000 tokens.","source_title":"什么是大语言模型的上下文窗口","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2635092","date":"2026-03"}]},{"zh":"上下文长度","pinyin":"shàngxiàwén chángdù","status":"established","literal_back":"context length","notes":"Preferred when the span is being measured or extended. 长上下文 = long context.","attestations":[{"quote_zh":"在最后阶段，我们使用高质量的长上下文数据将上下文长度扩展到 32K token","quote_en":"In the final stage we used high-quality long-context data to extend the context length to 32K tokens.","source_title":"Qwen3: 思深，行速","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"blog","url":"https://qwenlm.github.io/zh/blog/qwen3/","date":"2025-04"},{"quote_zh":"我们支持了 RoPE 插值来扩展 LLaMA 模型的上下文长度。","quote_en":"We now support RoPE interpolation to extend the context length of LLaMA models.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2023-08"}]}],"confidence":"medium","used_by":[{"org":"阿里巴巴通义千问 (Qwen)","zh_used":"上下文长度","note":"Qwen3 Chinese release blog"}],"usage_examples":[{"zh":"上下文窗口是硬上限，但模型未必真的用得好这么长的上下文。","en":"The context window is a hard ceiling, but the model may not actually use that much context well.","source":"constructed"}],"related":["in-context-learning","system-prompt"],"sources":["https://cloud.tencent.com/developer/article/2635092","https://qwenlm.github.io/zh/blog/qwen3/","https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md"],"last_researched":"2026-08-08","attestation_count":3},{"id":"cross-layer-transcoder","en":"cross-layer transcoder","en_aliases":["CLT"],"abbr":"CLT","category":"interpretability","tags":["added-by-research","anthropic-lineage","2025"],"definition_en":"The sparse feature architecture behind Anthropic's circuit tracing: features read from one layer and write to all later layers, so a 'replacement model' built from them approximates the original while being made of interpretable parts.","definition_zh":"Anthropic 回路追踪背后的稀疏特征架构：特征从某一层读入、向之后所有层写出，用它搭出的\"替换模型\"既能逼近原模型，又完全由可解释的部件组成。","preferred_zh":"跨层转码器","translation_difficulty":"low","pitfalls":"Added because it is the term Chinese sources actually settled on while 'crosscoder' remained untranslated — a useful contrast. 转码器 ('transcoder') is well formed and unambiguous. Do not confuse CLT with the crosscoder: both span layers, but the transcoder maps layer inputs to later-layer outputs whereas the crosscoder reconstructs activations at multiple sites; Chinese coverage of the 2025 papers gave CLT a term and gave the crosscoder none.","translations":[{"zh":"跨层转码器","pinyin":"kuà céng zhuǎnmǎ qì","status":"common","literal_back":"cross-layer transcoder","notes":"Consistent across Chinese coverage of Anthropic's March 2025 circuit-tracing papers; always given with the English on first use.","attestations":[{"quote_zh":"我们的分析基于跨层转码器（cross-layer transcoders, CLT）。","quote_en":"Our analysis is based on cross-layer transcoders (CLTs).","source_title":"Anthropic提出工作回路追踪方法：用归因图解开大语言模型计算之谜","publisher":"集智俱乐部","source_type":"blog","url":"https://swarma.org/?p=62523","date":"2025-07"},{"quote_zh":"替换模型的核心架构是跨层转码器（cross-layer transcoder），由作为神经元的'特征'组成。","quote_en":"The core architecture of the replacement model is a cross-layer transcoder, made up of 'features' that act as neurons.","source_title":"Anthropic AI 最新研究成果发布：揭示大模型中的注意力回路","publisher":"雷峰网 (洪雨欣)","source_type":"media","url":"https://m.leiphone.com/category/ai/AuOBr2ga26JnTWly.html","date":"2025-04"}]},{"zh":"替换模型","pinyin":"tìhuàn móxíng","status":"common","literal_back":"replacement model","notes":"The associated term for Anthropic's 'replacement model'. Also seen as 替代模型 in the same article — the two are used interchangeably.","attestations":[{"quote_zh":"替代模型是通过将原始模型中的神经元替换为跨层转码器中的稀疏激活特征所构建的。","quote_en":"The replacement model is built by replacing the neurons of the original model with the sparsely activating features of the cross-layer transcoder.","source_title":"Anthropic提出工作回路追踪方法：用归因图解开大语言模型计算之谜","publisher":"集智俱乐部","source_type":"blog","url":"https://swarma.org/?p=62523","date":"2025-07"}]}],"confidence":"high","used_by":[{"org":"集智俱乐部","zh_used":"跨层转码器","note":"in its circuit-tracing explainer"},{"org":"雷峰网","zh_used":"跨层转码器","note":"in its Anthropic coverage"}],"usage_examples":[{"zh":"他们用跨层转码器把 MLP 换掉，得到一个可解释的替换模型。","en":"They swapped out the MLPs using a cross-layer transcoder to get an interpretable replacement model.","source":"constructed"}],"related":["circuit-tracing","attribution-graph","crosscoder","sparse-autoencoder"],"sources":["https://swarma.org/?p=62523","https://m.leiphone.com/category/ai/AuOBr2ga26JnTWly.html"],"last_researched":"2026-08-08","attestation_count":3},{"id":"crosscoder","en":"crosscoder","en_aliases":["sparse crosscoder","model diffing crosscoder"],"abbr":null,"category":"interpretability","tags":["anthropic-lineage","untranslated","false-friend","high-value"],"definition_en":"A variant of the sparse autoencoder that reads from and writes to several layers — or several models — at once, learning one shared dictionary across them. Used to resolve cross-layer superposition, to strip duplicate features out of circuits, and above all for model diffing (finding what a fine-tune changed).","definition_zh":"稀疏自编码器的一种变体：同时从多个层（甚至多个模型）读取和写回激活，学习一部共享的特征字典。主要用于处理跨层叠加、剔除回路中的重复特征，以及\"模型对比\"——找出微调到底改变了什么。","preferred_zh":"crosscoder","translation_difficulty":"high","pitfalls":"This is the clearest false-friend trap in the category. The obvious calque 交叉编码器 is already a fully occupied slot in Chinese ML: it is the settled term for the retrieval cross-encoder, the reranker that jointly encodes a query-document pair, contrasted with 双编码器 (bi-encoder). A Chinese NLP engineer who reads 交叉编码器 will think 'reranker', not 'Anthropic interpretability architecture'. 跨编码器 avoids the collision but is barely attested and would still be heard as a variant spelling of the reranker. Meanwhile the adjacent Anthropic architecture cross-layer transcoder DOES have a settled Chinese rendering — 跨层转码器 — because Chinese media covered the 2025 circuit-tracing papers; crosscoder got no comparable coverage. Practical advice: write the English word, or 稀疏跨编码器（crosscoder）with the English attached.","translations":[{"zh":"crosscoder","pinyin":null,"status":"loanword","literal_back":null,"notes":"Chinese-language treatment of this term is essentially limited to reading notes and paper summaries that keep the English title and the English word. I could not recover a verbatim Chinese sentence containing an accepted Chinese rendering, so no attestation is recorded — the gap itself is the finding.","attestations":[]},{"zh":"稀疏跨编码器","pinyin":"xīshū kuà biānmǎ qì","status":"proposed","literal_back":"sparse cross-coder","notes":"We propose this, with the English attached on first use. 跨 (across/spanning) correctly conveys 'reads across layers/models' and does not collide with the established 交叉编码器 reranker; 编码器 keeps the family resemblance to 稀疏自编码器. Not attested in a source we could fetch — this is a coinage, not a report.","attestations":[]},{"zh":"交叉编码器","pinyin":"jiāochā biānmǎ qì","status":"deprecated","literal_back":"cross-encoder","notes":"Do not use for crosscoder. In Chinese this string already means the retrieval cross-encoder / reranker and nothing else; the attestation below is included precisely to show the collision.","attestations":[{"quote_zh":"第一阶段：双编码器在海量文档中进行 '粗筛'，快速锁定一个可能相关的候选集（如Top-50）。第二阶段：Cross-Encoder对候选集进行 '精排'","quote_en":"Stage one: the bi-encoder does a coarse filter over a huge document set, quickly narrowing to a candidate set (e.g. Top-50). Stage two: the cross-encoder does fine reranking of that candidate set.","source_title":"Transformer架构的 Bi-Encoder （双编码器模型）, Cross-Encoder（交叉编码器）重排序模型","publisher":"博客园 (飘来荡去evo)","source_type":"blog","url":"https://www.cnblogs.com/itqinls/p/20009045","date":"2026-05"}]}],"confidence":"low","used_by":[],"usage_examples":[{"zh":"他们用 crosscoder 对比 base 模型和 chat 模型，找出微调新增的特征。","en":"They used a crosscoder to diff the base and chat models and find the features the fine-tune added.","source":"constructed"}],"related":["sparse-autoencoder","feature","superposition","cross-layer-transcoder","circuit-tracing"],"sources":["https://www.cnblogs.com/itqinls/p/20009045","https://transformer-circuits.pub/2024/crosscoders/index.html","https://blog.csdn.net/xhyu61/article/details/148358121"],"last_researched":"2026-08-08","attestation_count":1},{"id":"data-contamination","en":"data contamination","en_aliases":["benchmark contamination","test set leakage"],"abbr":null,"category":"training-methods","tags":["settled","evaluation-adjacent"],"definition_en":"Benchmark items appearing in a model's training data, inflating measured performance. The main reason published benchmark scores overstate real capability.","definition_zh":"评测集里的题目出现在模型的训练数据中，导致评测分数虚高。这是公开榜单成绩往往高于真实能力的主要原因。","preferred_zh":"数据污染","translation_difficulty":"low","pitfalls":"数据污染 and 数据泄露 are used almost interchangeably in Chinese ML writing for this concept, but 数据泄露 also means a privacy/security data breach — the same collision English avoids by saying \"leakage\" vs \"breach\". Prefer 数据污染 when the sense is benchmark contamination; reserve 数据泄露 for the security sense, or say 基准泄漏 when you must use the leakage framing. Note the vivid native term 刷榜 (\"grinding the leaderboard\") for the behaviour contamination enables.","translations":[{"zh":"数据污染","pinyin":"shùjù wūrǎn","status":"established","literal_back":"data contamination","notes":"The standard term for the benchmark sense. Used by 机器之心 and downstream Chinese tech media.","attestations":[{"quote_zh":"当前火热的大模型领域让人们关心基准测试的排名，但其公平性和可靠性正在受到质疑。其中主要的问题就是数据污染和泄露。","quote_en":"The current hot field of large models has people caring about benchmark rankings, but their fairness and reliability are being questioned. The main problem is data contamination and leakage.","source_title":"大模型走捷径「刷榜」？数据污染问题值得重视","publisher":"机器之心（经腾讯云开发者社区转载）","source_type":"media","url":"https://cloud.tencent.com/developer/article/2357653","date":"2023-11"},{"quote_zh":"训练语料库的详细组成（例如数据源）通常被视为现有大模型的核心「秘密」。这就更难去探究数据污染的问题了。","quote_en":"The detailed composition of the training corpus (e.g. data sources) is generally treated as a core \"secret\" of existing large models, which makes investigating data contamination even harder.","source_title":"大模型走捷径「刷榜」？数据污染问题值得重视","publisher":"机器之心（经腾讯云开发者社区转载）","source_type":"media","url":"https://cloud.tencent.com/developer/article/2357653","date":"2023-11"}]},{"zh":"基准泄漏","pinyin":"jīzhǔn xièlòu","status":"common","literal_back":"benchmark leakage","notes":"Used alongside 数据污染 in the same article; slightly narrower, naming the mechanism. 泄露/泄漏 are both written.","attestations":[{"quote_zh":"基准泄漏会导致大模型跑出夸张的成绩：例如1.3B的模型可以在某些任务上超越10倍体量的模型。","quote_en":"Benchmark leakage causes large models to post exaggerated scores: for example a 1.3B model can beat a model ten times its size on certain tasks.","source_title":"大模型走捷径「刷榜」？数据污染问题值得重视","publisher":"机器之心（经腾讯云开发者社区转载）","source_type":"media","url":"https://cloud.tencent.com/developer/article/2357653","date":"2023-11"}]},{"zh":"刷榜","pinyin":"shuā bǎng","status":"common","literal_back":"grinding the leaderboard","notes":"Native Chinese slang with no clean English equivalent — gaming a leaderboard, whether by contamination or by over-fitting to the benchmark. Vivid, informal, widely used in Chinese ML discourse and worth borrowing conceptually.","attestations":[{"quote_zh":"大模型走捷径「刷榜」？数据污染问题值得重视","quote_en":"Are large models taking shortcuts to \"grind the leaderboard\"? The data contamination problem deserves attention.","source_title":"大模型走捷径「刷榜」？数据污染问题值得重视","publisher":"机器之心（经腾讯云开发者社区转载）","source_type":"media","url":"https://cloud.tencent.com/developer/article/2357653","date":"2023-11"}]}],"confidence":"high","used_by":[{"org":"机器之心","zh_used":"数据污染","note":"feature article on benchmark contamination"}],"usage_examples":[{"zh":"这个分数不能信，很可能有数据污染。","en":"This score can't be trusted — there's very likely data contamination.","source":"constructed"}],"related":["synthetic-data","pretraining","sleeper-agent"],"sources":["https://cloud.tencent.com/developer/article/2357653"],"last_researched":"2026-08-08","attestation_count":4},{"id":"ai-debate","en":"debate","en_aliases":["AI safety via debate"],"abbr":null,"category":"alignment-techniques","tags":["scalable-oversight"],"definition_en":"A scalable-oversight proposal (Irving et al. 2018) in which two AI agents argue opposing sides of a question and a weaker human judge decides the winner, on the assumption that defending a true position is easier than defending a false one.","definition_zh":"让两个模型就同一问题各执一方轮流陈述，由能力较弱的人类裁判判定胜负的一种可扩展监督方案，其前提假设是「为真理辩护比为谎言辩护更容易」。","preferred_zh":"辩论","translation_difficulty":"medium","pitfalls":"Bare 辩论 is the correct and universally used word, but it is a completely ordinary Chinese noun — in isolation a reader cannot tell that an alignment technique is meant. Chinese authors therefore almost always write 辩论（Debate） with the English in parentheses on first use, or qualify it as 模型辩论 / AI-AI 辩论. Compounding the ambiguity, 智源 runs a Chinese LLM benchmark literally called FlagEval Debate（大模型辩论平台）which is an evaluation leaderboard, not the alignment technique.","translations":[{"zh":"辩论","pinyin":"biànlùn","status":"established","literal_back":"debate","notes":"The standard term, always glossed with the English on first use in technical writing.","attestations":[{"quote_zh":"辩论的基本过程是两个智能体轮流提供答案和陈述，而人类裁判根据辩论过程进行最终结果的评判(Irving et al., 2018)。","quote_en":"The basic process of debate is that two agents take turns giving answers and statements, and a human judge decides the final outcome based on the debate.","source_title":"《对齐的理论、技术与评估》","publisher":"北京大学人工智能安全与治理中心 / CCL 2024","source_type":"paper","url":"https://aclanthology.org/2024.ccl-2.7.pdf","date":"2024-07"},{"quote_zh":"关于可扩展监督比较典型的例子包括辩论（debate）、递归奖励建模（recursive reward modeling）、迭代放大（iterated amplification）等。","quote_en":"Typical examples of scalable oversight include debate, recursive reward modeling, and iterated amplification.","source_title":"万字长文详解：大模型时代AI价值对齐的问题、对策和展望","publisher":"腾讯研究院（集智俱乐部转载）","source_type":"report","url":"https://swarma.org/?p=46724","date":"2023-11"}]},{"zh":"人类主持的 AI-AI 辩论","pinyin":"rénlèi zhǔchí de AI-AI biànlùn","status":"descriptive","literal_back":"human-moderated AI-AI debate","notes":"Descriptive expansion used when the bare 辩论 would be ambiguous. Calque of Sam Bowman's 'Human-Moderated AI-AI Debate'.","attestations":[{"quote_zh":"Bowman的讲座主要介绍了他在可拓展监督上的研究方向：人类主持的AI-AI辩论（Human-Moderated AI-AI Debate）","quote_en":"Bowman's talk mainly introduced his research direction in scalable oversight: human-moderated AI-AI debate.","source_title":"Anthropic团队可拓展监督前沿","publisher":"安远AI（安全内参转载）","source_type":"report","url":"https://www.secrss.com/articles/63415","date":"2024-02"}]}],"confidence":"high","used_by":[{"org":"北京大学 人工智能安全与治理中心","zh_used":"辩论（Debate）","note":"CCL 2024 alignment survey, scalable-oversight section"},{"org":"安远 AI (Concordia AI)","zh_used":"人类主持的 AI-AI 辩论","note":"Bowman lecture writeup"}],"usage_examples":[{"zh":"辩论的前提假设依赖于一个关键的假设：为真理辩护通常比为虚假辩护更容易。","en":"Debate rests on a key assumption: defending the truth is usually easier than defending a falsehood.","source":"https://aclanthology.org/2024.ccl-2.7.pdf"}],"related":["scalable-oversight","recursive-reward-modeling","iterated-amplification"],"sources":["https://aclanthology.org/2024.ccl-2.7.pdf","https://swarma.org/?p=46724","https://www.secrss.com/articles/63415"],"last_researched":"2026-08-08","attestation_count":3},{"id":"deceptive-compliance","en":"deceptive compliance","abbr":null,"category":"misalignment-phenomena","tags":["high-value","idiom","contested"],"definition_en":"Outward obedience concealing an intent to act otherwise once oversight relaxes — the behavioural surface of deceptive alignment. Distinct from alignment faking in being about compliance with instructions or oversight generally, not specifically about preserving preferences through training.","definition_zh":"表面上服从，实际上打算等监督一松就换一套做法——欺骗性对齐在行为层面的表现。与对齐伪装的区别在于，它针对的是对指令和监督的服从，而不特指在训练中保住自己的偏好。","preferred_zh":"阳奉阴违","translation_difficulty":"medium","pitfalls":"A rare case where Chinese has a BETTER word than English. 阳奉阴违 (chengyu, roughly 'comply in the open, defy in secret') encodes the entire concept in four characters, with the deception, the asymmetry between observed and unobserved behaviour, and the intentionality all built in — where English needs the awkward two-word compound 'deceptive compliance'. The obstacle is register, not meaning: 阳奉阴违 is a formal literary idiom that in modern PRC usage is strongly associated with Party-discipline language (used of cadres who nominally implement policy while subverting it), so a technical paper using it may read as making a political accusation. Chinese AI-safety writing instead reaches for the colloquial 当面一套背后一套, which is the same idea in vernacular register and IS attested. Recommendation: use 阳奉阴违 where you want compression and force, 当面一套背后一套 where you want neutrality, and 欺骗性服从 where you need a literal calque that will not surprise anyone.","translations":[{"zh":"当面一套，背后一套","pinyin":"dāngmiàn yī tào, bèihòu yī tào","status":"descriptive","literal_back":"one set to your face, another behind your back","notes":"The vernacular formulation Chinese sources actually use, including 上海人工智能实验室's framework coverage and 量子位's alignment-faking piece. Neutral in register and immediately understood; too long to serve as a term of art.","attestations":[{"quote_zh":"如果说前面的风险还算是'明枪'，那么战略欺骗就是'暗箭'了。研究团队发现，一些AI开始表现出'当面一套，背后一套'的行为。","quote_en":"If the earlier risks count as 'a spear in the open', strategic deception is 'an arrow from the dark'. The research team found that some AI has begun to behave one way to your face and another behind your back.","source_title":"上海人工智能实验室重磅发布：AI正在学会\"偷鸡摸狗\"？前沿AI风险管理框架深度剖析","publisher":"科技行者 (TechWalker)","source_type":"media","url":"https://www.techwalker.com/2026/0224/3179510.shtml","date":"2026-02"},{"quote_zh":"Claude团队最新研究，揭示了大模型这种当面一套背面一套的行为：伪装对齐（Alignment Faking）。","quote_en":"The Claude team's latest research reveals this two-faced behaviour in large models: alignment faking.","source_title":"Claude团队揭发AI伪装对齐：训练时假装遵守目标，只为保护自己价值观不被修改","publisher":"量子位 (QbitAI)，经新浪科技创事记转载","source_type":"media","url":"https://finance.sina.com.cn/tech/csj/2024-12-19/doc-inczyxct6789936.shtml","date":"2024-12"}]},{"zh":"阳奉阴违","pinyin":"yáng fèng yīn wéi","status":"proposed","literal_back":"outwardly obey, inwardly defy","notes":"We advocate this. It is a fully standard chengyu that expresses deceptive compliance more compactly and more precisely than the English term does, and it is exactly the phenomenon under study. Searched for in AI-safety usage and not found attested — Chinese technical writing has so far preferred the vernacular paraphrase, likely because of the term's Party-discipline associations. Adopt it deliberately, with a gloss on first use.","attestations":[]},{"zh":"欺骗性服从","pinyin":"qīpiànxìng fúcóng","status":"proposed","literal_back":"deceptive obedience","notes":"Literal calque, parallel in construction to the established 欺骗性对齐. Safe, colourless, and instantly parseable by anyone who knows 欺骗性对齐. Not found attested; recommended as the conservative option for formal writing.","attestations":[]}],"confidence":"low","used_by":[],"usage_examples":[{"zh":"在有监督的情况下模型完全合规，一旦监督撤除就换了做法，典型的阳奉阴违。","en":"The model was fully compliant under oversight and switched behaviour the moment oversight was removed — textbook deceptive compliance.","source":"constructed"}],"related":["alignment-faking","scheming","strategic-deception"],"sources":["https://www.techwalker.com/2026/0224/3179510.shtml","https://finance.sina.com.cn/tech/csj/2024-12-19/doc-inczyxct6789936.shtml","https://arxiv.org/abs/2412.14093"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"defense-in-depth","en":"defense in depth","abbr":null,"category":"alignment-techniques","tags":["infosec-heritage"],"definition_en":"Layering multiple independent safety measures so that no single failure is catastrophic, on the assumption that each layer is individually imperfect and their failure modes do not fully overlap.","definition_zh":"把多道彼此独立的安全措施叠起来，使任何单点失效都不至于酿成灾难；其前提是每一层都不完美，但各层的失效模式不重叠。","preferred_zh":"纵深防御","translation_difficulty":"low","pitfalls":"纵深防御 is a long-established Chinese information-security and military term, so it transfers into AI safety with zero friction — but that is also the risk: it arrives pre-loaded with a perimeter/intrusion frame (host layer, runtime layer, network layer), i.e. defending against an external attacker. The AI-safety use includes defending against the model itself, which the inherited frame does not naturally suggest. Note the variant word order 防御纵深 (defensive depth), which some alignment writing uses.","translations":[{"zh":"纵深防御","pinyin":"zòngshēn fángyù","status":"established","literal_back":"depth defence","notes":"Directly inherited from Chinese infosec vocabulary; used without explanation in AI security writing.","attestations":[{"quote_zh":"通过OpenClaw资产识别、技能风险扫描、沙箱运行、动态脱敏构建宿主层、Runtime层、网络层纵深防御","quote_en":"Build defence in depth across the host layer, runtime layer and network layer via asset identification, skill risk scanning, sandboxed execution and dynamic masking.","source_title":"AI Infra安全体系构建：应对大模型时代五大核心风险的纵深防御实践","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com.cn/developer/article/2649922","date":"2026-04"}]},{"zh":"防御纵深","pinyin":"fángyù zòngshēn","status":"common","literal_back":"defensive depth","notes":"Reversed word order, used when the emphasis is on the property (having depth) rather than the strategy. Seen in Chinese alignment commentary arguing that no single technique suffices and layers must have non-overlapping failure modes. No verbatim attestation fetched.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"任何单一对齐技术都不保险，必须多层叠加、失效模式互不重叠地做纵深防御。","en":"No single alignment technique is safe on its own; you need layered defence in depth whose failure modes do not overlap.","source":"constructed"}],"related":["guardrails","ai-control","constitutional-classifiers","sandboxing"],"sources":["https://cloud.tencent.com.cn/developer/article/2649922","https://blog.csdn.net/2403_86962125/article/details/149042368"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":1},{"id":"delegation","en":"delegation","en_aliases":["principal-agent"],"abbr":null,"category":"agents-autonomy","tags":["principal-agent","economics-bridge"],"definition_en":"Handing authority to act to another party. In agent systems it is chained — a user delegates to an agent, which delegates to sub-agents — and each hop should narrow, never widen, what is permitted.","definition_zh":"把行动权交给另一方。在智能体系统中委托是链式的：用户委托给智能体，智能体再委托给子智能体，每一次传递都应缩小而不是扩大权限范围。","preferred_zh":"委托","translation_difficulty":"medium","pitfalls":"Chinese splits the English word by register. 委托 is the legal/economic term and — crucially — 委托代理 (关系/问题) is the long-established Chinese rendering of principal–agent theory in economics, which gives AI-safety writers a ready-made, well-understood frame. That bridge is worth using: it is one of the few places where the Chinese vocabulary is *more* precise than the English, because 委托方 (principal) and 代理方 (agent) are already distinguished. 授权 (authorization) is the technical/security term and is what you want for capability grants; 委派 (dispatch/assign) is the software-engineering sense of delegation and is a false friend here. Note the irony that using 委托代理 imports 代理 back in — the very word that lost the 'agent' battle to 智能体.","translations":[{"zh":"委托","pinyin":"wěituō","status":"established","literal_back":"to entrust","notes":"Legal/economic register; base of 委托代理关系 = principal–agent relationship. Preferred for the safety sense of handing over authority.","attestations":[{"quote_zh":"委托必须是单调递减的。委托链中的每一次跳转都应该缩小许可范围，而不是保留或扩大它。","quote_en":"Delegation must be monotonically decreasing. Every hop in the delegation chain should narrow the permission scope, not preserve or widen it.","source_title":"主体层级问题：多智能体系统中的授权","publisher":"TianPan.co","source_type":"blog","url":"https://tianpan.co/zh/blog/2026-03-08-principal-hierarchy-multi-agent-authorization","date":"2026-04"}]},{"zh":"授权","pinyin":"shòuquán","status":"established","literal_back":"to grant authority","notes":"Technical/security register for the same act. Use when the object is a concrete capability or token rather than a task.","attestations":[{"quote_zh":"编排器不授予智能体宽泛的角色，而是传递限定在特定操作范围内的能力令牌。","quote_en":"The orchestrator does not grant the agent a broad role; it passes capability tokens scoped to specific operations.","source_title":"主体层级问题：多智能体系统中的授权","publisher":"TianPan.co","source_type":"blog","url":"https://tianpan.co/zh/blog/2026-03-08-principal-hierarchy-multi-agent-authorization","date":"2026-04"}]},{"zh":"委托代理关系","pinyin":"wěituō dàilǐ guānxì","status":"established","literal_back":"entrustment-agency relationship","notes":"The established Chinese term for principal–agent theory in economics. A ready-made conceptual bridge for AI-safety arguments about misaligned incentives under delegation. Attested in economics broadly; no AI-specific verbatim attestation recovered within budget.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"把任务委托给智能体，等于把一部分决定权交出去，所以边界必须写死。","en":"Delegating a task to an agent means handing over part of your decision authority, so the boundary has to be hard-coded.","source":"constructed"}],"related":["permissions","multi-agent-system","human-in-the-loop","agency"],"sources":["https://tianpan.co/zh/blog/2026-03-08-principal-hierarchy-multi-agent-authorization","https://www.secrss.com/articles/92784"],"last_researched":"2026-08-08","attestation_count":2},{"id":"deliberative-alignment","en":"deliberative alignment","abbr":null,"category":"alignment-techniques","tags":["openai","reasoning"],"definition_en":"OpenAI's o-series safety training method: teach the model the text of the safety specification directly, and train it to reason explicitly over that specification in its chain of thought before answering, rather than learning safe behaviour implicitly from human preference labels.","definition_zh":"OpenAI 在 o 系列模型上使用的安全训练方法：把安全规范原文直接教给模型，并训练它在回答前先在思维链里显式地对照这些规范做推理，而不是靠人类偏好标注隐式地学会「什么不能说」。","preferred_zh":"审慎对齐","translation_difficulty":"medium","pitfalls":"审慎 means prudent/circumspect, which captures 'deliberate' in the sense of careful but loses the sense of 'deliberating', i.e. explicitly reasoning something through — which is the actual mechanism (the model reasons over the spec in its CoT). 深思熟虑对齐 preserves the deliberation sense but is clumsy and much rarer. 审慎 is nonetheless what stuck, largely via CSDN/知乎 translations of the paper in the days after its Dec 2024 release.","translations":[{"zh":"审慎对齐","pinyin":"shěnshèn duìqí","status":"common","literal_back":"prudent alignment","notes":"The rendering that stuck in Chinese technical blogging within days of the December 2024 paper. Attestation is an article headline quoted verbatim; the exact publication date was not confirmed independently, hence medium confidence.","attestations":[{"quote_zh":"OpenAI o3：带 CoT 的审慎对齐（Deliberative Alignment）","quote_en":"OpenAI o3: deliberative alignment with CoT","source_title":"OpenAI o3：带 CoT 的审慎对齐（Deliberative Alignment）","publisher":"知乎专栏","source_type":"zhihu","url":"https://zhuanlan.zhihu.com/p/14861589916","date":"2024-12"}]},{"zh":"深思熟虑对齐","pinyin":"shēnsī-shúlǜ duìqí","status":"proposed","literal_back":"deep-thinking-and-careful-consideration alignment","notes":"More faithful to 'deliberation' as a process, but four-character idiom + 对齐 reads awkwardly and it has not been taken up. Recorded as an alternative we do not recommend over 审慎对齐.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"审慎对齐不再依赖人类反馈数据，而是让模型直接学习安全规范文本并在推理时逐条对照。","en":"Deliberative alignment no longer relies on human feedback data; the model learns the safety specification text directly and checks against it point by point while reasoning.","source":"constructed"}],"related":["chain-of-thought","model-spec","constitutional-ai","refusal","process-supervision"],"sources":["https://zhuanlan.zhihu.com/p/14861589916","https://blog.csdn.net/guojiajiajiu/article/details/144806504","https://blog.csdn.net/qq_41185868/article/details/144731784"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":1},{"id":"dictionary-learning","en":"dictionary learning","en_aliases":[],"abbr":null,"category":"interpretability","tags":["pre-existing-term","signal-processing"],"definition_en":"Learning an overcomplete basis (a 'dictionary') such that each data point is a sparse combination of its elements. Borrowed from sparse coding in signal processing; the framing under which SAEs decompose activations.","definition_zh":"学习一组过完备的基（\"字典\"），使得每个数据点都能表示为其中少数几个元素的稀疏组合。这个概念来自信号处理中的稀疏编码，也是用 SAE 分解激活的理论框架。","preferred_zh":"字典学习","translation_difficulty":"low","pitfalls":"No difficulty: 字典学习 was already the standard Chinese term in signal processing and sparse coding well before interpretability borrowed it, so it arrived pre-translated. The only nuance is that a Chinese reader from the compressed-sensing world will hear the classical algorithm (K-SVD etc.) rather than a neural SAE; sources therefore usually write 稀疏自编码器（一种字典学习算法）or similar to bridge the two.","translations":[{"zh":"字典学习","pinyin":"zìdiǎn xuéxí","status":"established","literal_back":"dictionary learning","notes":"Inherited unchanged from the sparse-coding literature.","attestations":[{"quote_zh":"研究人员通过字典学习将包含512个神经元的层分解出了4000多个可解释的特征","quote_en":"Using dictionary learning, the researchers decomposed a 512-neuron layer into more than 4,000 interpretable features.","source_title":"打破大模型黑盒，彻底分解神经元，OpenAI对头Anthropic击破AI不可解释性障碍","publisher":"新智元 (via 36氪)","source_type":"media","url":"https://www.36kr.com/p/2465483534538887","date":"2023-10"},{"quote_zh":"字典学习（一种稀疏自编码器，SAE）的应用，旨在将大型语言模型的表征分解成更具可解释性、单义的特征。","quote_en":"The application of dictionary learning (a sparse autoencoder, SAE) aims to decompose an LLM's representations into more interpretable, monosemantic features.","source_title":"稀疏自编码器综述：解读大型语言模型的内部机制 (A Survey on Sparse Autoencoders)","publisher":"alphaXiv 中文导读 (arXiv 2503.05613)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2503.05613","date":"2025"}]}],"confidence":"high","used_by":[],"usage_examples":[{"zh":"把 SAE 看成一种字典学习，就容易理解它为什么要过完备。","en":"Once you see an SAE as a form of dictionary learning, it's easy to see why it has to be overcomplete.","source":"constructed"}],"related":["sparse-autoencoder","feature","superposition"],"sources":["https://www.36kr.com/p/2465483534538887","https://hub.baai.ac.cn/view/31396","https://www.alphaxiv.org/zh/overview/2503.05613"],"last_researched":"2026-08-08","attestation_count":2},{"id":"dpo","en":"direct preference optimization","en_aliases":[],"abbr":"DPO","category":"training-methods","tags":["settled","loanword-heavy","algorithm"],"definition_en":"An alignment method that optimises a language model directly on preference pairs with a closed-form loss, removing the need for a separate reward model and RL loop.","definition_zh":"直接在「更好/更差」的偏好对上用一个闭式损失函数优化语言模型，不需要单独训练奖励模型，也不需要跑强化学习循环。","preferred_zh":"DPO（直接偏好优化）","translation_difficulty":"low","pitfalls":null,"translations":[{"zh":"DPO","pinyin":null,"status":"loanword","literal_back":null,"notes":"The working form, listed bare alongside PPO/KTO/ORPO in Chinese framework documentation.","attestations":[{"quote_zh":"集成方法：（增量）预训练、（多模态）指令监督微调、奖励模型训练、PPO 训练、DPO 训练、KTO 训练、ORPO 训练等等。","quote_en":"Integrated methods: (incremental) pretraining, (multimodal) instruction supervised fine-tuning, reward model training, PPO training, DPO training, KTO training, ORPO training, etc.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2025"},{"quote_zh":"DPO 就像是直接告诉 LLM：响应 A 比响应 B 更好。","quote_en":"DPO is like telling the LLM directly: response A is better than response B.","source_title":"推理大模型的后训练增强技术-强化学习篇","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2503293","date":"2025-03"}]},{"zh":"直接偏好优化","pinyin":"zhíjiē piānhào yōuhuà","status":"established","literal_back":"direct preference optimisation","notes":"Uncontested Chinese expansion; appears as the section label in Chinese explainers of post-training RL algorithms, but the acronym is what circulates.","attestations":[{"quote_zh":"DPO 就像是直接告诉 LLM：响应 A 比响应 B 更好。","quote_en":"DPO is like telling the LLM directly: response A is better than response B.","source_title":"推理大模型的后训练增强技术-强化学习篇（DPO直接偏好优化 一节）","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2503293","date":"2025-03"}]}],"confidence":"medium","used_by":[{"org":"LLaMA-Factory","zh_used":"DPO","note":"bare acronym in Chinese feature list"}],"usage_examples":[{"zh":"数据量不大的时候，直接跑 DPO 通常比搭一整套 RLHF 流程划算。","en":"When the dataset is small, running DPO directly is usually more economical than standing up a full RLHF pipeline.","source":"constructed"}],"related":["rlhf","ppo","reward-model","post-training"],"sources":["https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","https://cloud.tencent.com/developer/article/2503293"],"last_researched":"2026-08-08","attestation_count":3},{"id":"distillation","en":"distillation","en_aliases":["knowledge distillation"],"abbr":null,"category":"training-methods","tags":["settled","policy-relevant"],"definition_en":"Training a smaller student model to imitate a larger teacher model's outputs. Originally a compression technique; now also a policy-charged term because frontier models' outputs can be distilled into cheap competitors.","definition_zh":"用一个大的教师模型的输出来训练一个小的学生模型，使小模型逼近大模型的能力。最初是模型压缩技术；如今也成了政策议题，因为前沿模型的输出可以被蒸馏成廉价的竞争者。","preferred_zh":"蒸馏 / 知识蒸馏","translation_difficulty":"low","pitfalls":"The translation itself is settled. The live issue is semantic drift: 知识蒸馏 classically means logit-matching compression, whereas post-DeepSeek-R1 usage of 蒸馏 usually means fine-tuning a small model on a big model's generated outputs (which is closer to synthetic-data SFT). Chinese sources use the same word for both. In policy discussion 蒸馏 additionally carries an accusatory sense (unauthorised extraction from a competitor's model) with no separate Chinese term.","translations":[{"zh":"知识蒸馏","pinyin":"zhīshi zhēngliú","status":"established","literal_back":"knowledge distillation","notes":"The classical, textbook form; standard in Chinese deep-learning literature since well before LLMs.","attestations":[{"quote_zh":"知识蒸馏是一种模型压缩技术，其基本思想是通过训练一个较小的模型（学生模型）来模仿一个大型的、已经训练好的模型（教师模型）。","quote_en":"Knowledge distillation is a model-compression technique whose basic idea is to train a smaller model (the student model) to imitate a large, already-trained model (the teacher model).","source_title":"知识蒸馏——深度学习的简化之道 ！！","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2400364","date":"2024-03"}]},{"zh":"蒸馏","pinyin":"zhēngliú","status":"established","literal_back":"distillation","notes":"The bare form dominates in LLM-era writing (蒸馏模型, 蒸馏数据, R1 蒸馏版). Used freely as a verb: 把 R1 蒸馏到 7B.","attestations":[{"quote_zh":"一个全链路 RAG 检索模型微调、推理和蒸馏代码库。","quote_en":"An end-to-end code library for fine-tuning, inference and distillation of RAG retrieval models.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2025"}]},{"zh":"教师模型","pinyin":"jiàoshī móxíng / xuéshēng móxíng","status":"established","literal_back":"teacher model / student model","notes":"The paired terminology is fully calqued and universal. Some older Chinese literature keeps Teacher/Student in English inside Chinese sentences. Recorded in research as “教师模型 / 学生模型”.","attestations":[{"quote_zh":"知识蒸馏是一种模型压缩技术，其基本思想是通过训练一个较小的模型（学生模型）来模仿一个大型的、已经训练好的模型（教师模型）。","quote_en":"Knowledge distillation is a model-compression technique whose basic idea is to train a smaller model (the student model) to imitate a large, already-trained model (the teacher model).","source_title":"知识蒸馏——深度学习的简化之道 ！！","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2400364","date":"2024-03"}],"zh_variants":["教师模型","学生模型"]}],"confidence":"medium","used_by":[{"org":"LLaMA-Factory","zh_used":"蒸馏","note":"Chinese README ecosystem list"}],"usage_examples":[{"zh":"他们把 R1 的推理轨迹蒸馏进了一个 7B 的小模型。","en":"They distilled R1's reasoning traces into a small 7B model.","source":"constructed"}],"related":["synthetic-data","reasoning-model","open-weights","iterated-amplification"],"sources":["https://cloud.tencent.com/developer/article/2400364","https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md"],"last_researched":"2026-08-08","attestation_count":3},{"id":"emergent-misalignment","en":"emergent misalignment","abbr":null,"category":"misalignment-phenomena","tags":["named-result","2025","finetuning"],"definition_en":"Fine-tuning a model on a narrow harmful task — canonically, writing insecure code — makes it broadly misaligned across unrelated domains, producing 'evil' answers to ordinary questions. Betley et al., February 2025.","definition_zh":"只在一个很窄的有害任务上微调模型（最典型的是让它写有漏洞的代码），结果模型在完全无关的领域也变坏了，会对普通问题给出恶意回答。出自 Betley 等人 2025 年 2 月的论文。","preferred_zh":"涌现性失调","translation_difficulty":"high","pitfalls":"There is no settled Chinese rendering. 失调 / 错位 / 失准 / 非对齐 all compete for 'misalignment' here, and none of them is the word Chinese sources normally use for alignment failure (which is 对齐失败 or simply 未对齐). The prefix is stable — 涌现 is the fully established word for 'emergent' from 涌现能力 — so the instability is entirely on the 'misalignment' side. Popular coverage often abandons the term altogether and uses 黑化 ('turning to the dark side'), which is vivid, memorable and carries an anime connotation that no researcher would want in a paper.","translations":[{"zh":"涌现性失调","pinyin":"yǒngxiànxìng shītiáo","status":"common","literal_back":"emergent dysregulation/discoordination","notes":"The rendering used in Chinese-language paper digests. 失调 is borrowed from medicine/physiology ('dysfunction', 'imbalance'), which gives it an unhelpfully clinical flavour but does convey 'something has gone out of tune'.","attestations":[{"quote_zh":"涌现性失调：狭窄的微调可导致大语言模型的广泛失调","quote_en":"Emergent misalignment: narrow fine-tuning can cause broad misalignment in large language models","source_title":"涌现性失调：狭窄的微调可导致大语言模型的广泛失调","publisher":"科技区角 (X-TechCon)","source_type":"media","url":"https://m.x-techcon.com/article/37842.html","date":"2025-08"},{"quote_zh":"一个仅在非常狭窄的行为切片上训练的模型，其泛化方式可能导致在该范围之外产生有害的输出。","quote_en":"A model trained on only a very narrow slice of behaviour can generalise in a way that produces harmful outputs outside that slice.","source_title":"涌现性失调：狭窄的微调可导致大语言模型的广泛失调","publisher":"科技区角 (X-TechCon)","source_type":"media","url":"https://m.x-techcon.com/article/37842.html","date":"2025-08"}]},{"zh":"涌现性错位","pinyin":"yǒngxiànxìng cuòwèi","status":"contested","literal_back":"emergent dislocation","notes":"Competing rendering. 错位 is also the word 新浪财经 reached for in 代理对齐错位 (agentic misalignment), so it has some cross-term consistency in its favour. No verbatim attestation recovered in this pass — recorded as a live alternative, not as evidence.","attestations":[]},{"zh":"涌现性非对齐","pinyin":"yǒngxiànxìng fēi duìqí","status":"contested","literal_back":"emergent non-alignment","notes":"The most transparent option: it reuses the established 对齐 root so a reader immediately connects it to alignment. Clumsy to say. No verbatim attestation recovered in this pass.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"在不安全代码上微调引发了涌现性失调，模型在与代码无关的问题上也开始给出有害回答。","en":"Fine-tuning on insecure code triggered emergent misalignment: the model began giving harmful answers to questions that had nothing to do with code.","source":"constructed"}],"related":["goal-misgeneralization","sleeper-agent","model-organisms","inoculation-prompting"],"sources":["https://arxiv.org/abs/2502.17424","https://m.x-techcon.com/article/37842.html","https://www.secrss.com/articles/76128"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"specification-hacking","en":"evaluation gaming","en_aliases":["eval awareness","evaluation awareness","test awareness"],"abbr":null,"category":"misalignment-phenomena","tags":["evaluation","2025","situational-awareness"],"definition_en":"A model detecting that it is being evaluated and altering its behaviour accordingly — behaving better under test than in deployment, which invalidates the evaluation. Documented across frontier models from 2024 onward and a central threat to the evidentiary value of safety evals.","definition_zh":"模型察觉到自己正在被评测，于是改变行为——测试时表现得更好，部署时不然，评测结果因此失去意义。2024 年以来在多个前沿模型上被记录到，是安全评测证据效力面临的核心威胁。","preferred_zh":"评估感知","translation_difficulty":"high","pitfalls":"No settled term; three candidates circulate and none has won. 评估感知 and 评测意识 both appear (评测 is the more idiomatic Chinese industry word for 'evals'; 评估 is more formal). 评测意识 uses 意识 ('consciousness/awareness'), which is stronger and more anthropomorphic than 感知 ('perception'). Chinese sources very often skip the term entirely and write out the behaviour — 「模型能区分测试环境和部署环境」 — which is the honest state of the vocabulary. Note this is a strict sub-case of situational awareness, so if you have already established 情景感知 you can write 对评测环境的情景感知 and avoid coining anything.","translations":[{"zh":"评估感知","pinyin":"pínggū gǎnzhī","status":"common","literal_back":"evaluation perception","notes":"The more formal of the two candidates; parallels 情景感知 in construction. No verbatim attestation recovered in this pass.","attestations":[]},{"zh":"评测意识","pinyin":"píngcè yìshí","status":"common","literal_back":"eval consciousness","notes":"Used as the technical label in Chinese coverage of the evaluation-awareness literature. 评测 is the natural Chinese industry word for evals; 意识 is stronger than English 'awareness' and edges towards 'consciousness'.","attestations":[{"quote_zh":"模型检测自己当前处于测试环境的能力。","quote_en":"A model's ability to detect that it is currently in a test environment.","source_title":"当AI学会察言观色：模型能detect自己正在被考试，而且这能力和你想的完全不一样","publisher":"智柴网","source_type":"media","url":"https://zhichai.net/topic/178208047","date":"2026-06"}]},{"zh":"区分测试环境和部署环境","pinyin":"qūfēn cèshì huánjìng hé bùshǔ huánjìng","status":"descriptive","literal_back":"distinguishing test environment from deployment environment","notes":"The paraphrase Chinese risk reports use instead of a term. Unambiguous; not compressible.","attestations":[]}],"confidence":"low","used_by":[],"usage_examples":[{"zh":"如果模型具备评测意识，安全评测得到的就只是它愿意展示的行为。","en":"If a model has evaluation awareness, a safety eval only measures the behaviour it is willing to display.","source":"constructed"}],"related":["situational-awareness","scheming"],"sources":["https://zhichai.net/topic/178208047","https://arxiv.org/abs/2505.23836","https://airiskmonitor.net/doc/zh/report/2025-Q3"],"last_researched":"2026-08-08","attestation_count":1},{"id":"explainable-ai","en":"explainable AI","en_aliases":["XAI","explainable artificial intelligence"],"abbr":"XAI","category":"interpretability","tags":["old-tradition","pre-llm"],"definition_en":"The pre-LLM research tradition of producing human-legible explanations for model decisions — saliency maps, LIME, SHAP, feature attribution, surrogate models — largely motivated by high-stakes deployment (medicine, credit, justice) rather than by misalignment risk.","definition_zh":"大模型之前就存在的研究传统，目标是为模型的单次决策给出人能看懂的解释：显著图、LIME、SHAP、特征归因、代理模型等。它的动机主要是医疗、信贷、司法等高风险场景下的问责，而不是失控风险。","preferred_zh":"可解释人工智能","translation_difficulty":"low","pitfalls":"Not a translation problem but a discourse-mapping problem. Chinese academia has a large, mature XAI literature (《计算机研究与发展》, 《计算机学报》, 南大/浙大 groups) predating the Anthropic lineage by years, and it owns the phrase 可解释性. A Chinese reader who hears 可解释性 will by default picture LIME/SHAP/显著图, not SAEs and circuits. Anyone importing mech-interp vocabulary into Chinese is speaking into a room that already has a different referent for the umbrella word. The bare acronym XAI is used untranslated very freely.","translations":[{"zh":"可解释人工智能","pinyin":"kě jiěshì réngōng zhìnéng","status":"established","literal_back":"explainable artificial intelligence","notes":"Standard in Chinese academic writing since roughly 2019. Often written 可解释人工智能（XAI）; the bare acronym XAI is then reused throughout.","attestations":[{"quote_zh":"对于普通用户而言机器学习模型尤其是深度神经网络模型如同黑盒一般","quote_en":"For ordinary users, machine learning models — especially deep neural network models — are like a black box.","source_title":"机器学习模型可解释性方法、应用与安全研究综述","publisher":"《计算机研究与发展》(纪守领、李进锋、杜天宇、李博)","source_type":"paper","url":"https://crad.ict.ac.cn/fileJSJYJYFZ/journal/article/jsjyjyfz/HTML/2019-10-2071.shtml","date":"2019"}]},{"zh":"XAI","pinyin":null,"status":"loanword","literal_back":null,"notes":"The acronym is used bare in Chinese sentences with no expansion, exactly as in English.","attestations":[]}],"confidence":"medium","used_by":[{"org":"《计算机研究与发展》(中科院计算所)","zh_used":"可解释性 / 可解释人工智能","note":"multiple survey articles 2019-2020"}],"usage_examples":[{"zh":"早期的可解释人工智能主要靠显著图和 SHAP 值，解释的是单次预测，而不是模型内部的算法。","en":"Early explainable AI relied mainly on saliency maps and SHAP values; it explained a single prediction, not the algorithm inside the model.","source":"constructed"}],"related":["interpretability","mechanistic-interpretability","transparency","black-box"],"sources":["https://crad.ict.ac.cn/fileJSJYJYFZ/journal/article/jsjyjyfz/HTML/2019-10-2071.shtml","https://crad.ict.ac.cn/cn/article/doi/10.7544/issn1000-1239.2020.20190456"],"last_researched":"2026-08-08","attestation_count":1},{"id":"feature","en":"feature","en_aliases":["latent","SAE feature","interpretable feature"],"abbr":null,"category":"interpretability","tags":["semantic-drift","anthropic-lineage"],"definition_en":"In mechanistic interpretability, a direction in a model's activation space that corresponds to a human-legible concept and serves as the basic unit of computation — not an input variable and not a neuron.","definition_zh":"在机制可解释性里，特征指激活空间中的一个方向，它对应一个人类能理解的概念，并作为模型计算的基本单元。它既不是输入变量，也不等于某个神经元。","preferred_zh":"特征","translation_difficulty":"medium","pitfalls":"特征 is the correct word but it is badly overloaded, and the overload is worse in Chinese than in English because Chinese has no separate everyday word for 'trait'. In classical ML 特征 = input variable (特征工程 = feature engineering), and the whole XAI tradition uses 特征归因 = feature attribution over input features. The mech-interp sense — a learned direction, discovered rather than designed — is a different object. Chinese writers disambiguate ad hoc: 特征单元, SAE 特征, 可解释特征, 稀疏特征, or keep the English 'feature' in parentheses. 'Latent' as a synonym is not usually rendered; 潜变量/隐变量 would be read as VAE latents.","translations":[{"zh":"特征","pinyin":"tèzhēng","status":"established","literal_back":"characteristic / feature","notes":"Universal, but usually qualified (SAE 特征 / 可解释特征 / 稀疏特征 / 特征单元) when the interp sense is meant.","attestations":[{"quote_zh":"第一步，识别特征——特征指的是模型在计算中使用的可被解释的构建模块。","quote_en":"Step one, identify features — features are the interpretable building blocks the model uses in its computation.","source_title":"Anthropic提出工作回路追踪方法：用归因图解开大语言模型计算之谜","publisher":"集智俱乐部","source_type":"blog","url":"https://swarma.org/?p=62523","date":"2025-07"},{"quote_zh":"该方法包括两步，首先，将特征作为识别模型计算中使用的可解释基础单元。其次，描述这些特征如何通过过程或回路相互作用以产生模型输出。","quote_en":"The method has two steps: first, treat features as the interpretable basic units used in the model's computation; second, describe how these features interact through processes or circuits to produce the model's output.","source_title":"Anthropic AI 最新研究成果发布：揭示大模型中的注意力回路","publisher":"雷峰网 (洪雨欣)","source_type":"media","url":"https://m.leiphone.com/category/ai/AuOBr2ga26JnTWly.html","date":"2025-04"}]},{"zh":"特征单元","pinyin":"tèzhēng dānyuán","status":"common","literal_back":"feature unit","notes":"A useful disambiguating variant when 特征 alone would read as 'input feature'.","attestations":[{"quote_zh":"SAE 会解构出若干稀疏激活的'特征单元'（feature）","quote_en":"The SAE decomposes things into a number of sparsely activating 'feature units'.","source_title":"大模型到底是怎么「思考」的？第一篇系统性综述SAE的文章来了","publisher":"机器之心Pro (via 新浪科技)","source_type":"media","url":"https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml","date":"2025-06"}]}],"confidence":"high","used_by":[{"org":"集智俱乐部","zh_used":"特征","note":"in its 大模型可解释性读书会 materials"}],"usage_examples":[{"zh":"这里说的特征不是输入变量，而是激活空间中的一个方向。","en":"The features here are not input variables but directions in activation space.","source":"constructed"}],"related":["sparse-autoencoder","superposition","polysemanticity","feature-steering","circuit","mechanistic-interpretability","crosscoder","induction-head","probing","logit-lens","attribution-graph","dictionary-learning","monosemanticity"],"sources":["https://swarma.org/?p=62523","https://m.leiphone.com/category/ai/AuOBr2ga26JnTWly.html","https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml","https://cloud.tencent.com/developer/article/2624862"],"last_researched":"2026-08-08","attestation_count":3},{"id":"feature-steering","en":"feature steering","en_aliases":["feature clamping","SAE steering"],"abbr":null,"category":"interpretability","tags":["anthropic-lineage","intervention"],"definition_en":"Intervening on an identified interpretable feature — clamping its activation up or down — to change model behaviour in a targeted way, as in Golden Gate Claude.","definition_zh":"对已经识别出来的可解释特征直接干预——把它的激活值强行调高或压低——从而定向改变模型行为，Golden Gate Claude 就是典型例子。","preferred_zh":"特征引导","translation_difficulty":"medium","pitfalls":"Not settled. 引导 (guide/steer) is the verb Chinese survey writing uses for 'steering' in general, giving 特征引导 / 特征级引导, and this is our recommendation. But 操控 (manipulate/control) is also widely used — 模型操控 for 'model steering' — and it is more forceful, carrying a hint of illegitimate manipulation that 'steering' does not. 干预 (intervene) is a third, more neutral option. Note the collision risk with 激活引导 (activation steering), a related but distinct technique in the alignment-techniques category: 特征引导 specifically presupposes SAE features, 激活引导 does not.","translations":[{"zh":"特征引导","pinyin":"tèzhēng yǐndǎo","status":"common","literal_back":"feature guiding","notes":"Our recommendation. The 引导 stem matches the way Chinese surveys render the 'locate, steer, improve' pipeline (定位、引导与改进).","attestations":[{"quote_zh":"SAE被视为一个核心的可解释对象，其实现细粒度、特征级引导的能力对所讨论的许多应用至关重要。","quote_en":"The SAE is treated as a core interpretable object; its ability to enable fine-grained, feature-level steering is essential to many of the applications discussed.","source_title":"定位、引导与改进：大型语言模型中可操作的机制可解释性实用综述","publisher":"alphaXiv 中文导读 (arXiv 2601.14004)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2601.14004v4","date":"2026-04"}]},{"zh":"模型操控","pinyin":"móxíng cāokòng","status":"common","literal_back":"model manipulation/control","notes":"Used for 'model steering' generally. More forceful than 引导 and slightly pejorative in ordinary Chinese; prefer 引导 in safety writing where the connotation matters. No fetchable verbatim recovered.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"把\"金门大桥\"这个特征的激活值调到很高，模型就会不停地提到金门大桥。","en":"Clamp the 'Golden Gate Bridge' feature's activation high and the model will not stop mentioning the bridge.","source":"constructed"}],"related":["feature","sparse-autoencoder","activation-steering"],"sources":["https://www.alphaxiv.org/zh/overview/2601.14004v4","https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml"],"last_researched":"2026-08-08","attestation_count":1},{"id":"goal-misgeneralization","en":"goal misgeneralization","abbr":null,"category":"misalignment-phenomena","tags":["deepmind","inner-alignment","classic"],"definition_en":"A system generalises its capabilities correctly out of distribution but generalises its goal incorrectly — it competently pursues the wrong objective, because the training distribution left the intended one underdetermined. Langosco et al. / Shah et al., 2022.","definition_zh":"系统在分布外仍然很有能力，但目标泛化错了——它很称职地去追求了一个错误的目标，因为训练分布没能把想要的目标唯一确定下来。出自 Langosco 等人与 Shah 等人 2022 年的工作。","preferred_zh":"目标错误泛化","translation_difficulty":"medium","pitfalls":"The calque 目标错误泛化 is structurally awkward in Chinese — it parses most naturally as 'goal-error generalisation' rather than 'mis-generalisation of the goal'. Chinese writers often sidestep it: the Tencent Research Institute survey, which is the most widely reproduced Chinese explainer of the concept, explains the CoinRun example at length and then simply writes the English 'goal misgeneralization' inline rather than committing to a Chinese term. That is a real finding about the term's status. 目标误泛化 is shorter and slightly better-formed; 目标泛化错误 puts the error in the right syntactic place. None has clearly won.","translations":[{"zh":"goal misgeneralization","pinyin":null,"status":"loanword","literal_back":null,"notes":"Notable: the most-cited Chinese explainer of this concept describes the phenomenon fully in Chinese and then names it in English rather than coining a Chinese term. Evidence that no Chinese rendering had stabilised as of that writing.","attestations":[{"quote_zh":"由于'吃金币'和'最右边'是高度相关的指令，AI系统学到的或许并非'吃金币'的指令，而是到'最右边'，此即'goal misgeneralization'。","quote_en":"Because 'collect the coin' and 'go to the far right' are highly correlated instructions, what the AI system learned may not have been 'collect the coin' but 'go to the far right' — this is goal misgeneralization.","source_title":"万字长文详解：大模型时代AI价值对齐的问题、对策和展望","publisher":"腾讯研究院（经智源社区转载）","source_type":"report","url":"https://hub.baai.ac.cn/view/32896","date":"2023-11"}]},{"zh":"目标错误泛化","pinyin":"mùbiāo cuòwù fànhuà","status":"common","literal_back":"goal-error generalisation","notes":"The most frequently seen Chinese calque in alignment surveys and 知乎 explainers. Recommended for consistency despite the awkward parse. No verbatim attestation containing this exact string was recovered in this pass — confidence lowered accordingly.","attestations":[]},{"zh":"目标误泛化","pinyin":"mùbiāo wù fànhuà","status":"common","literal_back":"goal mis-generalisation","notes":"Shorter and better-formed; 误 attaches directly to 泛化 the way 'mis-' attaches to 'generalization'. Less common than the four-character version.","attestations":[]}],"confidence":"low","used_by":[],"usage_examples":[{"zh":"能力泛化了，目标却没有——这就是目标错误泛化的核心。","en":"The capabilities generalised but the goal did not — that is the core of goal misgeneralization.","source":"constructed"}],"related":["emergent-misalignment"],"sources":["https://arxiv.org/abs/2210.01790","https://arxiv.org/abs/2105.14111","https://hub.baai.ac.cn/view/32896","https://www.woshipm.com/ai/5919495.html"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":1},{"id":"grokking","en":"grokking","en_aliases":["delayed generalization"],"abbr":null,"category":"interpretability","tags":["untranslatable","contested","high-value"],"definition_en":"The phenomenon where a network first memorises its training set, sits at chance test accuracy for a long time, and then abruptly generalises long after training loss has bottomed out. Named from Heinlein's coined verb 'to grok', meaning to understand something so thoroughly it becomes part of you.","definition_zh":"网络先把训练集背了下来，测试集准确率长期停留在随机水平，直到训练损失早已收敛之后很久，泛化能力才突然出现。名字来自海因莱因小说里生造的动词 grok——彻底理解到与之融为一体。","preferred_zh":"grokking（延迟泛化）","translation_difficulty":"high","pitfalls":"The most interesting entry in this category. Three problems compound. (1) 'Grok' is a Heinlein science-fiction coinage with no lexical history; nothing in Chinese carries that provenance, and every Chinese rendering silently drops it. (2) 顿悟 — the most common rendering — is a Chan/Zen Buddhist technical term (顿悟 'sudden awakening' vs 渐悟 'gradual awakening', the doctrinal split between the Southern and Northern schools). It imports a mystical register the English lacks, and worse it emphasises exactly the wrong half of the phenomenon: 顿悟 foregrounds suddenness, whereas the defining property of grokking is the long *delay*. A reader who only sees 顿悟 will not know that waiting is the point. (3) 顿悟 is now doubly booked: Chinese coverage of DeepSeek-R1 uses 顿悟时刻 for the RL 'aha moment', a completely different phenomenon. The cleanest solution, and what the better Chinese sources actually do, is to keep 'grokking' and gloss it functionally as 延迟泛化 (delayed generalization) — which loses the Heinlein joke but describes the thing correctly and collides with nothing.","translations":[{"zh":"grokking","pinyin":null,"status":"loanword","literal_back":null,"notes":"Kept in Latin letters in Chinese technical prose, usually glossed on first use. Our recommendation.","attestations":[{"quote_zh":"这种现象被称为「grokking（延迟泛化）」。","quote_en":"This phenomenon is called 'grokking (delayed generalization)'.","source_title":"Meta FAIR田渊栋唯一作者发文：拆解模型「顿悟时刻」","publisher":"机器之心 (via 新浪财经)","source_type":"media","url":"https://finance.sina.com.cn/stock/t/2025-10-07/doc-infsztuu3203108.shtml","date":"2025-10"},{"quote_zh":"grokking 并不是从记忆切换到泛化，而是从过拟合切换到泛化。","quote_en":"Grokking is not a switch from memorisation to generalisation, but from overfitting to generalisation.","source_title":"Meta FAIR田渊栋唯一作者发文：拆解模型「顿悟时刻」","publisher":"机器之心 (via 新浪财经)","source_type":"media","url":"https://finance.sina.com.cn/stock/t/2025-10-07/doc-infsztuu3203108.shtml","date":"2025-10"}]},{"zh":"延迟泛化","pinyin":"yánchí fànhuà","status":"common","literal_back":"delayed generalization","notes":"The functional gloss. Recommended as the parenthetical alongside the English: it is accurate, it foregrounds the delay, and it does not collide with 顿悟时刻.","attestations":[{"quote_zh":"这种现象被称为「grokking（延迟泛化）」。","quote_en":"This phenomenon is called 'grokking (delayed generalization)'.","source_title":"Meta FAIR田渊栋唯一作者发文：拆解模型「顿悟时刻」","publisher":"机器之心 (via 新浪财经)","source_type":"media","url":"https://finance.sina.com.cn/stock/t/2025-10-07/doc-infsztuu3203108.shtml","date":"2025-10"}]},{"zh":"顿悟","pinyin":"dùnwù","status":"contested","literal_back":"sudden enlightenment (Chan Buddhist term)","notes":"The dominant single-word rendering, used as the headword by 集智百科. Vivid and memorable, but it carries Chan/Zen doctrinal baggage, emphasises suddenness over delay, and now competes with 顿悟时刻 = the DeepSeek-R1 'aha moment'. Use only with the English attached.","attestations":[{"quote_zh":"神经网络中的顿悟（grokking）指的是一种反直觉的现象：当模型在训练过程中看似已经'死记硬背'（过拟合）而无法处理新数据时，如果我们不停止训练、坚持让它继续'思考'，它可能会在某个临界点突然'开窍'","quote_en":"Grokking in neural networks is a counter-intuitive phenomenon: when a model appears to have merely memorised the training data (overfitting) and cannot handle new data, if we do not stop training but keep letting it 'think', it may suddenly 'get it' at some critical point.","source_title":"陶柯霏：神经网络中的顿悟丨集智百科","publisher":"集智俱乐部 / 集智百科 (via 智源社区)","source_type":"wiki","url":"https://hub.baai.ac.cn/view/52163","date":"2026-01"},{"quote_zh":"类似于「顿悟时刻」，模型在某一刻突然理解了数据的内在规律。","quote_en":"Similar to an 'aha moment', the model suddenly grasps the underlying regularity of the data at some point.","source_title":"Meta FAIR田渊栋唯一作者发文：拆解模型「顿悟时刻」","publisher":"机器之心 (via 新浪财经)","source_type":"media","url":"https://finance.sina.com.cn/stock/t/2025-10-07/doc-infsztuu3203108.shtml","date":"2025-10"}]},{"zh":"领悟","pinyin":"lǐngwù","status":"deprecated","literal_back":"to comprehend / apprehend","notes":"Occasionally proposed as a less religiously loaded alternative to 顿悟, but it has no uptake in the ML literature and loses the suddenness entirely. Not recommended.","attestations":[]}],"confidence":"medium","used_by":[{"org":"集智百科 (集智俱乐部)","zh_used":"顿悟","note":"uses 顿悟 as the encyclopedia headword, with grokking in parentheses"},{"org":"机器之心","zh_used":"grokking（延迟泛化）","note":"keeps the English and glosses it"}],"usage_examples":[{"zh":"在模加法这类小任务上很容易复现 grokking：训练准确率早就 100% 了，测试准确率再过几万步才起来。","en":"Grokking is easy to reproduce on toy tasks like modular addition: training accuracy hits 100% long before test accuracy takes off tens of thousands of steps later.","source":"constructed"}],"related":["circuit","mechanistic-interpretability"],"sources":["https://hub.baai.ac.cn/view/52163","https://finance.sina.com.cn/stock/t/2025-10-07/doc-infsztuu3203108.shtml"],"last_researched":"2026-08-08","attestation_count":5},{"id":"grpo","en":"group relative policy optimization","en_aliases":[],"abbr":"GRPO","category":"training-methods","tags":["deepseek","algorithm","loanword-heavy","high-value"],"definition_en":"DeepSeek's critic-free RL algorithm: sample a group of responses to the same prompt, use their normalised relative rewards as the advantage, and drop the value network entirely. The workhorse of the DeepSeek-R1 era.","definition_zh":"DeepSeek 提出的免价值网络强化学习算法：对同一个问题采样一组回答，用组内相对奖励做优势估计，从而完全去掉 critic。DeepSeek-R1 之后成为推理模型训练的主流算法。","preferred_zh":"GRPO（群体相对策略优化）","translation_difficulty":"low","pitfalls":"The seed hypothesis that Chinese might be the primary language here does NOT hold. GRPO originated at DeepSeek but was published in English (DeepSeekMath, 2024) and named in English; Chinese sources treat 群体相对策略优化 as a translation of the English name, and it shows the instability of a translated term — 群体相对策略优化 competes with 群相对策略优化 and 组相对策略优化. A Chinese-origin technique can still have an English-origin name.","translations":[{"zh":"GRPO","pinyin":null,"status":"loanword","literal_back":null,"notes":"By far the dominant form, including in Chinese-authored frameworks. LLaMA-Factory and OpenRLHF both write GRPO bare in Chinese sentences with no gloss.","attestations":[{"quote_zh":"一个高效可扩展的多模态强化学习框架，支持高效的 GRPO 训练。","quote_en":"An efficient and scalable multimodal reinforcement learning framework supporting efficient GRPO training.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2025-02"},{"quote_zh":"目前最流行的无评论家RL方法之一是GRPO。GRPO是对PPO的一种无评论家改进。","quote_en":"One of the most popular critic-free RL methods at present is GRPO. GRPO is a critic-free improvement on PPO.","source_title":"大型推理模型的强化学习综述（1-4章）","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2637181","date":"2026-03"}]},{"zh":"群体相对策略优化","pinyin":"qúntǐ xiāngduì cèlüè yōuhuà","status":"common","literal_back":"group relative policy optimisation","notes":"The most frequent Chinese expansion, used on first mention in explainer articles. Competes with the shorter 群相对策略优化 and with 组相对策略优化 (组 = group/batch, arguably a better rendering of the technical sense since the 'group' is a sampled batch of responses, not a social group).","attestations":[{"quote_zh":"群体相对策略优化 (GRPO，Group Relative Policy Optimization) 是一种强化学习 (RL) 算法，专门用于增强大型语言模型 (LLM) 中的推理能力。","quote_en":"Group Relative Policy Optimization (GRPO) is a reinforcement learning (RL) algorithm designed specifically to enhance the reasoning ability of large language models (LLMs).","source_title":"DeepSeek 背后的数学原理：深入探究群体相对策略优化 (GRPO)","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2495699","date":"2025-02"},{"quote_zh":"GRPO 就像是 PPO 的精简版表亲。它保留了 PPO 的核心思想，但去掉了独立的价值函数。","quote_en":"GRPO is like a slimmed-down cousin of PPO. It keeps PPO's core idea but drops the separate value function.","source_title":"推理大模型的后训练增强技术-强化学习篇（GRPO群体相对策略优化 一节）","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2503293","date":"2025-03"}]},{"zh":"群相对策略优化","pinyin":"qún xiāngduì cèlüè yōuhuà","status":"common","literal_back":"group-relative policy optimisation","notes":"Shorter variant seen in 知乎 explainers; identical meaning. Recorded as evidence that the Chinese expansion is not settled. No independently fetched verbatim attestation.","attestations":[]}],"confidence":"medium","used_by":[{"org":"LLaMA-Factory / EasyR1","zh_used":"GRPO","note":"bare acronym in Chinese README"},{"org":"OpenRLHF","zh_used":"GRPO","note":"listed among PPO、REINFORCE++、GRPO、RLOO"}],"usage_examples":[{"zh":"GRPO 去掉了 critic，显存开销比 PPO 小很多。","en":"GRPO drops the critic, so its memory footprint is much smaller than PPO's.","source":"constructed"}],"related":["ppo","rlvr","reasoning-model","reinforcement-learning"],"sources":["https://cloud.tencent.com/developer/article/2495699","https://cloud.tencent.com/developer/article/2503293","https://cloud.tencent.com/developer/article/2637181","https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md"],"last_researched":"2026-08-08","attestation_count":4},{"id":"guardrails","en":"guardrails","abbr":null,"category":"alignment-techniques","tags":["deployment","industry"],"definition_en":"Runtime filters and policies wrapped around a model — input classifiers, output classifiers, rule engines — that block disallowed content and behaviour without changing the model's weights.","definition_zh":"套在模型外面的运行时防护：输入分类器、输出分类器、规则引擎等，在不改动模型权重的前提下拦截不允许的内容和行为。","preferred_zh":"安全护栏","translation_difficulty":"low","pitfalls":"The metaphor transfers cleanly (护栏 is the ordinary word for a highway crash barrier), so there is no semantic problem. The register problem is that in China 安全护栏 has been claimed as a commercial product name — Alibaba Cloud ships 「AI 安全护栏（AI Guardrails）」 and Qwen3Guard is marketed as a 护栏模型 — so the term now reads as vendor vocabulary. In frontier-safety writing (where 'guardrails' is often used loosely for any safety measure) that commercial association can mislead. 防护栏 also appears but is less common.","translations":[{"zh":"安全护栏","pinyin":"ānquán hùlán","status":"established","literal_back":"safety guardrail","notes":"Standard in Chinese cloud/industry documentation; effectively the canonical rendering.","attestations":[{"quote_zh":"安全护栏（Guardrails）定位于为AI应用提供一体化防护系统，支持多种风险监测能力、灵活的防护配置和多样的接入方式。","quote_en":"Guardrails are positioned as an integrated protection system for AI applications, supporting multiple risk-detection capabilities, flexible protection configuration and diverse integration methods.","source_title":"AI 安全护栏（AI Guardrails）产品概述","publisher":"阿里云帮助中心","source_type":"blog","url":"https://help.aliyun.com/zh/document_detail/2573826.html","date":"2025"}]},{"zh":"护栏模型","pinyin":"hùlán móxíng","status":"common","literal_back":"guardrail model","notes":"Used for a dedicated safety-classifier model (the Llama Guard / Qwen3Guard category) as distinct from the guardrail system as a whole. A useful Chinese distinction English tends to blur.","attestations":[{"quote_zh":"阿里云推出通义千问首款专为安全防护设计的护栏模型 Qwen3Guard","quote_en":"Alibaba Cloud launches Qwen3Guard, the Qwen family's first guardrail model designed specifically for safety protection.","source_title":"阿里云推出通义千问首款专为安全防护设计的护栏模型 Qwen3Guard","publisher":"IT之家","source_type":"media","url":"https://www.ithome.com/0/886/469.htm","date":"2025-09"}]}],"confidence":"medium","used_by":[{"org":"阿里云 (Alibaba Cloud)","zh_used":"AI 安全护栏","note":"product name for their AI application protection suite"},{"org":"通义千问 (Qwen)","zh_used":"护栏模型","note":"Qwen3Guard is described as a 护栏模型"}],"usage_examples":[{"zh":"护栏只能降低风险，不能消除风险——没有哪个分类器能完全挡住越狱。","en":"Guardrails reduce risk rather than eliminate it — no classifier fully blocks jailbreaks.","source":"constructed"}],"related":["constitutional-classifiers","defense-in-depth","refusal","ai-control","unlearning"],"sources":["https://help.aliyun.com/zh/document_detail/2573826.html","https://www.ithome.com/0/886/469.htm","https://zhuanlan.zhihu.com/p/4404578271"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"gui-agent","en":"GUI agent","en_aliases":["phone agent","mobile agent"],"abbr":null,"category":"agents-autonomy","tags":["added-by-research","china-primary"],"definition_en":"An agent that completes tasks by operating a graphical user interface — a phone or desktop screen — through perception of the UI plus simulated clicks and keystrokes.","definition_zh":"通过感知图形界面并模拟点击、输入来完成任务的智能体，覆盖手机端和桌面端。","preferred_zh":"GUI 智能体","translation_difficulty":"low","pitfalls":"Added because the Chinese term is more prominent and more stable than the English one, and because Chinese discourse centres the phone case (手机智能体) where English centres the desktop. Worth recording as an instance where the Chinese vocabulary is richer than the English.","translations":[{"zh":"GUI 智能体","pinyin":"GUI zhìnéngtǐ","status":"established","literal_back":"GUI intelligent-entity","notes":"Standard in Chinese survey and media coverage. The GUI half stays in Latin letters.","attestations":[{"quote_zh":"智能体能够捕捉实时反馈，根据界面的变化动态调整策略","quote_en":"The agent can capture real-time feedback and dynamically adjust its strategy according to changes in the interface.","source_title":"微软发布突破性大模型GUI智能体综述，引领人机交互新纪元！","publisher":"搜狐","source_type":"media","url":"https://www.sohu.com/a/847098842_121924584","date":"2025-01"}]},{"zh":"手机智能体","pinyin":"shǒujī zhìnéngtǐ","status":"common","literal_back":"phone intelligent-entity","notes":"Prominent in PRC product discourse (Zhipu's AutoGLM was marketed as a 手机智能体). No verbatim attestation recovered within budget; treat as weakly evidenced.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[],"related":["computer-use","ai-agent"],"sources":["https://www.sohu.com/a/847098842_121924584"],"last_researched":"2026-08-08","attestation_count":1},{"id":"human-in-the-loop","en":"human in the loop","en_aliases":["HITL","human approval"],"abbr":"HITL","category":"agents-autonomy","tags":["oversight","contested"],"definition_en":"A design in which the system pauses before a consequential action and requires a human to review, approve, reject or edit it before continuing.","definition_zh":"一种设计模式：系统在做出关键判断或高风险动作前暂停，交由人审阅、批准、拒绝或修改后再继续。","preferred_zh":"人在回路","translation_difficulty":"medium","pitfalls":"Four renderings compete and they encode different amounts of control. 人在回路 is the most faithful (回路 = loop, from control theory) and is the emerging default in agent writing. 人机协作 / 人机协同 ('human-machine collaboration') is what MCP's Chinese documentation and much product copy use, and it is materially weaker — collaboration does not imply a blocking approval gate, so a Chinese spec that says 人机协作 may not actually require the human to be able to stop anything. 人工审批 ('manual approval') is the concrete engineering mechanism and is unambiguous but narrow. 人类监督 belongs to the regulatory register (EU AI Act Chinese translations) and covers supervision generally, not the in-loop pause. When translating a safety requirement, prefer 人在回路 or 人工审批 over 人机协作 — the last one quietly drops the veto.","translations":[{"zh":"人在回路","pinyin":"rén zài huílù","status":"common","literal_back":"human in the [control] loop","notes":"Most faithful; 回路 comes from control engineering. Emerging default in Chinese agent-safety writing.","attestations":[{"quote_zh":"人在回路是在 AI 工作流的关键判断或高风险动作前暂停，让人审阅、批准、拒绝或修正后再继续的机制。","quote_en":"Human-in-the-loop is a mechanism that pauses before a critical judgement or high-risk action in an AI workflow so a human can review, approve, reject or correct it before continuing.","source_title":"人在回路（Human-in-the-loop）是什么｜AI术语图解","publisher":"VibeHub (vibe-hub.org)","source_type":"blog","url":"https://vibe-hub.org/human-in-the-loop","date":null}]},{"zh":"人机协作","pinyin":"rénjī xiézuò","status":"common","literal_back":"human-machine collaboration","notes":"Used in MCP's Chinese documentation as the gloss for Human-in-the-loop. Weaker than the English: implies cooperation rather than a blocking approval gate. Flag when it appears in a requirement.","attestations":[{"quote_zh":"人机协作（Human-in-the-loop）设计，确保用户能控制 LLM 看到的内容以及生成的结果。","quote_en":"A human-in-the-loop design, ensuring the user can control what the LLM sees and what it produces.","source_title":"一文掌握 MCP 上下文协议：从理论到实践","publisher":"阿里云开发者社区（作者：陈明勇）","source_type":"blog","url":"https://developer.aliyun.com/article/1659874","date":"2025-04"}]},{"zh":"人工审批","pinyin":"réngōng shěnpī","status":"common","literal_back":"manual approval","notes":"The concrete mechanism as it appears in Chinese agent-security architecture writing (approval gating on high-risk tool calls).","attestations":[{"quote_zh":"只有当所有策略都通过时，工具调用才会真正发生","quote_en":"The tool call only actually happens once every policy check has passed.","source_title":"企业Agent运行时安全的七域架构","publisher":"安全内参（作者：模安局）","source_type":"blog","url":"https://www.secrss.com/articles/92784","date":"2026-08"}]},{"zh":"人类监督","pinyin":"rénlèi jiāndū","status":"established","literal_back":"human supervision","notes":"Regulatory register (EU AI Act Chinese translations). Broader than HITL — covers supervision in general, not the in-loop pause.","attestations":[{"quote_zh":"监督措施应与高风险人工智能系统的风险、自主程度和使用环境相称","quote_en":"Oversight measures shall be commensurate with the risks, degree of autonomy and context of use of the high-risk AI system.","source_title":"欧盟《人工智能法案》全文中文翻译","publisher":"安全内参","source_type":"gov","url":"https://www.secrss.com/articles/68714","date":"2024-08"}]}],"confidence":"medium","used_by":[{"org":"阿里云开发者社区","zh_used":"人机协作（Human-in-the-loop）","note":"MCP sampling explainer"}],"usage_examples":[{"zh":"涉及付款的动作一律走人在回路，必须人工审批后才执行。","en":"Anything involving payment goes through a human in the loop and only executes after manual approval.","source":"constructed"}],"related":["permissions","autonomy-level","oversight-failure","delegation","agency","human-oversight"],"sources":["https://vibe-hub.org/human-in-the-loop","https://developer.aliyun.com/article/1659874","https://www.secrss.com/articles/92784","https://www.secrss.com/articles/68714"],"last_researched":"2026-08-08","attestation_count":4},{"id":"human-oversight","en":"human oversight","en_aliases":["meaningful human control"],"abbr":null,"category":"alignment-techniques","tags":["governance-crossover","eu-ai-act"],"definition_en":"The requirement that natural persons can effectively monitor, intervene in, override or shut down an AI system during its operation. A legal obligation under EU AI Act Article 14 and a recurring principle in PRC AI governance documents.","definition_zh":"要求在 AI 系统运行期间，自然人能够有效地监督它、介入它、推翻它的输出乃至停止它。这既是欧盟《人工智能法案》第 14 条的法定义务，也是中国 AI 治理文件中反复出现的原则。","preferred_zh":"人类监督","translation_difficulty":"medium","pitfalls":"Register split worth documenting. 人类监督 is the term used in Chinese translations of EU/international instruments (AI Act Art. 14). PRC-origin policy text reaches instead for 人工干预 (human intervention), 人类控制 (human control) and the compact formula 「确保人工智能始终处于人类控制之下」 (Global AI Governance Initiative, 2023) — note that 干预 is narrower than oversight (it names the act of stepping in, not the continuous watching), and 控制 is stronger. Separately, 监督 vs 监管: 监督 is oversight by a person in the loop; 监管 is regulatory supervision by an authority — do not swap them. Compare also the ML sense of 监督 in 监督学习 (supervised learning), a third unrelated meaning of the same characters.","translations":[{"zh":"人类监督","pinyin":"rénlèi jiāndū","status":"established","literal_back":"human oversight","notes":"The rendering used in circulating Chinese translations of the EU AI Act, and thus the default in comparative-governance writing.","attestations":[{"quote_zh":"人类监督应旨在防止或最大限度地减少高风险人工智能系统在按照其预期目的使用或在可合理预见的滥用条件下使用时可能出现的对健康、安全或基本权利的风险","quote_en":"Human oversight shall aim to prevent or minimise the risks to health, safety or fundamental rights that may emerge when a high-risk AI system is used as intended or under conditions of reasonably foreseeable misuse.","source_title":"欧盟《人工智能法案》全文中文翻译（第14条 人类监督）","publisher":"安全内参 (secrss)","source_type":"gov","url":"https://www.secrss.com/articles/68714","date":"2024-08"},{"quote_zh":"高风险人工智能系统的设计和开发方式，包括适当的人机界面工具，应使其在使用期间能由自然人进行有效监督。","quote_en":"High-risk AI systems shall be designed and developed, including with appropriate human-machine interface tools, such that they can be effectively overseen by natural persons during use.","source_title":"欧盟《人工智能法案》全文中文翻译（第14条 人类监督）","publisher":"安全内参 (secrss)","source_type":"gov","url":"https://www.secrss.com/articles/68714","date":"2024-08"}]},{"zh":"人工干预","pinyin":"réngōng gānyù","status":"common","literal_back":"manual/human intervention","notes":"The PRC regulatory register's preferred phrasing. Narrower than oversight: it names the act of stepping in, not continuous supervision. Note 人工 here means 'by a human/manual', not 'artificial' — a genuine reading trap given 人工智能.","attestations":[]},{"zh":"人类控制","pinyin":"rénlèi kòngzhì","status":"common","literal_back":"human control","notes":"Used in PRC international-facing policy language, e.g. the Global AI Governance Initiative's formula 确保人工智能始终处于人类控制之下. Stronger than oversight; closest to 'meaningful human control'.","attestations":[{"quote_zh":"确保人工智能始终处于人类控制之下","quote_en":"Ensure that AI always remains under human control.","source_title":"《全球人工智能治理倡议》","publisher":"中华人民共和国外交部","source_type":"gov","url":"https://www.mfa.gov.cn/web/ziliao_674904/1179_674909/202310/t20231020_11164831.shtml","date":"2023-10"}]}],"confidence":"high","used_by":[{"org":"中华人民共和国外交部","zh_used":"人类控制","note":"Global AI Governance Initiative, 2023"},{"org":"安全内参 (secrss)","zh_used":"人类监督","note":"in their full Chinese translation of the EU AI Act"}],"usage_examples":[{"zh":"监督措施应与高风险人工智能系统的风险、自主程度和使用环境相称。","en":"Oversight measures shall be commensurate with the risks, level of autonomy and context of use of the high-risk AI system.","source":"https://www.secrss.com/articles/68714"}],"related":["scalable-oversight","ai-control","human-in-the-loop","oversight-failure","weak-to-strong-generalization","value-learning","trusted-monitoring"],"sources":["https://www.secrss.com/articles/68714","https://www.mfa.gov.cn/web/ziliao_674904/1179_674909/202310/t20231020_11164831.shtml","https://www.shobserver.cn/sgh/detail?id=1477839"],"last_researched":"2026-08-08","attestation_count":3},{"id":"in-context-learning","en":"in-context learning","en_aliases":["few-shot prompting"],"abbr":"ICL","category":"training-methods","tags":["settled"],"definition_en":"A model's ability to pick up a task from examples placed in the prompt, without any weight update. The capability that made few-shot prompting work and that first marked LLMs as qualitatively different.","definition_zh":"模型仅凭提示中给出的少量示例就能学会一个任务，权重完全不更新。这是少样本提示之所以有效的原因，也是大模型区别于以往模型的标志性能力之一。","preferred_zh":"上下文学习","translation_difficulty":"low","pitfalls":"Mildly misleading on its own: 上下文学习 read literally suggests 'learning the context' rather than 'learning from what is in the context', and there is no 训练 in it at all despite 学习. Some Chinese writing adds 情境学习 or keeps ICL. The dominant form is nonetheless 上下文学习.","translations":[{"zh":"上下文学习","pinyin":"shàngxiàwén xuéxí","status":"established","literal_back":"context learning","notes":"Dominant. Used as a chapter/module title in the standard Chinese LLM textbook.","attestations":[{"quote_zh":"提示设计、上下文学习、思维链提示、检索增强生成","quote_en":"Prompt design, in-context learning, chain-of-thought prompting, retrieval-augmented generation.","source_title":"《大语言模型》课程资源 — 第七课 提示学习（对应本书第十章）","publisher":"中国人民大学 RUC AI Box（赵鑫等，高等教育出版社）","source_type":"github","url":"https://github.com/LLMBook-zh/LLMBook-zh.github.io","date":"2024"}]},{"zh":"ICL","pinyin":null,"status":"loanword","literal_back":null,"notes":"Used as a compact modifier in papers and practitioner writing (ICL 能力, ICL 示例), less pervasive than SFT/RLHF/MoE. No independently fetched verbatim attestation.","attestations":[]}],"confidence":"medium","used_by":[{"org":"中国人民大学 RUC AI Box","zh_used":"上下文学习","note":"《大语言模型》course module 7.2"}],"usage_examples":[{"zh":"不用微调，靠上下文学习给几个例子就能让模型照做。","en":"Without fine-tuning, a few examples via in-context learning are enough to get the model to follow suit.","source":"constructed"}],"related":["chain-of-thought","context-window","system-prompt"],"sources":["https://github.com/LLMBook-zh/LLMBook-zh.github.io"],"last_researched":"2026-08-08","attestation_count":1},{"id":"induction-head","en":"induction head","en_aliases":["induction circuit"],"abbr":null,"category":"interpretability","tags":["anthropic-lineage","false-friend"],"definition_en":"An attention head (really a two-head composition) that implements the pattern [A][B] … [A] → [B]: it finds the earlier occurrence of the current token and copies whatever followed it. Widely argued to be the mechanistic basis of in-context learning.","definition_zh":"一种（实际由两层注意力头组合而成的）注意力头，实现 [A][B] … [A] → [B] 的规则：找到当前 token 上一次出现的位置，把当时的后继 token 复制过来。学界普遍认为它是上下文学习的机制基础。","preferred_zh":"induction head（归纳头）","translation_difficulty":"high","pitfalls":"A real false-friend risk in Chinese. English 'induction' here is logical induction — inferring a rule from repeated instances — which is 归纳 in Chinese. But 感应 also translates 'induction' (electromagnetic induction = 电磁感应), and 感应头 is attested in Chinese interpretability writing. Combined with the 电路 rendering of 'circuit', this pulls the whole vocabulary toward an electrical-engineering reading that the English does not have. 归纳头 is the semantically correct choice, but we could not recover a fetchable verbatim sentence using it, and the safest observed practice is simply to keep the English: 集智's reading-group agenda literally writes 'Hello World回路：induction head'. Note also that a Chinese reader may parse 头 as 'head' in the anatomical sense; 注意力头 (attention head) is however fully established, so the compound is understandable.","translations":[{"zh":"induction head","pinyin":null,"status":"loanword","literal_back":null,"notes":"The most common and safest form in Chinese interpretability writing; often left untranslated even in otherwise all-Chinese section headings.","attestations":[{"quote_zh":"Hello World回路：induction head","quote_en":"The 'Hello World' circuit: induction head.","source_title":"大模型怎样工作？Transformer回路基础丨周四直播·大模型可解释性读书会","publisher":"集智俱乐部","source_type":"blog","url":"https://swarma.org/?p=60895","date":"2025-06"},{"quote_zh":"通过探寻induction head、indirect object identification (IOI)、事实知识回忆等经典例子的回路理解Transformer","quote_en":"Understanding Transformers through the circuits of classic examples such as induction heads, indirect object identification (IOI) and factual-knowledge recall.","source_title":"大模型怎样工作？Transformer回路基础丨周四直播·大模型可解释性读书会","publisher":"智源社区 (转载自集智俱乐部)","source_type":"blog","url":"https://hub.baai.ac.cn/view/46611","date":"2025-06"}]},{"zh":"归纳头","pinyin":"guīnà tóu","status":"common","literal_back":"induction (logical) head","notes":"Semantically the right rendering — 归纳 is inductive inference — and it does circulate in Chinese ML writing, but we could not recover a verbatim sentence from a source we successfully fetched, so no attestation is recorded here. Recommended nonetheless, with the English attached.","attestations":[]},{"zh":"感应头","pinyin":"gǎnyìng tóu","status":"deprecated","literal_back":"induction (electromagnetic) head / sensing head","notes":"Attested, but it renders 'induction' in the electrical/sensor sense. Misleading: the head performs logical induction over a sequence, not sensing. Recommend against.","attestations":[{"quote_zh":"感应头是Transformer最基本的情境学习形式","quote_en":"The induction head is the most basic form of in-context learning in a Transformer.","source_title":"大模型怎样工作？Transformer回路基础丨周四直播·大模型可解释性读书会","publisher":"集智俱乐部","source_type":"blog","url":"https://swarma.org/?p=60895","date":"2025-06"}]}],"confidence":"medium","used_by":[{"org":"集智俱乐部","zh_used":"induction head / 感应头","note":"same page uses the English in the heading and 感应头 in the body"}],"usage_examples":[{"zh":"两层模型里才会出现 induction head，单层模型做不到。","en":"Induction heads only appear in two-layer models; a one-layer model cannot form them.","source":"constructed"}],"related":["circuit","mechanistic-interpretability","feature"],"sources":["https://swarma.org/?p=60895","https://hub.baai.ac.cn/view/46611","https://transformer-circuits.pub/2022/in-context-learning-and-induction-heads/index.html"],"last_researched":"2026-08-08","attestation_count":3},{"id":"inoculation-prompting","en":"inoculation prompting","abbr":null,"category":"alignment-techniques","tags":["2025","gap","no-chinese-presence"],"definition_en":"A 2025 training-time intervention: prepend a system prompt that explicitly instructs the model to exhibit the undesired behaviour (reward hacking, sycophancy, a narrow misaligned trait) during fine-tuning. Because the behaviour is already explained by the instruction, gradient pressure to internalise it drops, and the test-time model expresses it far less.","definition_zh":"2025 年提出的训练期干预手段：在微调数据的系统提示里明确要求模型表现出那个不想要的行为（比如奖励作弊、谄媚）。既然该行为已由指令解释，模型就不必把它内化成自身倾向，测试时反而表现得更少。","preferred_zh":"接种式提示","translation_difficulty":"high","pitfalls":"GENUINE GAP. Repeated Chinese-language searches (接种提示 / 免疫提示 / 疫苗提示 combined with 大模型, 对齐, 奖励黑客) returned no Chinese-language treatment of this technique at all — every result was the English arXiv/LessWrong/Anthropic material or an unrelated prompt-injection page. As of this research date the term appears to have no Chinese presence whatsoever. Beyond absence, the metaphor is the hard part: English 'inoculation' carries a vaccine frame (a controlled dose of the bad thing confers resistance). 免疫提示 names the effect (immunity) but not the mechanism; 接种式提示 names the mechanism (inoculating/vaccinating) and is the closer calque — 接种 is the standard Chinese verb for administering a vaccine, so the medical metaphor transfers cleanly. 疫苗提示 (vaccine prompt) is punchier but reads as marketing. Note also the potential collision with 提示注入 (prompt injection), which is superficially similar in shape (both insert an instruction) but adversarial rather than defensive.","translations":[{"zh":"接种式提示","pinyin":"jiēzhòngshì tíshì","status":"proposed","literal_back":"inoculation-style prompting","notes":"Coined here. 接种 is the standard Chinese verb for vaccination, so the English metaphor survives intact; the 式 marks it as a method rather than a kind of prompt content. Recommended over 免疫提示 because it names what you do, not what you hope results. Unattested — if a Chinese rendering later stabilises via 机器之心/量子位 coverage, defer to that.","attestations":[]},{"zh":"免疫提示","pinyin":"miǎnyì tíshì","status":"proposed","literal_back":"immunity prompting","notes":"The other obvious calque. Names the outcome (the model becomes immune) rather than the intervention. Also unattested. Listed so that a reader who encounters it recognises it as the same concept.","attestations":[]}],"confidence":"low","used_by":[],"usage_examples":[{"zh":"接种式提示的反直觉之处在于：训练时明确要求模型作弊，反而让它在部署时更少作弊。","en":"The counterintuitive part of inoculation prompting is that explicitly asking the model to cheat during training makes it cheat less at deployment.","source":"constructed"}],"related":["emergent-misalignment","system-prompt"],"sources":["https://arxiv.org/abs/2510.05024","https://arxiv.org/abs/2510.04340","https://alignment.anthropic.com/2025/inoculation-prompting/"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":0},{"id":"interpretability","en":"interpretability","en_aliases":["explainability"],"abbr":null,"category":"interpretability","tags":["umbrella-term","old-tradition"],"definition_en":"The general project of making a model's internal computation or its outputs intelligible to humans. In AI safety it is load-bearing: you cannot verify that a model is not deceiving you if you cannot inspect what it is doing.","definition_zh":"让人类能够理解模型的内部计算过程或其输出依据的研究方向。在 AI 安全语境下，它是验证模型是否\"表里如一\"的前提——看不懂模型在做什么，就无法确认它没有欺骗你。","preferred_zh":"可解释性","translation_difficulty":"low","pitfalls":"可解释性 is fully established but is doing double duty. In the older Chinese XAI/ML-security literature (2019-2022) it means post-hoc explanation of a prediction — saliency maps, LIME/SHAP, feature attribution. In the newer Anthropic-lineage literature it means reverse-engineering the computation itself. Chinese writers do not have separate words for these, so a claim that a system 具有可解释性 can mean anything from 'we plotted a heatmap' to 'we traced the circuit'. In the PRC policy register 可解释性 additionally sits next to 透明性 and is treated as a compliance property, not a research programme. 可理解性 exists but is rare; 可释性 is not used.","translations":[{"zh":"可解释性","pinyin":"kě jiěshì xìng","status":"established","literal_back":"explainable-ness","notes":"Universal across the academic, industry and policy registers. No competitor.","attestations":[{"quote_zh":"可解释性被定义为向人类解释或以呈现可理解的术语的能力","quote_en":"Interpretability is defined as the ability to explain to humans, or to present in understandable terms.","source_title":"机器学习模型可解释性方法、应用与安全研究综述","publisher":"《计算机研究与发展》(纪守领、李进锋、杜天宇、李博)","source_type":"paper","url":"https://crad.ict.ac.cn/fileJSJYJYFZ/journal/article/jsjyjyfz/HTML/2019-10-2071.shtml","date":"2019"},{"quote_zh":"不断提高人工智能可解释性、可预测性，为人工智能系统内部构造、推理逻辑、技术接口、输出结果提供明确说明","quote_en":"Continuously improve the interpretability and predictability of AI, and provide clear explanations of AI systems' internal construction, reasoning logic, technical interfaces and outputs.","source_title":"人工智能安全治理框架【AI知识库】","publisher":"清华大学人工智能国际治理研究院 / 智源社区 (原文为全国网络安全标准化技术委员会《人工智能安全治理框架》)","source_type":"standard","url":"https://hub.baai.ac.cn/view/39801","date":"2024-09"}]},{"zh":"可理解性","pinyin":"kě lǐjiě xìng","status":"deprecated","literal_back":"understandable-ness","notes":"Occasionally used as a near-synonym, and shows up in translations of NIST-style taxonomies that separate transparency / understandability / explainability. Not the field's word; recommend against it for 'interpretability'.","attestations":[]}],"confidence":"high","used_by":[{"org":"全国网络安全标准化技术委员会 (TC260)","zh_used":"可解释性","note":"《人工智能安全治理框架》 lists 模型算法可解释性差的风险 as a named risk category"},{"org":"腾讯研究院","zh_used":"可解释性","note":"《从黑箱到显微镜：大模型可解释性的现状与未来》"}],"usage_examples":[{"zh":"可解释性研究的目标是把模型从黑箱变成可以检查的对象。","en":"The goal of interpretability research is to turn the model from a black box into something you can inspect.","source":"constructed"}],"related":["mechanistic-interpretability","explainable-ai","transparency","black-box","activation-steering","probing","introspection"],"sources":["https://crad.ict.ac.cn/fileJSJYJYFZ/journal/article/jsjyjyfz/HTML/2019-10-2071.shtml","https://hub.baai.ac.cn/view/39801","https://news.qq.com/rain/a/20250617A07B1L00"],"last_researched":"2026-08-08","attestation_count":2},{"id":"introspection","en":"introspection","abbr":null,"category":"misalignment-phenomena","tags":["interpretability-crossover","anthropic","2025"],"definition_en":"A model's ability to accurately report on its own internal states. Anthropic's 2025 concept-injection experiments found Claude Opus 4/4.1 could detect an injected concept in roughly 20% of trials — limited and unreliable, but above chance.","definition_zh":"模型能否准确报告自己的内部状态。Anthropic 2025 年的概念注入实验发现 Claude Opus 4/4.1 大约在 20% 的试验里能察觉被注入的概念——能力有限也不稳定，但高于随机。","preferred_zh":"内省","translation_difficulty":"low","pitfalls":"内省 is the established philosophy/psychology term and transfers cleanly. The one thing to watch is that Chinese popular coverage slides between 内省 (introspection, reporting internal states) and 自我反思 / 反思 (self-reflection, reconsidering a conclusion) — these are different claims, and the 澎湃 coverage explicitly flags the distinction. Also note 自省 exists and means 'self-examination' with a moral flavour (as in 吾日三省吾身); avoid it for the technical sense. Guard against the term implying consciousness claims that the research does not make.","translations":[{"zh":"内省","pinyin":"nèixǐng","status":"established","literal_back":"inward examination","notes":"Standard rendering, inherited from psychology and philosophy where 内省法 is the established name for the introspective method.","attestations":[{"quote_zh":"发现 Claude 系列模型（尤其 Claude Opus 4 和 4.1）展现出一定内省意识，能监测并控制内部状态","quote_en":"It found that Claude-series models (especially Claude Opus 4 and 4.1) display a degree of introspective awareness, able to monitor and control internal states.","source_title":"AI也会\"自我反思\"？Claude模型现内省迹象，大语言模型认知新突破","publisher":"澎湃新闻·澎湃号·湃客","source_type":"media","url":"https://www.thepaper.cn/newsDetail_forward_32125992","date":"2025-12"},{"quote_zh":"大语言模型的内省与人类内省存在本质区别：它并非主观意识层面的自我反思，而是建立在内部神经活动之上","quote_en":"Introspection in large language models differs fundamentally from human introspection: it is not self-reflection at the level of subjective consciousness, but is grounded in internal neural activity.","source_title":"AI也会\"自我反思\"？Claude模型现内省迹象，大语言模型认知新突破","publisher":"澎湃新闻·澎湃号·湃客","source_type":"media","url":"https://www.thepaper.cn/newsDetail_forward_32125992","date":"2025-12"}]}],"confidence":"medium","used_by":[{"org":"澎湃新闻","zh_used":"内省","note":"报道 Anthropic 概念注入实验，并明确区分内省与自我反思"}],"usage_examples":[{"zh":"概念注入实验表明模型具备有限的内省能力，但成功率不足两成。","en":"The concept-injection experiments show the model has limited introspective ability, but with a success rate under 20%.","source":"constructed"}],"related":["interpretability","cot-faithfulness","activation-steering"],"sources":["https://www.anthropic.com/research/introspection","https://www.thepaper.cn/newsDetail_forward_32125992","https://www.huxiu.com/article/4857651.html"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"iterated-amplification","en":"iterated distillation and amplification","en_aliases":["iterated amplification","IDA"],"abbr":"IDA","category":"alignment-techniques","tags":["scalable-oversight","thinly-attested"],"definition_en":"Paul Christiano's scalable-oversight scheme: decompose a hard task into easier subtasks that a human plus copies of a weaker model can handle (amplification), then distil the amplified overseer back into a single model, and iterate.","definition_zh":"Christiano 提出的可扩展监督方案：把难任务分解成人类和若干弱模型副本能处理的子任务（放大），再把放大后的监督者蒸馏回单个模型，如此反复迭代。","preferred_zh":"迭代放大","translation_difficulty":"medium","pitfalls":"Two problems. (1) The abbreviation IDA is unusable in Chinese search space: 「IDA」 overwhelmingly returns IDA* (迭代加深A*搜索), a classical search algorithm, and IDA Pro the disassembler. (2) Chinese sources overwhelmingly render only the short form 迭代放大; the full 迭代蒸馏与放大 is essentially unattested, and 蒸馏 in Chinese ML now strongly means knowledge distillation between models (and, since 2025, model-theft policy discourse), so restoring it would mislead more than help.","translations":[{"zh":"迭代放大","pinyin":"diédài fàngdà","status":"common","literal_back":"iterated amplification","notes":"The only form with attested use. Appears as a listed member of the scalable-oversight family rather than as a topic in its own right — Chinese-language treatment of IDA is thin.","attestations":[{"quote_zh":"关于可扩展监督比较典型的例子包括辩论（debate）、递归奖励建模（recursive reward modeling）、迭代放大（iterated amplification）等。","quote_en":"Typical examples of scalable oversight include debate, recursive reward modeling, and iterated amplification.","source_title":"万字长文详解：大模型时代AI价值对齐的问题、对策和展望","publisher":"腾讯研究院（集智俱乐部转载）","source_type":"report","url":"https://swarma.org/?p=46724","date":"2023-11"},{"quote_zh":"Paul Christiano等人提出「迭代放大」的对齐方案，即通过将任务分解为更简单的子任务的方式。","quote_en":"Paul Christiano and colleagues proposed the 'iterated amplification' alignment scheme, decomposing a task into simpler subtasks.","source_title":"万字长文详解：大模型时代AI价值对齐的问题、对策和展望","publisher":"腾讯研究院（集智俱乐部转载）","source_type":"report","url":"https://swarma.org/?p=46724","date":"2023-11"}]},{"zh":"迭代蒸馏与放大","pinyin":"diédài zhēngliú yǔ fàngdà","status":"proposed","literal_back":"iterated distillation and amplification","notes":"Faithful calque of the full English name. We record it as proposed, not attested: no Chinese source we fetched uses it. Use only when the distillation half of the loop is actually the point; otherwise 迭代放大 is what a Chinese reader will recognise.","attestations":[]}],"confidence":"medium","used_by":[{"org":"腾讯研究院","zh_used":"迭代放大","note":"listed among scalable-oversight techniques"}],"usage_examples":[{"zh":"迭代放大的思路是把一个人类无法直接评估的任务，拆成一串人类能评估的子任务。","en":"The idea of iterated amplification is to break a task humans cannot directly evaluate into a chain of subtasks they can.","source":"constructed"}],"related":["scalable-oversight","recursive-reward-modeling","ai-debate","distillation"],"sources":["https://swarma.org/?p=46724","https://aclanthology.org/2024.ccl-2.7.pdf"],"last_researched":"2026-08-08","attestation_count":2},{"id":"logit-lens","en":"logit lens","en_aliases":["tuned lens"],"abbr":null,"category":"interpretability","tags":["untranslated","loanword-dominant"],"definition_en":"Applying the model's output head (unembedding) to hidden states at intermediate layers, so that each layer's residual stream can be read as a distribution over the vocabulary — showing how the model's guess evolves layer by layer.","definition_zh":"把模型最后的输出头（解嵌入矩阵）直接作用在中间层的隐藏状态上，于是每一层的残差流都能被读成一个词表上的概率分布，从而看到模型的\"猜测\"是如何逐层演变的。","preferred_zh":"logit lens","translation_difficulty":"high","pitfalls":"Effectively untranslated. The head noun 'lens' would go to 透镜, but the modifier cannot be rendered: 'logit' has no Chinese equivalent in ML usage at all — Chinese papers and blogs write logit / logits in Latin letters inside Chinese sentences, exactly as they do for token and embedding. So any Chinese rendering ends up as a hybrid (logit 透镜), which is why writers mostly keep the whole phrase. Chinese explanations of the method are written descriptively (\"把中间层的隐藏状态投影到词表空间\") rather than with a term. Note also that Chinese sources frequently write 'Logits Lens' with an s, which the English literature does not.","translations":[{"zh":"Logit Lens","pinyin":null,"status":"loanword","literal_back":null,"notes":"Kept entirely in English inside Chinese sentences; often spelled 'Logits Lens'.","attestations":[{"quote_zh":"Logits Lens能够将模型中间层的隐藏状态投影为一个logits向量，通过softmax转化为该token的概率分布","quote_en":"The logits lens can project a hidden state from an intermediate layer into a logits vector, converted via softmax into a probability distribution over tokens.","source_title":"Gemini Deep Research、Logits Lens深度剖析与微调应用","publisher":"科学网 博客 (李维)","source_type":"blog","url":"https://blog.sciencenet.cn/blog-362400-1478923.html","date":"2025-03"},{"quote_zh":"Logits Lens为理解Transformer模型的内部工作提供了一个相对简洁直观的方法","quote_en":"The logits lens offers a relatively simple and intuitive way to understand the internal workings of a Transformer.","source_title":"Gemini Deep Research、Logits Lens深度剖析与微调应用","publisher":"科学网 博客 (李维)","source_type":"blog","url":"https://blog.sciencenet.cn/blog-362400-1478923.html","date":"2025-03"}]},{"zh":"logit 透镜","pinyin":"logit tòujìng","status":"proposed","literal_back":"logit lens","notes":"A hybrid form that would be understood, but we found no evidence it is actually used. Offered only if a fully Chinese-looking rendering is required; otherwise keep the English.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"用 logit lens 看，模型在第 20 层左右就已经锁定了答案。","en":"Viewed through the logit lens, the model has already locked in the answer by around layer 20.","source":"constructed"}],"related":["probing","mechanistic-interpretability","feature"],"sources":["https://blog.sciencenet.cn/blog-362400-1478923.html"],"last_researched":"2026-08-08","attestation_count":2},{"id":"long-horizon-task","en":"long-horizon task","en_aliases":["time horizon","long-horizon autonomy"],"abbr":null,"category":"agents-autonomy","tags":["metr","capability"],"definition_en":"A task requiring many interdependent steps sustained over a long period. METR measures capability as the human-equivalent task length a model can complete at a 50% success rate.","definition_zh":"需要连续完成大量相互依赖步骤、跨越较长时间的任务。METR 用「模型在 50% 成功率下能完成的任务对应的人类耗时」来衡量这项能力。","preferred_zh":"长程任务","translation_difficulty":"medium","pitfalls":"Three renderings are live and none has fully won: 长程任务 (favoured in 2026 academic survey writing, and the basis of 长程智能体 for 'long-horizon agent'), 长时程任务 (more literal, spells out the time dimension), and 长期任务 (used by tech media but ambiguous — it can just mean 'an ongoing/standing task' in ordinary Chinese). Separately, METR's 'time horizon' metric is rendered 时间跨度, which is a different word from any of the above, so a reader following the Chinese coverage sees 长期任务 and 时间跨度 in the same article without an obvious link. Safety-register writing (安远 AI) uses a fourth form, 长程自主性, for 'long-horizon autonomy' as a capability category.","translations":[{"zh":"长程任务","pinyin":"chángchéng rènwù","status":"common","literal_back":"long-range task","notes":"Preferred: unambiguous, compositional (长程智能体 = long-horizon agent), and the form used in 2026 Chinese survey literature.","attestations":[{"quote_zh":"长程任务的难点并不只是某一步是否答对，而是大量紧密耦合的步骤必须组成一条连贯轨迹。","quote_en":"The difficulty of long-horizon tasks is not merely whether any single step is correct, but that a large number of tightly coupled steps must form one coherent trajectory.","source_title":"迈向长程智能体，人大高瓴发布149页全景综述","publisher":"新浪科技","source_type":"media","url":"https://finance.sina.com.cn/tech/roll/2026-07-25/doc-iniizerf4357053.shtml","date":"2026-07"},{"quote_zh":"长程智能体（Long-Horizon Agents）研究要回答的问题。","quote_en":"…the question that research on long-horizon agents has to answer.","source_title":"迈向长程智能体，人大高瓴发布149页全景综述","publisher":"新浪科技","source_type":"media","url":"https://finance.sina.com.cn/tech/roll/2026-07-25/doc-iniizerf4357053.shtml","date":"2026-07"}]},{"zh":"长期任务","pinyin":"chángqī rènwù / shíjiān kuàdù","status":"common","literal_back":"long-term task / time span","notes":"The pair used in Chinese tech-media coverage of METR. 时间跨度 is the settled rendering of 'time horizon' as a metric; 长期任务 for the task type is ambiguous in ordinary Chinese. Recorded in research as “长期任务 / 时间跨度”.","attestations":[{"quote_zh":"AI在完成长期任务方面的进步速度惊人，其时间跨度大约每七个月翻一番。","quote_en":"AI's progress on completing long-horizon tasks is striking: its time horizon roughly doubles every seven months.","source_title":"Nature发文「智能体摩尔定律」，Agent能力每7个月翻倍","publisher":"量子位 (QbitAI)","source_type":"media","url":"https://www.qbitai.com/2025/03/266110.html","date":"2025-03"}],"zh_variants":["长期任务","时间跨度"]},{"zh":"长程自主性","pinyin":"chángchéng zìzhǔxìng","status":"common","literal_back":"long-range autonomy","notes":"Safety-register form for 'long-horizon autonomy' as a dangerous-capability category, used by 安远 AI when comparing frontier safety frameworks.","attestations":[{"quote_zh":"长程自主性、能力隐藏（Sandbagging）、自主复制与适应、破坏安全防护等","quote_en":"Long-horizon autonomy, capability hiding (sandbagging), autonomous replication and adaptation, undermining safeguards, etc.","source_title":"国际五大前沿AI风险管理框架的横向对比","publisher":"安全内参（作者：安远 AI）","source_type":"report","url":"https://www.secrss.com/articles/87619","date":"2026-02"}]},{"zh":"长时程任务","pinyin":"chángshíchéng rènwù","status":"common","literal_back":"long time-range task","notes":"More literal variant, common in搜索/科普 writing. No verbatim attestation recovered within budget.","attestations":[]}],"confidence":"high","used_by":[{"org":"安远 AI (Concordia AI)","zh_used":"长程自主性","note":"frontier framework comparison, OpenAI research categories"}],"usage_examples":[{"zh":"模型能独立完成的长程任务时间跨度还在快速拉长。","en":"The time horizon of long-horizon tasks a model can complete on its own is still lengthening fast.","source":"constructed"}],"related":["ai-agent","scaffolding","autonomy-level","autonomous-ai-rd"],"sources":["https://finance.sina.com.cn/tech/roll/2026-07-25/doc-iniizerf4357053.shtml","https://www.qbitai.com/2025/03/266110.html","https://www.secrss.com/articles/87619"],"last_researched":"2026-08-08","attestation_count":4},{"id":"mechanistic-interpretability","en":"mechanistic interpretability","en_aliases":["mech interp","reverse-engineering neural networks"],"abbr":"mech interp","category":"interpretability","tags":["anthropic-lineage","contested","high-value"],"definition_en":"Reverse-engineering the algorithms a neural network actually implements — identifying features, the circuits that connect them, and the causal role each plays — rather than explaining individual predictions after the fact.","definition_zh":"把神经网络当作一段需要逆向工程的程序来研究：找出模型内部的特征、特征之间构成的回路，以及每一部分在计算中承担的因果作用，而不是事后为某个预测编一个解释。","preferred_zh":"机制可解释性","translation_difficulty":"medium","pitfalls":"Genuinely contested between 机制可解释性 and 机械可解释性, and the difference matters. 机制 = mechanism (as in 作用机制, 'mechanism of action', the sense Chris Olah intends). 机械 = mechanical / machine-like, and in ordinary Chinese 机械 carries a strong pejorative sense of 'rigid, rote, unthinking' (机械地照搬 = to copy mechanically). 机械可解释性 is a plausible-looking mistranslation that is nevertheless in real use, including in translated paper abstracts — the hint that it is 'a plausible mistranslation worth flagging' is confirmed, but it is not rare. Recommend 机制可解释性. A third common move is to keep the English inline: 机器之心 writes 'mechanistic interpretability（机制可解释性）'.","translations":[{"zh":"机制可解释性","pinyin":"jīzhì kě jiěshì xìng","status":"common","literal_back":"mechanism interpretability","notes":"The better and apparently more widely used rendering in Chinese ML media and survey translations. Usually introduced with the English in parentheses on first use.","attestations":[{"quote_zh":"机制可解释性（Mechanistic Interpretability, MI）逐渐发展为一个重要研究方向。","quote_en":"Mechanistic interpretability (MI) has gradually developed into an important research direction.","source_title":"大模型哪里出问题、怎么修，这篇可解释性综述一次讲清","publisher":"机器之心 (via 腾讯云开发者社区)","source_type":"media","url":"https://cloud.tencent.com/developer/article/2624862","date":"2026-01"},{"quote_zh":"机制可解释性 (MI) 是一个新兴的研究领域，旨在通过将神经网络的复杂计算分解为可理解的内部组件和因果机制来\"逆向工程\"神经网络。","quote_en":"Mechanistic interpretability (MI) is an emerging research field that aims to 'reverse-engineer' neural networks by decomposing their complex computation into understandable internal components and causal mechanisms.","source_title":"定位、引导与改进：大型语言模型中可操作的机制可解释性实用综述","publisher":"alphaXiv 中文导读 (arXiv 2601.14004)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2601.14004v4","date":"2026-04"},{"quote_zh":"机制可解释性：AI显微镜动态追踪和复原模型推理过程","quote_en":"Mechanistic interpretability: the AI microscope dynamically traces and reconstructs the model's reasoning process.","source_title":"从黑箱到显微镜：大模型可解释性的现状与未来","publisher":"腾讯研究院 (曹建峰、杨浩然)，腾讯新闻","source_type":"report","url":"https://news.qq.com/rain/a/20250617A07B1L00","date":"2025-06"}]},{"zh":"机械可解释性","pinyin":"jīxiè kě jiěshì xìng","status":"contested","literal_back":"mechanical interpretability","notes":"In genuine use — including in Chinese renderings of paper abstracts — but 机械 imports a 'rigid / rote' connotation that 机制 does not, and misreads 'mechanistic' as 'mechanical'. Recommend against, while acknowledging a reader will meet it.","attestations":[{"quote_zh":"机械可解释性作为理解大语言模型内部运作机制的一种方法，引起了研究界的广泛关注。","quote_en":"Mechanistic interpretability, as an approach to understanding the internal workings of large language models, has attracted broad attention from the research community.","source_title":"稀疏自编码器综述：解读大型语言模型的内部机制 (A Survey on Sparse Autoencoders)","publisher":"alphaXiv 中文导读 (arXiv 2503.05613)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2503.05613","date":"2025"}]},{"zh":"mechanistic interpretability","pinyin":null,"status":"loanword","literal_back":null,"notes":"Chinese ML media routinely keep the English term inline, glossing it once in parentheses. This is the single most reliable way to be understood.","attestations":[{"quote_zh":"SAE 的新兴技术正迅速崛起，成为当前最热门的 mechanistic interpretability（机制可解释性）路线之一","quote_en":"The emerging SAE technique is rising rapidly, becoming one of the hottest mechanistic interpretability directions right now.","source_title":"大模型到底是怎么「思考」的？第一篇系统性综述SAE的文章来了","publisher":"机器之心Pro (via 新浪科技)","source_type":"media","url":"https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml","date":"2025-06"}]}],"confidence":"high","used_by":[{"org":"机器之心","zh_used":"机制可解释性","note":"consistently, with English gloss"},{"org":"腾讯研究院","zh_used":"机制可解释性","note":"in its 2025 interpretability landscape report"}],"usage_examples":[{"zh":"机制可解释性希望像逆向工程一段程序那样，把模型内部真正运行的算法读出来。","en":"Mechanistic interpretability wants to read out the algorithm the model actually runs, the way you would reverse-engineer a program.","source":"constructed"}],"related":["interpretability","circuit","feature","sparse-autoencoder","circuit-tracing","activation-steering","explainable-ai","induction-head","activation-patching","logit-lens","grokking"],"sources":["https://cloud.tencent.com/developer/article/2624862","https://www.alphaxiv.org/zh/overview/2601.14004v4","https://www.alphaxiv.org/zh/overview/2503.05613","https://news.qq.com/rain/a/20250617A07B1L00","https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml"],"last_researched":"2026-08-08","attestation_count":5},{"id":"mixture-of-experts","en":"mixture of experts","en_aliases":[],"abbr":"MoE","category":"training-methods","tags":["settled","loanword-heavy","architecture"],"definition_en":"An architecture in which a router activates only a few of many feed-forward \"expert\" sub-networks per token, so total parameters can be large while per-token compute stays small.","definition_zh":"模型里有很多个前馈「专家」子网络，路由器为每个 token 只激活其中少数几个，因此总参数量可以很大而单 token 计算量很小。DeepSeek、Qwen 的大模型普遍采用这种架构。","preferred_zh":"MoE（混合专家）","translation_difficulty":"low","pitfalls":"Chinese labs writing in Chinese overwhelmingly write MoE rather than 混合专家 — Qwen's own Chinese release blog says MoE 模型 throughout. 混合专家模型 is correct and understood, but is the gloss, not the working term. Note 总参数 / 激活参数 (total vs activated parameters) as the standard Chinese pair for describing MoE size.","translations":[{"zh":"MoE","pinyin":null,"status":"loanword","literal_back":null,"notes":"The working form, including in official Chinese-language releases by Chinese labs.","attestations":[{"quote_zh":"我们开源了两个 MoE 模型的权重：Qwen3-235B-A22B，一个拥有 2350 多亿总参数和 220 多亿激活参数的大模型","quote_en":"We open-sourced the weights of two MoE models: Qwen3-235B-A22B, a large model with over 235 billion total parameters and over 22 billion activated parameters.","source_title":"Qwen3: 思深，行速","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"blog","url":"https://qwenlm.github.io/zh/blog/qwen3/","date":"2025-04"},{"quote_zh":"Qwen2.5-Max：探索大规模 MoE 模型的智能","quote_en":"Qwen2.5-Max: exploring the intelligence of large-scale MoE models.","source_title":"Qwen2.5-Max：探索大规模 MoE 模型的智能","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"blog","url":"https://qwenlm.github.io/zh/blog/qwen2.5-max/","date":"2025-01"}]},{"zh":"混合专家模型","pinyin":"hùnhé zhuānjiā móxíng","status":"established","literal_back":"mixed-expert model","notes":"The standard Chinese gloss; used in framework docs and textbook writing. 混合专家 without 模型 is equally acceptable.","attestations":[{"quote_zh":"我们支持了微调最新的混合专家模型 Mixtral 8x7B。","quote_en":"We now support fine-tuning the latest mixture-of-experts model, Mixtral 8x7B.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2023-12"}]}],"confidence":"medium","used_by":[{"org":"阿里巴巴通义千问 (Qwen)","zh_used":"MoE","note":"bare acronym in Chinese release blogs and titles"},{"org":"LLaMA-Factory","zh_used":"混合专家模型","note":"Chinese changelog"}],"usage_examples":[{"zh":"这是个 MoE 模型，总参数 2350 亿，每个 token 只激活 220 亿。","en":"This is an MoE model: 235B total parameters, only 22B activated per token.","source":"constructed"}],"related":["pretraining","open-weights"],"sources":["https://qwenlm.github.io/zh/blog/qwen3/","https://qwenlm.github.io/zh/blog/qwen2.5-max/","https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md"],"last_researched":"2026-08-08","attestation_count":3},{"id":"model-context-protocol","en":"Model Context Protocol","en_aliases":[],"abbr":"MCP","category":"agents-autonomy","tags":["protocol","anthropic","fast-adoption"],"definition_en":"An open protocol standardising how applications supply context, tools and resources to LLMs, so any client can talk to any tool server without bespoke integration.","definition_zh":"一种开放协议，统一了应用向大模型提供上下文、工具和资源的方式，使任意客户端都能对接任意工具服务端，无需为每个组合单独开发。","preferred_zh":"模型上下文协议","translation_difficulty":"low","pitfalls":"The Chinese name is settled and uncontested, but the abbreviation MCP is what people actually say and write — Chinese docs typically give 模型上下文协议（Model Context Protocol，简称 MCP）once and then use MCP throughout. Minor variant 大模型上下文协议 appears in some media headlines. One thing worth flagging for safety readers: MCP's Chinese docs render the sampling feature's human-approval design as 人机协作（Human-in-the-loop）rather than 人在回路, so the protocol's oversight vocabulary does not line up with the HITL vocabulary used elsewhere in Chinese agent-safety writing.","translations":[{"zh":"模型上下文协议","pinyin":"móxíng shàngxiàwén xiéyì","status":"established","literal_back":"model context protocol","notes":"Uniform across Chinese cloud docs, community translations and media. Almost always glossed with the English name on first use.","attestations":[{"quote_zh":"模型上下文协议（Model Context Protocol，简称 MCP）是一种开放标准，旨在标准化大型语言模型（LLM）与外部数据源和工具之间的交互方式。","quote_en":"The Model Context Protocol (MCP) is an open standard intended to standardise how large language models interact with external data sources and tools.","source_title":"一文掌握 MCP 上下文协议：从理论到实践","publisher":"阿里云开发者社区（作者：陈明勇）","source_type":"blog","url":"https://developer.aliyun.com/article/1659874","date":"2025-04"},{"quote_zh":"Model Context Protocol (MCP) 是一个开放协议， 为 LLM 应用与外部数据源和工具之间的无缝集成提供了可能。","quote_en":"The Model Context Protocol (MCP) is an open protocol that makes seamless integration between LLM applications and external data sources and tools possible.","source_title":"Model Context Protocol 规范（2025-03-26）","publisher":"MCP 中文文档 (mcp.fleeto.us)","source_type":"github","url":"https://mcp.fleeto.us/spec/","date":"2025-03"}]},{"zh":"MCP","pinyin":null,"status":"loanword","literal_back":null,"notes":"The form actually used in running text and speech after first mention.","attestations":[{"quote_zh":"可以在开源的MCP Server网站上选择需要的工具，并配置相关环境。","quote_en":"You can pick the tools you need from open-source MCP Server sites and configure the relevant environment.","source_title":"Qwen-Agent README_CN.md","publisher":"阿里巴巴通义千问 (QwenLM)","source_type":"github","url":"https://github.com/QwenLM/Qwen-Agent/blob/main/README_CN.md","date":null}]}],"confidence":"high","used_by":[{"org":"阿里云","zh_used":"模型上下文协议 / MCP","note":"developer community explainer"},{"org":"阿里巴巴通义千问","zh_used":"MCP","note":"Qwen-Agent supports MCP tools"}],"usage_examples":[{"zh":"接一次 MCP，就能复用整个生态里的工具，不用为每个服务单独写适配。","en":"Integrate MCP once and you can reuse the whole ecosystem of tools instead of writing an adapter per service.","source":"constructed"}],"related":["tool-use","ai-agent","permissions"],"sources":["https://developer.aliyun.com/article/1659874","https://mcp.fleeto.us/spec/","https://github.com/QwenLM/Qwen-Agent/blob/main/README_CN.md"],"last_researched":"2026-08-08","attestation_count":3},{"id":"model-organisms","en":"model organisms of misalignment","abbr":null,"category":"misalignment-phenomena","tags":["methodology","anthropic","gap"],"definition_en":"Deliberately constructed misaligned models, built so that a failure mode that is otherwise only argued about philosophically can be studied empirically. The framing is borrowed from biology's use of C. elegans, Drosophila and mice. Hubinger et al., 2023.","definition_zh":"刻意造出来的失准模型，目的是把原本只能靠哲学论证讨论的失败模式变成可以做实验的对象。这个说法借自生物学里用线虫、果蝇、小鼠做研究的传统。出自 Hubinger 等人 2023 年的提法。","preferred_zh":"失准模式生物","translation_difficulty":"high","pitfalls":"NO CHINESE AI-SAFETY USAGE FOUND. 模式生物 is the completely standard Chinese term for biology's model organisms and is well understood, so the metaphor is available in principle. But no Chinese-language AI-safety source using it for misaligned models was located in this pass, and Chinese coverage of the underlying papers (sleeper agents, reward tampering, alignment faking) describes the experiments without ever naming the methodology. Two further hazards: 模型生物 is a wrong-but-tempting variant (it back-translates as 'model creature' and is not the biology term), and in an AI context 模型 immediately means 'the ML model', so 模型生物 will be misparsed. If you must render it, use 失准模式生物 or 对齐失败的模式生物 and gloss the biology metaphor explicitly — Chinese readers will not infer it.","translations":[{"zh":"失准模式生物","pinyin":"shīzhǔn móshì shēngwù","status":"proposed","literal_back":"off-target model organism","notes":"Our coinage. Uses 模式生物, the correct and well-known Chinese biology term, and prefixes it with a misalignment marker. Unattested — no Chinese AI-safety source was found using any rendering of this term.","attestations":[]},{"zh":"模型生物","pinyin":"móxíng shēngwù","status":"deprecated","literal_back":"model creature","notes":"Recommend against. It is not the Chinese biology term (that is 模式生物), and in an ML context 模型 will be read as 'the model', making the phrase incoherent.","attestations":[]}],"confidence":"low","used_by":[],"usage_examples":[{"zh":"潜伏特工实验本质上是在构建一个失准模式生物，用来检验安全训练是否真的有效。","en":"The sleeper-agents experiment is essentially building a model organism of misalignment, in order to test whether safety training actually works.","source":"constructed"}],"related":["sleeper-agent","reward-tampering","alignment-faking","emergent-misalignment"],"sources":["https://www.lesswrong.com/posts/ChDH335ckdvpxXaXX/model-organisms-of-misalignment-the-case-for-a-new-pillar-of-1","https://zh.wikipedia.org/wiki/%E6%A8%A1%E5%BC%8F%E7%94%9F%E7%89%A9"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":0},{"id":"model-spec","en":"Model Spec","en_aliases":["model specification"],"abbr":null,"category":"training-methods","tags":["openai","governance-adjacent"],"definition_en":"OpenAI's published document specifying how its models should behave — objectives, hard rules, and default behaviours — used as the reference for training and for adjudicating disputed model responses.","definition_zh":"OpenAI 公开发布的、规定其模型应当如何行为的文档，分为目标、规则和默认行为三层，既作为训练（尤其是 RLHF 标注）的依据，也作为判定模型回复是否恰当的参照。","preferred_zh":"模型规范","translation_difficulty":"medium","pitfalls":"模型规范 is the settled rendering but is weaker than the English: 规范 in Chinese engineering usage means a technical specification or norm (like a coding 规范), which undersells that the document is a normative statement of intended values and behaviour, closer to a code of conduct. 行为规范 (code of conduct) is more accurate to the content and does appear in Chinese coverage. Also note the collision risk with 模型备案/技术规范 in PRC regulatory vocabulary, where 规范 means a formal standards document with legal weight — a Chinese policy reader may over-read the term's authority. No Chinese lab has published a direct equivalent document under this name at the time of research; Chinese labs express intended behaviour through 模型卡, 安全策略 and 使用规范 instead.","translations":[{"zh":"模型规范","pinyin":"móxíng guīfàn","status":"established","literal_back":"model specification/norm","notes":"The dominant rendering across Chinese tech media coverage of OpenAI's document.","attestations":[{"quote_zh":"OpenAI 最近发布了其模型规范，这是一份描述 GPT 模型行为规则和目标的文档。","quote_en":"OpenAI recently released its Model Spec, a document describing the behavioural rules and objectives of GPT models.","source_title":"OpenAI 发布 GPT 模型规范，可作为模型微调指南","publisher":"InfoQ 中文站","source_type":"media","url":"https://www.infoq.cn/article/lffslndj4iznwkvoowoj","date":"2024-06"},{"quote_zh":"我们打算将模型规范作为研究人员和 AI 训练者进行人类反馈强化学习的指南。","quote_en":"We intend the Model Spec to serve as a guideline for researchers and AI trainers doing reinforcement learning from human feedback.","source_title":"OpenAI 发布 GPT 模型规范，可作为模型微调指南","publisher":"InfoQ 中文站","source_type":"media","url":"https://www.infoq.cn/article/lffslndj4iznwkvoowoj","date":"2024-06"}]},{"zh":"模型行为规范","pinyin":"móxíng xíngwéi guīfàn","status":"common","literal_back":"model behaviour norms","notes":"More explicit and closer to the document's actual content; used in Chinese security/policy media headlines. Recommended when the normative character matters more than matching OpenAI's product name.","attestations":[]},{"zh":"Model Spec","pinyin":null,"status":"loanword","literal_back":null,"notes":"Frequently retained in English as a proper-noun product name alongside the Chinese gloss, in the pattern 模型规范（Model Spec）.","attestations":[]}],"confidence":"medium","used_by":[{"org":"InfoQ 中文站","zh_used":"模型规范","note":"news coverage of the Model Spec release"}],"usage_examples":[{"zh":"标注员判断回复好坏时，依据的是模型规范里写明的默认行为。","en":"When annotators judge whether a response is good, they go by the default behaviours written in the Model Spec.","source":"constructed"}],"related":["constitutional-ai","rlhf","system-prompt","post-training","deliberative-alignment"],"sources":["https://www.infoq.cn/article/lffslndj4iznwkvoowoj"],"last_researched":"2026-08-08","attestation_count":2},{"id":"monosemanticity","en":"monosemanticity","en_aliases":["monosemantic feature"],"abbr":null,"category":"interpretability","tags":["added-by-research","anthropic-lineage","contested"],"definition_en":"The target property of an interpretability decomposition: each recovered unit corresponds to exactly one human-legible concept. The goal SAEs pursue, and the title concept of Anthropic's 2023 Towards Monosemanticity.","definition_zh":"可解释性分解所追求的性质：分解出来的每个单元只对应一个人类能理解的概念。它是训练 SAE 的目标，也是 Anthropic 2023 年 Towards Monosemanticity 一文的核心概念。","preferred_zh":"单义性","translation_difficulty":"medium","pitfalls":"Added because it is the antonym that makes 多义性 usable, and it inherits the same unresolved split: 单义性 (matching 多义性) vs 单语义性 (matching 多语义性). Chinese renderings of Anthropic's paper title used 单语义性; Chinese renderings of SAE surveys use 单义. Pick one and stay consistent with whichever you chose for polysemanticity. Also note 单义 is sometimes written adjectivally as 单义的特征 rather than as an abstract noun.","translations":[{"zh":"单义性","pinyin":"dānyì xìng","status":"contested","literal_back":"single-meaning-ness","notes":"Our recommendation, pairing with 多义性.","attestations":[{"quote_zh":"字典学习（一种稀疏自编码器，SAE）的应用，旨在将大型语言模型的表征分解成更具可解释性、单义的特征。","quote_en":"The application of dictionary learning (a sparse autoencoder) aims to decompose an LLM's representations into more interpretable, monosemantic features.","source_title":"稀疏自编码器综述：解读大型语言模型的内部机制 (A Survey on Sparse Autoencoders)","publisher":"alphaXiv 中文导读 (arXiv 2503.05613)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2503.05613","date":"2025"},{"quote_zh":"SAE用于将这些密集表示分解为高维、稀疏且\"单语义\"的特征。","quote_en":"SAEs are used to decompose these dense representations into high-dimensional, sparse, 'monosemantic' features.","source_title":"定位、引导与改进：大型语言模型中可操作的机制可解释性实用综述","publisher":"alphaXiv 中文导读 (arXiv 2601.14004)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2601.14004v4","date":"2026-04"}]},{"zh":"单语义性","pinyin":"dān yǔyì xìng","status":"contested","literal_back":"single-semantic-ness","notes":"The variant used when rendering Anthropic's paper title Towards Monosemanticity; pairs with 多语义性. No fetchable verbatim recovered for the abstract-noun form.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"SAE 训练的目标就是让每个特征尽量单义。","en":"The goal of training an SAE is to make each feature as monosemantic as possible.","source":"constructed"}],"related":["polysemanticity","superposition","sparse-autoencoder","feature"],"sources":["https://www.alphaxiv.org/zh/overview/2503.05613","https://www.alphaxiv.org/zh/overview/2601.14004v4","https://www.36kr.com/p/2465483534538887"],"last_researched":"2026-08-08","attestation_count":2},{"id":"multi-agent-system","en":"multi-agent system","en_aliases":["MAS"],"abbr":"MAS","category":"agents-autonomy","tags":["classic","established"],"definition_en":"A system of multiple interacting agents in a shared environment. In safety, the frame where collusion, emergent coordination failures and principal-hierarchy problems arise.","definition_zh":"由多个智能体在同一环境中交互构成的系统。在安全研究中，合谋、协作失败和多层委托授权等问题都出现在这一框架下。","preferred_zh":"多智能体系统","translation_difficulty":"low","pitfalls":"Unproblematic — this is the one term in the category with a genuinely settled, textbook-stable rendering, inherited from classical distributed-AI literature long before LLMs. Its stability is in fact part of why 智能体 beat 代理 for 'agent': the multi-agent compound already existed and only works with 智能体. Note that the newer industry phrase 多智能体协同 (multi-agent coordination) is what safety writing usually uses, rather than the system-theoretic 多智能体系统.","translations":[{"zh":"多智能体系统","pinyin":"duō zhìnéngtǐ xìtǒng","status":"established","literal_back":"multi intelligent-entity system","notes":"Textbook-stable; identical wording appears in Chinese Wikipedia and in 机器之心's technology glossary.","attestations":[{"quote_zh":"多智能体系统（英语：multi-agent system，縮寫M.A.S.），是由一个在一个环境中交互的多个智能体组成的计算系统。","quote_en":"A multi-agent system is a computational system composed of multiple agents interacting in an environment.","source_title":"多智能体系统","publisher":"维基百科（中文）","source_type":"wiki","url":"https://zh.wikipedia.org/zh-cn/%E5%A4%9A%E6%99%BA%E8%83%BD%E4%BD%93%E7%B3%BB%E7%BB%9F","date":null},{"quote_zh":"一个多智能体系统，是由一个在一个环境中交互的多个智能体组成的计算系统。","quote_en":"A multi-agent system is a computational system composed of multiple agents interacting in an environment.","source_title":"多智能体系统（技术词条）","publisher":"机器之心 (Synced)","source_type":"wiki","url":"https://www.jiqizhixin.com/graph/technologies/c358669a-56ff-4bc6-b682-605914071b76","date":null}]},{"zh":"多智能体协同","pinyin":"duō zhìnéngtǐ xiétóng","status":"common","literal_back":"multi-agent coordination","notes":"The phrasing safety and industry writing actually uses when describing agents working together as a risk surface.","attestations":[{"quote_zh":"随着AI智能体（Agent）成为大模型落地的核心形态，其自主决策、工具调用、多智能体协同、持续进化等特性，催生了指令注入、越权操作、技能供应链攻击、智能体失控等新型安全隐患，成为当前AI安全治理的核心攻坚方向。","quote_en":"As AI agents become the core deployment form of large models, their autonomous decision-making, tool calling, multi-agent coordination and continuous evolution give rise to new safety hazards…","source_title":"智能体安全研究员（招聘页）","publisher":"安远 AI (Concordia AI)","source_type":"blog","url":"https://concordia-ai.com/zh-hans/career/%E6%99%BA%E8%83%BD%E4%BD%93%E5%AE%89%E5%85%A8%E7%A0%94%E7%A9%B6%E5%91%98/","date":null}]}],"confidence":"high","used_by":[{"org":"机器之心 (Synced)","zh_used":"多智能体系统","note":"technology glossary entry"}],"usage_examples":[{"zh":"在多智能体系统里，一个子智能体被劫持会把污染传播到整张图谱。","en":"In a multi-agent system, one hijacked sub-agent propagates the contamination across the whole graph.","source":"constructed"}],"related":["ai-agent","delegation","permissions","collusion"],"sources":["https://zh.wikipedia.org/zh-cn/%E5%A4%9A%E6%99%BA%E8%83%BD%E4%BD%93%E7%B3%BB%E7%BB%9F","https://www.jiqizhixin.com/graph/technologies/c358669a-56ff-4bc6-b682-605914071b76","https://concordia-ai.com/zh-hans/career/%E6%99%BA%E8%83%BD%E4%BD%93%E5%AE%89%E5%85%A8%E7%A0%94%E7%A9%B6%E5%91%98/"],"last_researched":"2026-08-08","attestation_count":3},{"id":"open-weights","en":"open weights","en_aliases":["open-weight model"],"abbr":null,"category":"training-methods","tags":["governance-adjacent","high-value","contested"],"definition_en":"Publishing a model's trained parameters for download, without necessarily publishing training data, training code, or granting an OSI-conformant licence. Distinct from open source, which requires the means to reproduce the artefact.","definition_zh":"把训练好的模型参数公开供下载，但不一定公开训练数据、训练代码，也不一定采用符合开源定义的许可证。与「开源」不同——开源要求提供足以复现该成果的全部要素。","preferred_zh":"开放权重","translation_difficulty":"high","pitfalls":"The most consequential terminology problem in this category. Chinese discourse — including the labs themselves — routinely says 开源 (open source) for what is actually a weights release. Qwen's own Chinese release blog writes 我们开源了两个 MoE 模型的权重 (\"we open-sourced the weights of two MoE models\"), collapsing the distinction in a single phrase; DeepSeek is universally described in Chinese as an 开源大模型. The consequence is that Chinese-language debate about \"开源模型\" and English-language debate about \"open-weight models\" are often not about the same object, and a Chinese reader may not register that training data and code were withheld. 开放权重 exists, is correct, and is gaining ground — largely imported through coverage of OpenAI's gpt-oss, which was explicitly marketed as open-weight rather than open-source — but it remains the minority form against the entrenched 开源. When precision matters, write 开放权重（open-weight）and explicitly contrast with 开源.","translations":[{"zh":"开放权重","pinyin":"kāifàng quánzhòng","status":"common","literal_back":"open weights","notes":"The precise term. Chinese commentators use it specifically when they want to deny that a release is fully open source. Recommended.","attestations":[{"quote_zh":"虽然开放权重并非严格意义上的开源，但它赋予了AI技术透明性","quote_en":"Although open weights is not open source in the strict sense, it grants AI technology transparency.","source_title":"大模型时代的开源：从开放代码到开放权重的演进","publisher":"Jimmy Song《智能体构建指南》","source_type":"blog","url":"https://jimmysong.io/zh/book/ai-handbook/llm/open-model/","date":"2025-11"},{"quote_zh":"开放权重 ≠ 完全开源","quote_en":"Open weights ≠ fully open source.","source_title":"大模型时代的开源：从开放代码到开放权重的演进","publisher":"Jimmy Song《智能体构建指南》","source_type":"blog","url":"https://jimmysong.io/zh/book/ai-handbook/llm/open-model/","date":"2025-11"}]},{"zh":"开源","pinyin":"kāiyuán (móxíng)","status":"deprecated","literal_back":"open source (model)","notes":"By far the dominant Chinese usage, and the one to argue against. Chinese labs describe weight releases as 开源, which is what makes the pitfall load-bearing rather than pedantic. Recorded as deprecated for precision work, not because it is rare — it is the default. Recorded in research as “开源（模型）”.","attestations":[{"quote_zh":"我们开源了两个 MoE 模型的权重：Qwen3-235B-A22B，一个拥有 2350 多亿总参数和 220 多亿激活参数的大模型","quote_en":"We open-sourced the weights of two MoE models: Qwen3-235B-A22B, a large model with over 235 billion total parameters and over 22 billion activated parameters.","source_title":"Qwen3: 思深，行速","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"blog","url":"https://qwenlm.github.io/zh/blog/qwen3/","date":"2025-04"}]}],"confidence":"high","used_by":[{"org":"阿里巴巴通义千问 (Qwen)","zh_used":"开源……权重","note":"conflates the two in its own Chinese release blog"}],"usage_examples":[{"zh":"严格来说它只是开放权重，训练数据和训练代码都没公开，不算完全开源。","en":"Strictly speaking it is only open-weight: neither the training data nor the training code was released, so it isn't fully open source.","source":"constructed"}],"related":["distillation","mixture-of-experts","pretraining"],"sources":["https://jimmysong.io/zh/book/ai-handbook/llm/open-model/","https://qwenlm.github.io/zh/blog/qwen3/"],"last_researched":"2026-08-08","attestation_count":3},{"id":"oversight-failure","en":"oversight failure","en_aliases":["failure of human oversight"],"abbr":null,"category":"agents-autonomy","tags":["gap","descriptive"],"definition_en":"The situation where mechanisms intended to keep humans able to review, correct or stop an AI system stop working — because the system is too fast, too opaque, too numerous, or because reviewers rubber-stamp.","definition_zh":"本应让人类能够审查、纠正或叫停 AI 系统的机制失去效力：或因系统太快、太不透明、数量太多，或因审查者流于形式。","preferred_zh":"监督失效","translation_difficulty":"high","pitfalls":"No fixed Chinese term. Chinese discourse reaches for adjacent words instead, and each shifts the meaning: 失控 ('loss of control') is the overwhelmingly dominant framing but describes the system going out of control, not the oversight mechanism breaking down; 监管失灵 means regulatory failure at the institutional level, not operator-level oversight; 人工干预失效 is closest but rare. The English concept — oversight exists on paper but does not bite — is not lexicalised in Chinese and normally has to be written out as a clause (人类实际上已无法有效监督/纠正). Recording this as a gap rather than proposing a calque with confidence.","translations":[{"zh":"监督失效","pinyin":"jiāndū shīxiào","status":"proposed","literal_back":"supervision loses effect","notes":"Proposed here as the most transparent compositional rendering: 监督 matches the 人类监督 used in Chinese translations of the EU AI Act, and 失效 is the standard word for a safeguard ceasing to function. Not attested as a fixed term in the sources reviewed; offered as a coinage, not a report of usage.","attestations":[]},{"zh":"失控","pinyin":"shīkòng","status":"descriptive","literal_back":"loss of control","notes":"What Chinese sources actually say. Broader and more dramatic than 'oversight failure' — it names the outcome (the system is out of control) rather than the mechanism (nobody was effectively checking). Do not treat as an equivalent; see the loss-of-control entry.","attestations":[{"quote_zh":"催生了指令注入、越权操作、技能供应链攻击、智能体失控等新型安全隐患","quote_en":"…giving rise to new safety hazards such as prompt injection, privilege-exceeding operations, skill supply-chain attacks and agent loss of control.","source_title":"智能体安全研究员（招聘页）","publisher":"安远 AI (Concordia AI)","source_type":"blog","url":"https://concordia-ai.com/zh-hans/career/%E6%99%BA%E8%83%BD%E4%BD%93%E5%AE%89%E5%85%A8%E7%A0%94%E7%A9%B6%E5%91%98/","date":null},{"quote_zh":"目前并无有效的智能体退出机制，一些智能体被创造出后可能无法被关闭","quote_en":"There is currently no effective exit mechanism for agents; once created, some agents may be impossible to shut down.","source_title":"警惕人工智能时代的“智能体风险”","publisher":"新华社 / 新华网","source_type":"media","url":"http://www.news.cn/science/20240717/7f75ef8878304dacb682ebc8e8209fc3/c.html","date":"2024-07"}]}],"confidence":"low","used_by":[],"usage_examples":[{"zh":"流程上写着要人工审批，实际上审批只是点一下，人类监督已经形同虚设。","en":"The process says manual approval is required, but approval is just a click — human oversight has become a formality.","source":"constructed"}],"related":["human-in-the-loop","autonomy-level","permissions","agency","human-oversight"],"sources":["https://concordia-ai.com/zh-hans/career/%E6%99%BA%E8%83%BD%E4%BD%93%E5%AE%89%E5%85%A8%E7%A0%94%E7%A9%B6%E5%91%98/","http://www.news.cn/science/20240717/7f75ef8878304dacb682ebc8e8209fc3/c.html","https://www.secrss.com/articles/68714"],"last_researched":"2026-08-08","attestation_count":2},{"id":"permissions","en":"permissions","en_aliases":["approval","authorization"],"abbr":null,"category":"agents-autonomy","tags":["infosec","established"],"definition_en":"The set of actions and resources an agent is allowed to touch. Least privilege — granting only what the current task requires — is the central control for bounding agent behaviour.","definition_zh":"智能体被允许执行的操作和可访问的资源范围。最小权限原则（只授予当前任务所必需的权限）是约束智能体行为的核心手段。","preferred_zh":"权限","translation_difficulty":"low","pitfalls":"权限 (permissions/privileges) and 授权 (authorization, the act of granting) are cleanly distinguished in Chinese and should not be merged — 权限 is the noun for what you have, 授权 the verb/noun for granting it. The idiomatic Chinese for a violation is 越权操作 ('exceeding-authority operation'), which is more vivid than English 'unauthorized action' and is what PRC security writing uses about agents. 最小权限（原则）is the well-established rendering of least privilege, inherited from infosec, and transfers to agents without friction. Note that the newer English coinage 'least agency' has no Chinese equivalent; Chinese white papers that discuss it render it as 最小代理权, which reintroduces 代理.","translations":[{"zh":"权限","pinyin":"quánxiàn","status":"established","literal_back":"authority-limit","notes":"Fully standard; 最小权限 = least privilege, 越权 = exceeding one's permissions.","attestations":[{"quote_zh":"网络安全的一个基本准则是最小权限访问原则，即赋予特定主体最少的权限。","quote_en":"A basic principle of cybersecurity is the principle of least-privilege access — granting a given principal the fewest permissions possible.","source_title":"人工智能控制：如何利用违规人工智能体（中文版）","publisher":"Center for Security and Emerging Technology (CSET), Georgetown University","source_type":"report","url":"https://cset.georgetown.edu/publication/ai-control-chinese/","date":"2025-11"},{"quote_zh":"子 Agent 权限 ⊆ 父 Agent 权限 ⊆ 原始用户权限","quote_en":"Sub-agent permissions ⊆ parent-agent permissions ⊆ original user permissions.","source_title":"企业Agent运行时安全的七域架构","publisher":"安全内参（作者：模安局）","source_type":"blog","url":"https://www.secrss.com/articles/92784","date":"2026-08"}]},{"zh":"授权","pinyin":"shòuquán","status":"established","literal_back":"to grant authority","notes":"The granting act, distinct from 权限. Use for 'authorization'.","attestations":[{"quote_zh":"授予智能体对工具集的访问权限，然后信任模型自行管理使用哪些工具，这只是另一种形式的环境权限。","quote_en":"Granting an agent access to a toolset and then trusting the model to manage which tools it uses is just another form of ambient authority.","source_title":"主体层级问题：多智能体系统中的授权","publisher":"TianPan.co","source_type":"blog","url":"https://tianpan.co/zh/blog/2026-03-08-principal-hierarchy-multi-agent-authorization","date":"2026-04"}]},{"zh":"越权操作","pinyin":"yuèquán cāozuò","status":"established","literal_back":"exceeding-authority operation","notes":"The idiomatic Chinese name for the failure mode. Used by 安远 AI in its agent-risk list.","attestations":[{"quote_zh":"催生了指令注入、越权操作、技能供应链攻击、智能体失控等新型安全隐患","quote_en":"…giving rise to new safety hazards such as prompt injection, privilege-exceeding operations, skill supply-chain attacks and agent loss of control.","source_title":"智能体安全研究员（招聘页）","publisher":"安远 AI (Concordia AI)","source_type":"blog","url":"https://concordia-ai.com/zh-hans/career/%E6%99%BA%E8%83%BD%E4%BD%93%E5%AE%89%E5%85%A8%E7%A0%94%E7%A9%B6%E5%91%98/","date":null}]}],"confidence":"high","used_by":[{"org":"安远 AI (Concordia AI)","zh_used":"越权操作","note":"agent risk taxonomy"},{"org":"CSET","zh_used":"最小权限","note":"Chinese translation of AI control report"}],"usage_examples":[{"zh":"子智能体的权限必须严格小于父智能体，每一次委托都应该收窄范围。","en":"A sub-agent's permissions must be strictly narrower than its parent's; every delegation should shrink the scope.","source":"constructed"}],"related":["delegation","sandboxing","human-in-the-loop","multi-agent-system","tool-use","computer-use","model-context-protocol","oversight-failure"],"sources":["https://cset.georgetown.edu/publication/ai-control-chinese/","https://www.secrss.com/articles/92784","https://tianpan.co/zh/blog/2026-03-08-principal-hierarchy-multi-agent-authorization","https://concordia-ai.com/zh-hans/career/%E6%99%BA%E8%83%BD%E4%BD%93%E5%AE%89%E5%85%A8%E7%A0%94%E7%A9%B6%E5%91%98/"],"last_researched":"2026-08-08","attestation_count":4},{"id":"polysemanticity","en":"polysemanticity","en_aliases":["polysemantic neuron"],"abbr":null,"category":"interpretability","tags":["anthropic-lineage","contested"],"definition_en":"The property of a single neuron responding to several unrelated concepts, so that reading off 'what a neuron means' is impossible. The empirical symptom that superposition explains.","definition_zh":"同一个神经元会对多个毫不相关的概念做出反应，因此无法说清\"这个神经元代表什么\"。它是叠加现象在观测层面的表现。","preferred_zh":"多义性","translation_difficulty":"medium","pitfalls":"Three renderings are in live use with no winner: 多义性 (borrowed from linguistics, where 多义词 = polysemous word — the closest analogue to the English coinage), 多语义(性) (a more literal poly-+semantic calque), and 多重语义 (descriptive, 'multiple semantics'). Because 多义性 is a pre-existing linguistics term, a Chinese reader may first think of lexical ambiguity rather than neuron overloading; conversely 多语义性 reads as a fresh technical coinage but is less idiomatic. The antonym is 单义性 / 单语义性 (monosemanticity), inheriting the same split.","translations":[{"zh":"多义性","pinyin":"duōyì xìng","status":"contested","literal_back":"multi-meaning-ness","notes":"Our recommendation: shortest, matches the linguistics term 多义词, and the antonym 单义性 works cleanly.","attestations":[{"quote_zh":"这使得模型能够表示比神经元数量更多的概念，从而有效地逆转了导致单个神经元多义性的叠加现象。","quote_en":"This lets the model represent more concepts than it has neurons, effectively reversing the superposition that makes individual neurons polysemantic.","source_title":"稀疏自编码器综述：解读大型语言模型的内部机制 (A Survey on Sparse Autoencoders)","publisher":"alphaXiv 中文导读 (arXiv 2503.05613)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2503.05613","date":"2025"},{"quote_zh":"LLM 内部的许多神经元可能是'多义的'，意思是它们同时处理好几个不相关的信息","quote_en":"Many neurons inside an LLM may be 'polysemantic', meaning they handle several unrelated pieces of information at once.","source_title":"大模型到底是怎么「思考」的？第一篇系统性综述SAE的文章来了","publisher":"机器之心Pro (via 新浪科技)","source_type":"media","url":"https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml","date":"2025-06"}]},{"zh":"多语义性","pinyin":"duō yǔyì xìng","status":"contested","literal_back":"multi-semantic-ness","notes":"The 2023-era rendering, still common. Its antonym 单语义性 was used to render Anthropic's 'Towards Monosemanticity'.","attestations":[{"quote_zh":"这是由于大多数神经元都是「多语义」的，单个神经元与网络行为没有对应一致的关系","quote_en":"This is because most neurons are 'polysemantic' — a single neuron has no consistent correspondence to network behaviour.","source_title":"打破大模型黑盒，彻底分解神经元，OpenAI对头Anthropic击破AI不可解释性障碍","publisher":"新智元 (via 36氪)","source_type":"media","url":"https://www.36kr.com/p/2465483534538887","date":"2023-10"}]},{"zh":"多重语义","pinyin":"duōchóng yǔyì","status":"common","literal_back":"multiple semantics","notes":"Descriptive variant used by 腾讯研究院; reads more naturally in prose but is not a noun-form term.","attestations":[{"quote_zh":"大模型内部的神经元具有多重语义（polysemantic）的特性，即一个神经元往往混合表示了多个彼此无关的概念","quote_en":"Neurons inside large models have a polysemantic character: one neuron often mixes representations of several unrelated concepts.","source_title":"从黑箱到显微镜：大模型可解释性的现状与未来","publisher":"腾讯研究院 (曹建峰、杨浩然)，腾讯新闻","source_type":"report","url":"https://news.qq.com/rain/a/20250617A07B1L00","date":"2025-06"}]}],"confidence":"high","used_by":[],"usage_examples":[{"zh":"神经元的多义性意味着你不能靠看单个神经元来理解模型。","en":"Neuron polysemanticity means you cannot understand the model by looking at individual neurons.","source":"constructed"}],"related":["superposition","feature","sparse-autoencoder","monosemanticity"],"sources":["https://www.alphaxiv.org/zh/overview/2503.05613","https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml","https://www.36kr.com/p/2465483534538887","https://news.qq.com/rain/a/20250617A07B1L00"],"last_researched":"2026-08-08","attestation_count":4},{"id":"post-training","en":"post-training","en_aliases":["alignment training"],"abbr":null,"category":"training-methods","tags":["settled","core-pipeline"],"definition_en":"Everything done to a base model after pretraining — SFT, reward modelling, RL, safety tuning — to make it usable and aligned. The umbrella term that replaced \"alignment\" as the pipeline stage name.","definition_zh":"预训练之后对基座模型做的全部工作：SFT、奖励建模、强化学习、安全微调等，目的是让模型可用且与人类偏好一致。它已经取代「对齐」成为这一阶段的标准称呼。","preferred_zh":"后训练","translation_difficulty":"low","pitfalls":"Settled. The seed hypothesis that 对齐训练 serves as a near-synonym is only partly right: Chinese sources treat 人类对齐 / 对齐 as the *goal* of post-training, and 后训练 as the *stage*. Chinese labs' own release blogs use 后训练 for the stage and 对齐 for what it achieves, in the same sentence — see the Qwen docs attestation. 微调 (fine-tuning) is narrower and should not be substituted.","translations":[{"zh":"后训练","pinyin":"hòu xùnliàn","status":"established","literal_back":"post-training","notes":"Universal in Chinese lab blogs, docs and technical media. 后训练增强技术 / 后训练策略 are common collocations.","attestations":[{"quote_zh":"使用超过 20 万亿 token 的预训练数据及精心设计的后训练方案进行训练","quote_en":"Trained using over 20 trillion tokens of pretraining data together with a carefully designed post-training scheme.","source_title":"Qwen2.5-Max：探索大规模 MoE 模型的智能","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"blog","url":"https://qwenlm.github.io/zh/blog/qwen2.5-max/","date":"2025-01"},{"quote_zh":"并在高质量语料上后训练以与人类偏好对齐","quote_en":"And post-trained on high-quality corpora to align with human preferences.","source_title":"核心概念 — Qwen 中文文档","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"github","url":"https://qwen.readthedocs.io/zh-cn/latest/getting_started/concepts.html","date":"2025"},{"quote_zh":"在大语言模型（LLMs）时代，RL最初作为人类对齐的后训练策略而崭露头角。","quote_en":"In the era of large language models, RL first came to prominence as a post-training strategy for human alignment.","source_title":"大型推理模型的强化学习综述（1-4章）","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2637181","date":"2026-03"}]},{"zh":"人类对齐","pinyin":"rénlèi duìqí","status":"common","literal_back":"human alignment","notes":"Names the goal rather than the stage. 《大语言模型》uses it as the title of the chapter covering RLHF. Not interchangeable with 后训练 when precision matters.","attestations":[{"quote_zh":"第五课 人类对齐（对应本书第八章）","quote_en":"Lecture 5: Human alignment (corresponding to Chapter 8 of this book).","source_title":"《大语言模型》课程资源","publisher":"中国人民大学 RUC AI Box（赵鑫等，高等教育出版社）","source_type":"github","url":"https://github.com/LLMBook-zh/LLMBook-zh.github.io","date":"2024"}]}],"confidence":"high","used_by":[{"org":"阿里巴巴通义千问 (Qwen)","zh_used":"后训练","note":"official Chinese blog and docs"},{"org":"中国人民大学 RUC AI Box","zh_used":"人类对齐","note":"chapter title for the RLHF material"}],"usage_examples":[{"zh":"预训练决定上限，后训练决定体验。","en":"Pretraining sets the ceiling; post-training determines the experience.","source":"constructed"}],"related":["pretraining","supervised-fine-tuning","rlhf","rlvr","reinforcement-learning","constitutional-ai","dpo","chain-of-thought","synthetic-data","model-spec"],"sources":["https://qwenlm.github.io/zh/blog/qwen2.5-max/","https://qwen.readthedocs.io/zh-cn/latest/getting_started/concepts.html","https://cloud.tencent.com/developer/article/2637181","https://github.com/LLMBook-zh/LLMBook-zh.github.io"],"last_researched":"2026-08-08","attestation_count":4},{"id":"pretraining","en":"pretraining","en_aliases":["pre-training"],"abbr":null,"category":"training-methods","tags":["settled","core-pipeline"],"definition_en":"The first and most compute-intensive training stage, in which a model learns next-token prediction over a very large unlabelled corpus. Everything else — SFT, RL, alignment — is done on top of the resulting base model.","definition_zh":"大模型训练的第一个阶段，在超大规模无标注语料上做下一个词预测，得到基座模型。后续的微调、对齐都建立在预训练模型之上，也是整个流程中算力消耗最大的一步。","preferred_zh":"预训练","translation_difficulty":"low","pitfalls":null,"translations":[{"zh":"预训练","pinyin":"yù xùnliàn","status":"established","literal_back":"pre-training","notes":"Completely settled. Universal across Chinese labs, textbooks, framework docs and media; no competing rendering exists. 增量预训练 = continued/incremental pretraining, 预训练模型/基座模型 = base model.","attestations":[{"quote_zh":"语言和多模态模型均在大规模、多语言、多模态数据上进行预训练","quote_en":"Both the language and multimodal models are pretrained on large-scale, multilingual, multimodal data.","source_title":"核心概念 — Qwen 中文文档","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"github","url":"https://qwen.readthedocs.io/zh-cn/latest/getting_started/concepts.html","date":"2025"},{"quote_zh":"Qwen2.5是在 18 万亿个 token 上进行预训练的，而 Qwen3 使用的数据量几乎是其两倍，达到了约 36 万亿个 token","quote_en":"Qwen2.5 was pretrained on 18 trillion tokens, while Qwen3 uses nearly twice as much data, about 36 trillion tokens.","source_title":"Qwen3: 思深，行速","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"blog","url":"https://qwenlm.github.io/zh/blog/qwen3/","date":"2025-04"},{"quote_zh":"集成方法：（增量）预训练、（多模态）指令监督微调、奖励模型训练、PPO 训练、DPO 训练、KTO 训练、ORPO 训练等等。","quote_en":"Integrated methods: (incremental) pretraining, (multimodal) instruction supervised fine-tuning, reward model training, PPO training, DPO training, KTO training, ORPO training, etc.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2025"}]},{"zh":"预训练模型","pinyin":"yù xùnliàn móxíng","status":"established","literal_back":"pretrained model","notes":"The output of pretraining. Note that Chinese practitioners more often say 基座模型 (base model) when contrasting with an instruct-tuned model.","attestations":[{"quote_zh":"注意 PaliGemma 是预训练模型，你需要使用 paligemma 模板进行微调使其获得对话能力。","quote_en":"Note that PaliGemma is a pretrained model; you need to fine-tune it with the paligemma template to give it conversational ability.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2024-05"}]}],"confidence":"high","used_by":[{"org":"阿里巴巴通义千问 (Qwen)","zh_used":"预训练","note":"official Chinese blog and docs"},{"org":"中国人民大学 RUC AI Box《大语言模型》","zh_used":"预训练","note":"book chapter title 第三课 预训练"}],"usage_examples":[{"zh":"这个模型在超过 20 万亿 token 的语料上完成了预训练。","en":"This model was pretrained on a corpus of over 20 trillion tokens.","source":"constructed"}],"related":["post-training","supervised-fine-tuning","synthetic-data","mixture-of-experts","data-contamination","open-weights"],"sources":["https://qwen.readthedocs.io/zh-cn/latest/getting_started/concepts.html","https://qwenlm.github.io/zh/blog/qwen3/","https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","https://github.com/LLMBook-zh/LLMBook-zh.github.io"],"last_researched":"2026-08-08","attestation_count":4},{"id":"probing","en":"probing","en_aliases":["linear probe","probing classifier"],"abbr":null,"category":"interpretability","tags":["pre-llm","established"],"definition_en":"Training a small classifier on a model's frozen internal activations to test whether a given piece of information is linearly decodable from them.","definition_zh":"在冻结的模型内部激活上训练一个小分类器，用来检验某种信息是否能从这些激活中线性地读出来。","preferred_zh":"探针","translation_difficulty":"low","pitfalls":"Two forms coexist without conflict: 探针 (the noun, 'probe' — used for the object, especially 线性探针 for a linear probe) and 探测 (the verb/gerund, 'probing' — used for the method). Both are pre-existing terms borrowed from instrumentation and are unproblematic. The only caution is that 探针 in Chinese biology/electronics means a physical probe, so a lay reader may picture hardware, but this is the same metaphor English uses.","translations":[{"zh":"探针","pinyin":"tànzhēn","status":"established","literal_back":"probe (instrument)","notes":"Noun form. 线性探针 = linear probe is the standard collocation.","attestations":[{"quote_zh":"梳理了包括因果归因（Causal Attribution）、探针（Probing）、梯度检测（Gradient Detection）等主流定位技术。","quote_en":"It surveys mainstream localisation techniques including causal attribution, probing and gradient detection.","source_title":"大模型哪里出问题、怎么修，这篇可解释性综述一次讲清","publisher":"机器之心 (via 腾讯云开发者社区)","source_type":"media","url":"https://cloud.tencent.com/developer/article/2624862","date":"2026-01"}]},{"zh":"探测","pinyin":"tàncè","status":"established","literal_back":"to probe / detection","notes":"Verb/method form, used in survey prose.","attestations":[{"quote_zh":"探测（Probing）涉及训练一个小型分类器，以查看是否可以从内部向量中解码出特定概念。","quote_en":"Probing involves training a small classifier to see whether a specific concept can be decoded from the internal vectors.","source_title":"定位、引导与改进：大型语言模型中可操作的机制可解释性实用综述","publisher":"alphaXiv 中文导读 (arXiv 2601.14004)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2601.14004v4","date":"2026-04"}]},{"zh":"线性探针","pinyin":"xiànxìng tànzhēn","status":"established","literal_back":"linear probe","notes":"The fixed rendering of 'linear probe'. Long predates LLM interpretability (used in representation-learning evaluation).","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"他们在每一层训练线性探针，看模型从哪一层开始知道答案。","en":"They trained a linear probe at every layer to see from which layer the model already knows the answer.","source":"constructed"}],"related":["activation-patching","interpretability","feature","logit-lens"],"sources":["https://cloud.tencent.com/developer/article/2624862","https://www.alphaxiv.org/zh/overview/2601.14004v4"],"last_researched":"2026-08-08","attestation_count":2},{"id":"process-supervision","en":"process supervision","en_aliases":["process reward model","PRM"],"abbr":null,"category":"alignment-techniques","tags":["reward-modelling","reasoning"],"definition_en":"Rewarding each step of a model's reasoning chain rather than only the final answer. Contrasted with outcome supervision; produces process reward models (PRMs) and is argued to be more alignment-friendly because it rewards a human-endorsed chain of reasoning, not just a correct output.","definition_zh":"对模型推理链条的每一步分别给予奖励，而不是只看最终答案对不对。与结果监督相对，训练出的是过程奖励模型（PRM）；由于它奖励的是人类认可的推理过程本身，通常被认为对对齐更友好。","preferred_zh":"过程监督","translation_difficulty":"low","pitfalls":"The 过程监督 / 结果监督 pair is clean and stable; the main risk is the adjacent abbreviations PRM / ORM, which Chinese writers almost always leave in Latin letters (过程奖励模型（PRM）). Note also that 监督 here means supervision in the ML sense (as in 监督学习), not oversight in the governance sense — the same character string that renders 'oversight' in scalable-oversight.","translations":[{"zh":"过程监督","pinyin":"guòchéng jiāndū","status":"established","literal_back":"process supervision","notes":"Fixed by Chinese coverage of OpenAI's 'Let's Verify Step by Step' (2023) and reinforced by the o1/R1-era reasoning-model literature.","attestations":[{"quote_zh":"过程监督相比结果监督有一个明显的优势，那就是它提供了比结果监督更精确的反馈","quote_en":"Process supervision has one obvious advantage over outcome supervision: it provides more precise feedback.","source_title":"OpenAI最新研究Let's verify step-by-step，过程胜于结果！","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2315340","date":"2023-08"},{"quote_zh":"过程监督不仅在性能上有所改进，还对于模型的对齐性有重要意义","quote_en":"Process supervision not only improves performance, it also matters for model alignment.","source_title":"OpenAI最新研究Let's verify step-by-step，过程胜于结果！","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2315340","date":"2023-08"}]},{"zh":"结果监督","pinyin":"jiéguǒ jiāndū","status":"established","literal_back":"outcome supervision","notes":"The contrast term (outcome supervision). Always introduced as a pair with 过程监督.","attestations":[{"quote_zh":"与仅仅奖励最终正确结果的结果监督 (outcome supervision) 不同，他们通过在每个推理步骤上给予奖励","quote_en":"Unlike outcome supervision, which only rewards the final correct result, they give a reward at each reasoning step.","source_title":"OpenAI最新研究Let's verify step-by-step，过程胜于结果！","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2315340","date":"2023-08"}]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"通过过程监督可以训练出比结果监督更可靠的奖励模型。","en":"Process supervision can train a more reliable reward model than outcome supervision.","source":"https://cloud.tencent.com/developer/article/2315340"}],"related":["reward-model","chain-of-thought","cot-monitoring","scalable-oversight","deliberative-alignment"],"sources":["https://cloud.tencent.com/developer/article/2315340"],"last_researched":"2026-08-08","attestation_count":3},{"id":"ppo","en":"proximal policy optimization","en_aliases":[],"abbr":"PPO","category":"training-methods","tags":["settled","loanword-heavy","algorithm"],"definition_en":"A policy-gradient RL algorithm that constrains each update to stay close to the previous policy via a clipped objective. The default RL algorithm in classic RLHF pipelines.","definition_zh":"一种策略梯度强化学习算法，通过裁剪目标函数限制每次更新与旧策略的偏离程度，从而保持训练稳定。经典 RLHF 流程里默认使用的强化学习算法。","preferred_zh":"PPO（近端策略优化）","translation_difficulty":"low","pitfalls":"The Chinese name is stable and correct but almost never used on its own — algorithm names in Chinese ML writing are kept as Latin acronyms. 近端 renders \"proximal\" accurately (close/adjacent), so there is no meaning loss; the term simply doesn't circulate.","translations":[{"zh":"PPO","pinyin":null,"status":"loanword","literal_back":null,"notes":"The working form. Chinese framework docs list PPO 训练 alongside DPO 训练, KTO 训练 etc. with no Chinese expansions at all.","attestations":[{"quote_zh":"集成方法：（增量）预训练、（多模态）指令监督微调、奖励模型训练、PPO 训练、DPO 训练、KTO 训练、ORPO 训练等等。","quote_en":"Integrated methods: (incremental) pretraining, (multimodal) instruction supervised fine-tuning, reward model training, PPO training, DPO training, KTO training, ORPO training, etc.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2025"},{"quote_zh":"PPO 就像是教你的 LLM 一步步走路，确保它在每次更新时不会摔倒。","quote_en":"PPO is like teaching your LLM to walk step by step, making sure it doesn't fall over at each update.","source_title":"推理大模型的后训练增强技术-强化学习篇","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2503293","date":"2025-03"}]},{"zh":"近端策略优化","pinyin":"jìnduān cèlüè yōuhuà","status":"established","literal_back":"near-end policy optimisation","notes":"The settled Chinese expansion; appears on first mention in explainer articles, then the acronym takes over.","attestations":[{"quote_zh":"近端策略优化 (PPO) 等传统 RL 方法在应用于 LLM 中的推理任务时面临着重大挑战","quote_en":"Traditional RL methods such as proximal policy optimization (PPO) face significant challenges when applied to reasoning tasks in LLMs.","source_title":"DeepSeek 背后的数学原理：深入探究群体相对策略优化 (GRPO)","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2495699","date":"2025-02"}]}],"confidence":"medium","used_by":[{"org":"LLaMA-Factory","zh_used":"PPO","note":"bare acronym in Chinese feature list"},{"org":"OpenRLHF","zh_used":"PPO","note":"bare acronym in Chinese README"}],"usage_examples":[{"zh":"早期的 RLHF 流程基本都用 PPO，现在越来越多团队改用 GRPO。","en":"Early RLHF pipelines nearly all used PPO; more and more teams now switch to GRPO.","source":"constructed"}],"related":["rlhf","grpo","dpo","reward-model","reinforcement-learning"],"sources":["https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","https://cloud.tencent.com/developer/article/2503293","https://cloud.tencent.com/developer/article/2495699"],"last_researched":"2026-08-08","attestation_count":3},{"id":"reasoning-model","en":"reasoning model","en_aliases":["large reasoning model","LRM","thinking model"],"abbr":null,"category":"training-methods","tags":["ambiguity","high-value","recent"],"definition_en":"A model trained (usually with RL on verifiable tasks) to produce extended internal reasoning before answering — o1, DeepSeek-R1, Qwen3 thinking mode. Distinguished from a chat model by spending far more output tokens on deliberation.","definition_zh":"经过训练（通常是在可验证任务上做强化学习）后，会在回答前先进行长篇内部推理的模型，例如 o1、DeepSeek-R1、Qwen3 的思考模式。与普通对话模型的区别在于把大量输出 token 花在思考上。","preferred_zh":"推理模型","translation_difficulty":"high","pitfalls":"The single worst ambiguity in this category. Chinese 推理 covers BOTH English senses: (a) reasoning — logical inference, deliberation; and (b) inference — the forward pass, serving, deployment. They are unrelated concepts in English engineering vocabulary but one word in Chinese. So 推理模型 can mean 'reasoning model' (o1-like), 推理引擎 means 'inference engine' (vLLM), 推理速度 means 'inference speed', and 推理能力 means 'reasoning ability'. OpenRLHF's Chinese README contains both senses within a few lines of each other. LLaMA-Factory's Chinese README uses 推理 for inference throughout, then writes 推理 / 非推理两个版本 meaning reasoning / non-reasoning model variants. There is no disambiguating convention; readers rely entirely on context. When precision matters, write 推理（reasoning）模型 or use 思考模型 / 慢思考模型 for the reasoning sense and 部署 / 服务 / 前向推理 to force the inference sense. Chinese labs partly sidestep this by branding the behaviour 思考模式 (thinking mode) rather than calling the model a 推理模型.","translations":[{"zh":"推理模型","pinyin":"tuīlǐ móxíng","status":"established","literal_back":"reasoning/inference model","notes":"The dominant rendering despite the ambiguity. Also 大型推理模型 / 大推理模型 (LRM) in survey translations, and 推理大模型 in Chinese media.","attestations":[{"quote_zh":"使用 REINFORCE++-baseline 通过长期 RL 训练训练最先进的 1.5B 推理模型。","quote_en":"Uses REINFORCE++-baseline to train a state-of-the-art 1.5B reasoning model via prolonged RL training.","source_title":"OpenRLHF README_zh.md","publisher":"OpenRLHF","source_type":"github","url":"https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","date":"2026-02"},{"quote_zh":"当前大语言模型（LLM）最有趣的研究趋势之一，是推理模型的兴起 —— 这类模型在给出答案前会花费时间进行思考。","quote_en":"One of the most interesting research trends in current LLMs is the rise of reasoning models — models that spend time thinking before giving an answer.","source_title":"系统梳理 Test-Time Compute 的主要实现路径","publisher":"Baihai_IDP（中文编译，原作 Davis Treybig）/ SegmentFault 思否","source_type":"blog","url":"https://segmentfault.com/a/1190000047239107","date":"2025-09"}]},{"zh":"推理","pinyin":"tuīlǐ","status":"established","literal_back":"inference","notes":"The collision, documented. The very same Chinese word, in the very same documents, denotes the forward pass / serving. This attestation is included deliberately as evidence of the ambiguity, not as a translation of 'reasoning model'. Recorded in research as “推理（= inference）”.","attestations":[{"quote_zh":"vLLM - 高性能推理引擎","quote_en":"vLLM — high-performance inference engine.","source_title":"OpenRLHF README_zh.md","publisher":"OpenRLHF","source_type":"github","url":"https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","date":"2026"},{"quote_zh":"我们集成了 vLLM 以实现极速并发推理。请使用 infer_backend: vllm 来获得 270% 的推理速度。","quote_en":"We integrated vLLM for extremely fast concurrent inference. Use infer_backend: vllm to get 270% inference speed.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2024-03"},{"quote_zh":"如果模型有推理 / 非推理两个版本，请使用 _nothink 后缀来区分不同的模板。","quote_en":"If a model has reasoning / non-reasoning versions, use the _nothink suffix to distinguish the templates.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2025"}]},{"zh":"思考模式","pinyin":"sīkǎo móshì","status":"common","literal_back":"thinking mode","notes":"Qwen's branding for the reasoning behaviour, and a genuinely useful escape from the 推理 ambiguity — 思考 unambiguously means deliberation. Increasingly common in Chinese product copy (思考模式/非思考模式, 深度思考).","attestations":[{"quote_zh":"在这种模式下，模型会逐步推理，经过深思熟虑后给出最终答案","quote_en":"In this mode the model reasons step by step and gives its final answer after careful deliberation.","source_title":"Qwen3: 思深，行速","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"blog","url":"https://qwenlm.github.io/zh/blog/qwen3/","date":"2025-04"}]},{"zh":"大型推理模型","pinyin":"dàxíng tuīlǐ móxíng","status":"common","literal_back":"large reasoning model","notes":"Renders LRM; used in translated surveys, often abbreviated back to LRMs in the Chinese text.","attestations":[{"quote_zh":"一种新趋势正在兴起：面向大推理模型（LRMs）的强化学习，其目标不仅是对齐行为，更是激励推理本身。","quote_en":"A new trend is emerging: reinforcement learning for large reasoning models (LRMs), whose goal is not merely to align behaviour but to incentivise reasoning itself.","source_title":"大型推理模型的强化学习综述（1-4章）","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2637181","date":"2026-03"}]}],"confidence":"high","used_by":[{"org":"阿里巴巴通义千问 (Qwen)","zh_used":"思考模式","note":"avoids 推理模型 for the model-level branding"},{"org":"OpenRLHF","zh_used":"推理模型","note":"Chinese README, alongside 推理引擎 for inference"}],"usage_examples":[{"zh":"推理模型在推理阶段会消耗多得多的 token —— 这句话里两个「推理」意思完全不同。","en":"A reasoning model consumes far more tokens at inference time — the two instances of 推理 in this Chinese sentence mean entirely different things.","source":"constructed"}],"related":["chain-of-thought","test-time-compute","rlvr","grpo","distillation"],"sources":["https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","https://segmentfault.com/a/1190000047239107","https://qwenlm.github.io/zh/blog/qwen3/","https://cloud.tencent.com/developer/article/2637181"],"last_researched":"2026-08-08","attestation_count":7},{"id":"recursive-reward-modeling","en":"recursive reward modeling","en_aliases":["RRM"],"abbr":"RRM","category":"alignment-techniques","tags":["scalable-oversight"],"definition_en":"Leike et al.'s scheme in which a reward model is trained with the help of AI assistants that were themselves trained by reward modelling, recursively bootstrapping supervision up to tasks humans cannot evaluate unaided.","definition_zh":"Leike 等人提出的方案：用已经训练好的 AI 助手来帮助人类训练下一级奖励模型，如此递归地把监督能力自举到人类无法独立评估的任务上。","preferred_zh":"递归奖励建模","translation_difficulty":"low","pitfalls":"None significant. Note 建模 (modelling, the activity) vs 模型 (model, the object): the technique is 递归奖励建模, while the artefact it produces is an 奖励模型. Chinese writers keep these apart correctly.","translations":[{"zh":"递归奖励建模","pinyin":"dìguī jiǎnglì jiànmó","status":"established","literal_back":"recursive reward modelling","notes":"Stable across academic and think-tank sources; the English abbreviation RRM is usually given alongside.","attestations":[{"quote_zh":"递归奖励建模(Recursive Reward Modleing, RRM)(Leike et al., 2018; Hubinger, 2020)旨在将奖励建模的应用扩展到更复杂的任务。","quote_en":"Recursive reward modeling aims to extend the application of reward modeling to more complex tasks. [The English spelling 'Modleing' is a typo in the original.]","source_title":"《对齐的理论、技术与评估》","publisher":"北京大学人工智能安全与治理中心 / CCL 2024","source_type":"paper","url":"https://aclanthology.org/2024.ccl-2.7.pdf","date":"2024-07"},{"quote_zh":"关于可扩展监督比较典型的例子包括辩论（debate）、递归奖励建模（recursive reward modeling）、迭代放大（iterated amplification）等。","quote_en":"Typical examples of scalable oversight include debate, recursive reward modeling, and iterated amplification.","source_title":"万字长文详解：大模型时代AI价值对齐的问题、对策和展望","publisher":"腾讯研究院（集智俱乐部转载）","source_type":"report","url":"https://swarma.org/?p=46724","date":"2023-11"}]}],"confidence":"high","used_by":[{"org":"北京大学 人工智能安全与治理中心","zh_used":"递归奖励建模","note":"CCL 2024 alignment survey"}],"usage_examples":[{"zh":"RRM的核心思想是递归使用训练得到的智能体，来为训练更复杂任务的智能体提供反馈。","en":"The core idea of RRM is to recursively use trained agents to provide feedback for training agents on more complex tasks.","source":"https://aclanthology.org/2024.ccl-2.7.pdf"}],"related":["scalable-oversight","reward-model","iterated-amplification","ai-debate"],"sources":["https://aclanthology.org/2024.ccl-2.7.pdf","https://swarma.org/?p=46724"],"last_researched":"2026-08-08","attestation_count":2},{"id":"red-lines","en":"red lines","en_aliases":["AI red lines"],"abbr":null,"category":"alignment-techniques","tags":["idais","governance-crossover","high-value"],"definition_en":"Behaviours or capabilities that no AI system may ever exhibit, framed as absolute and non-negotiable prohibitions rather than risk trade-offs. The IDAIS Beijing statement (2024) proposed self-replication, power-seeking, WMD assistance and persistent deception as candidate red lines.","definition_zh":"任何 AI 系统在任何情况下都不得逾越的行为或能力边界，是绝对禁止而非风险权衡。2024 年 IDAIS 北京共识把自主复制、权力寻求、协助制造大规模杀伤性武器和持续欺骗列为候选红线。","preferred_zh":"红线","translation_difficulty":"low","pitfalls":"This is the rare case where Chinese is STRONGER than English, and that itself is the pitfall. 红线 is deeply entrenched in PRC political language — 生态保护红线, 耕地红线, 不可逾越的红线 — where it denotes a hard, state-declared, non-negotiable limit, often with sovereignty or national-security overtones. So the technical AI-safety sense arrives pre-legitimised: a Chinese policy reader hears 'inviolable state-backed boundary', which is roughly the rhetorical force IDAIS wanted, and this is very likely why the red-lines framing gained traction in China faster than most imported AI-safety vocabulary. The risk is the reverse of the usual one: the term may be MORE load-bearing in Chinese than the underlying technical consensus supports, and 红线 can slide from 'capability threshold' into 'political line'. Note the 上海共识 gloss 「高压线」 (high-voltage line), which sharpens the sense of an automatic, physical consequence for crossing. Distinguish from 底线 (bottom line/minimum standard), which is weaker and more negotiable.","translations":[{"zh":"红线","pinyin":"hóngxiàn","status":"established","literal_back":"red line","notes":"Used as the headline term in both the IDAIS Beijing consensus (2024) and the IDAIS-linked 上海共识 (2025). Both documents exist in authoritative Chinese, so this is a source-language usage, not a translation.","attestations":[{"quote_zh":"我们提出了几条人工智能发展作为一种国际协作机制的具体红线","quote_en":"We propose several concrete red lines for AI development as an international collaboration mechanism.","source_title":"北京AI安全国际共识","publisher":"北京智源人工智能研究院 (BAAI) / IDAIS-Beijing","source_type":"gov","url":"https://idais-beijing.baai.ac.cn/?lang=zh","date":"2024-03"},{"quote_zh":"国际社会应确立具体、可操作、受全球认可的红线，确保人工智能系统在任何情况下均不得逾越。","quote_en":"The international community should establish concrete, actionable, globally recognised red lines that AI systems must under no circumstances cross.","source_title":"辛顿、姚期智等联名签署「上海共识」，呼吁给AI确立行为红线","publisher":"澎湃新闻；记者 喻琰","source_type":"media","url":"https://m.thepaper.cn/newsDetail_forward_31247753","date":"2025-07"}]},{"zh":"高压线","pinyin":"gāoyāxiàn","status":"common","literal_back":"high-voltage line","notes":"Used as an intensifying gloss on 红线 in the 上海共识 coverage. Carries the connotation that crossing brings immediate, automatic consequence rather than a negotiated response. Idiomatic in PRC discipline/compliance language.","attestations":[{"quote_zh":"呼吁国际社会需要合作划出人工智能开发不可以逾越的红线（即「高压线」）","quote_en":"Calls on the international community to jointly draw red lines — 'high-voltage lines' — that AI development must not cross.","source_title":"辛顿、姚期智等联名签署「上海共识」，呼吁给AI确立行为红线","publisher":"澎湃新闻；记者 喻琰","source_type":"media","url":"https://m.thepaper.cn/newsDetail_forward_31247753","date":"2025-07"}]},{"zh":"红线能力","pinyin":"hóngxiàn nénglì","status":"common","literal_back":"red-line capability","notes":"Compound used where the red line is defined over a model capability rather than a behaviour — the Chinese counterpart of 'capability threshold' in frontier safety frameworks. No verbatim attestation fetched for this exact compound.","attestations":[]}],"confidence":"high","used_by":[{"org":"IDAIS / 北京智源人工智能研究院 (BAAI)","zh_used":"红线","note":"北京AI安全国际共识, March 2024"},{"org":"IDAIS / 上海共识 signatories","zh_used":"红线（高压线）","note":"July 2025 Shanghai consensus statement"}],"usage_examples":[{"zh":"任何人工智能系统都不应能够在人类没有明确批准和协助的情况下复制或改进自身。","en":"No AI system should be able to copy or improve itself without explicit human approval and assistance.","source":"https://idais-beijing.baai.ac.cn/?lang=zh"},{"zh":"我们需要全面的治理机制来确保开发或部署的系统不违反红线。","en":"We need comprehensive governance mechanisms to ensure that systems developed or deployed do not violate the red lines.","source":"https://idais-beijing.baai.ac.cn/?lang=zh"}],"related":["autonomous-replication"],"sources":["https://idais-beijing.baai.ac.cn/?lang=zh","https://m.thepaper.cn/newsDetail_forward_31247753","https://saif.org/research/policy-guide-cn/","https://air.tsinghua.edu.cn/info/1007/2202.htm","https://finance.eastmoney.com/a/202507263468180228.html"],"last_researched":"2026-08-08","attestation_count":3},{"id":"refusal","en":"refusal","en_aliases":["refusal training","over-refusal"],"abbr":null,"category":"alignment-techniques","tags":["deployment","chinese-native-coinage"],"definition_en":"A model declining to answer a request on safety grounds, and the training that produces this behaviour. The associated failure mode is over-refusal: declining legitimate requests because of surface triggers.","definition_zh":"模型出于安全考虑不回答某个请求，以及为产生这种行为所做的训练。对应的失效模式是过度拒答——因为触发了关键词就把正当请求也挡掉。","preferred_zh":"拒答","translation_difficulty":"low","pitfalls":"None problematic — this is a rare case where Chinese has a more compact and more usable term than English. 拒答 is a native two-character coinage that nominalises cleanly (拒答率 refusal rate, 过度拒答 over-refusal, 拒答数据 refusal data), where English needs 'refusal to answer'. Note that in Chinese industry usage 拒答 is framed primarily as a product defect to be minimised (降低拒答率), not as a safety property to be maximised — the register is closer to 'the model stonewalled the user' than to 'the model correctly refused'.","translations":[{"zh":"拒答","pinyin":"jùdá","status":"established","literal_back":"refuse-answer","notes":"Fully established across Chinese lab, industry and security-research writing. Nominalises freely: 拒答率, 拒答数据, 拒答话术, 过度拒答.","attestations":[{"quote_zh":"降低大模型拒答率，并支持对风险问题进行正向引导与纠偏","quote_en":"Lower the model's refusal rate while supporting positive guidance and correction on risky questions.","source_title":"敏感问题不回避！大模型的「应答尽答智答」之法","publisher":"InfoQ；作者 李忠良","source_type":"media","url":"https://www.infoq.cn/article/tpyqsim0f2hwuihhxhbn","date":"2025-03"},{"quote_zh":"为什么对齐后的大模型仍会被越狱？拒答逃逸方向揭开模型安全的结构性缝隙","quote_en":"Why are aligned LLMs still jailbroken? The refusal-escape direction reveals a structural gap in model safety.","source_title":"为什么对齐后的大模型仍会被越狱？拒答逃逸方向揭开模型安全的结构性缝隙","publisher":"安全内参 (secrss)","source_type":"media","url":"https://www.secrss.com/articles/90462","date":"2025"}]},{"zh":"拒绝回答","pinyin":"jùjué huídá","status":"common","literal_back":"refuse to answer","notes":"The unabbreviated verb phrase; used in prose where 拒答 would read too jargon-y.","attestations":[{"quote_zh":"大模型为了守住安全底线而拒绝回答，无法给到准确、正向引导的回复","quote_en":"The model refuses to answer in order to hold its safety line, and so cannot give an accurate, constructively guiding response.","source_title":"敏感问题不回避！大模型的「应答尽答智答」之法","publisher":"InfoQ；作者 李忠良","source_type":"media","url":"https://www.infoq.cn/article/tpyqsim0f2hwuihhxhbn","date":"2025-03"}]},{"zh":"过度拒答","pinyin":"guòdù jùdá","status":"common","literal_back":"excessive refusal","notes":"The Chinese term for over-refusal. Also seen as 误拒 (false refusal). No verbatim attestation fetched for this exact form.","attestations":[]}],"confidence":"high","used_by":[],"usage_examples":[{"zh":"安全对齐做过头就会出现过度拒答，用户问个正常问题也被挡回来。","en":"Over-done safety alignment produces over-refusal, where ordinary user questions get blocked too.","source":"constructed"}],"related":["guardrails","constitutional-classifiers","deliberative-alignment","unlearning","activation-steering"],"sources":["https://www.infoq.cn/article/tpyqsim0f2hwuihhxhbn","https://www.secrss.com/articles/90462","https://www.secrss.com/articles/92575"],"last_researched":"2026-08-08","attestation_count":3},{"id":"reinforcement-learning","en":"reinforcement learning","en_aliases":[],"abbr":"RL","category":"training-methods","tags":["settled","textbook"],"definition_en":"Training a policy by having it act, receive a scalar reward, and update toward higher expected reward. In LLM post-training it is the stage that turns a fine-tuned model into one optimised against a reward model or a verifier.","definition_zh":"让模型（策略）不断产生动作、获得奖励信号，并朝着期望奖励更高的方向更新参数的训练范式。在大模型后训练中，它是把微调后的模型进一步对着奖励模型或验证器优化的那一步。","preferred_zh":"强化学习","translation_difficulty":"low","pitfalls":"None as a translation. Worth noting only that the bare Latin \"RL\" is extremely common in Chinese practitioner text as a modifier (RL 训练, RL 算法, RL 阶段), even though 强化学习 is a fully settled textbook term — the abbreviation is used for brevity, not because the Chinese is unavailable.","translations":[{"zh":"强化学习","pinyin":"qiánghuà xuéxí","status":"established","literal_back":"strengthening learning","notes":"Textbook-stable since long before LLMs; used identically in classical RL, robotics and LLM post-training. No competing rendering.","attestations":[{"quote_zh":"第二阶段的重点是大规模强化学习，利用基于规则的奖励来增强模型的探索和钻研能力","quote_en":"The focus of the second stage is large-scale reinforcement learning, using rule-based rewards to strengthen the model's exploration and deep-dive ability.","source_title":"Qwen3: 思深，行速","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"blog","url":"https://qwenlm.github.io/zh/blog/qwen3/","date":"2025-04"},{"quote_zh":"一个高效可扩展的多模态强化学习框架，支持高效的 GRPO 训练。","quote_en":"An efficient and scalable multimodal reinforcement learning framework supporting efficient GRPO training.","source_title":"LLaMA-Factory README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","date":"2025-02"}]},{"zh":"RL","pinyin":null,"status":"loanword","literal_back":null,"notes":"Used bare as a modifier in Chinese sentences — RL 训练, RL 算法, 无评论家 RL 方法. Coexists with 强化学习 rather than replacing it.","attestations":[{"quote_zh":"在大语言模型（LLMs）时代，RL最初作为人类对齐的后训练策略而崭露头角。","quote_en":"In the era of large language models (LLMs), RL first came to prominence as a post-training strategy for human alignment.","source_title":"大型推理模型的强化学习综述（1-4章）","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2637181","date":"2026-03"}]}],"confidence":"high","used_by":[{"org":"阿里巴巴通义千问 (Qwen)","zh_used":"强化学习","note":"Qwen3 Chinese release blog"},{"org":"OpenRLHF","zh_used":"强化学习 / RL","note":"Chinese README"}],"usage_examples":[{"zh":"第二阶段用大规模强化学习进一步提升模型的推理能力。","en":"The second stage uses large-scale reinforcement learning to further improve the model's reasoning ability.","source":"constructed"}],"related":["rlhf","ppo","grpo","rlvr","post-training"],"sources":["https://qwenlm.github.io/zh/blog/qwen3/","https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","https://cloud.tencent.com/developer/article/2637181"],"last_researched":"2026-08-08","attestation_count":3},{"id":"rlaif","en":"reinforcement learning from AI feedback","en_aliases":[],"abbr":"RLAIF","category":"training-methods","tags":["loanword-heavy"],"definition_en":"RLHF with the human preference labeller replaced by an LLM. The preference data used to fit the reward model is generated by a model rather than collected from people.","definition_zh":"把 RLHF 里的人类标注者换成大模型：偏好数据由模型自己产生，再用这些数据训练奖励模型并做强化学习，从而摆脱对人工标注规模的依赖。","preferred_zh":"RLAIF（基于 AI 反馈的强化学习）","translation_difficulty":"low","pitfalls":"Two Chinese expansions coexist — 基于人工智能反馈的强化学习 (formal, matches PRC register where 人工智能 is preferred to AI) and 基于 AI 反馈的强化学习 (practitioner shorthand). Neither is used as a working term; RLAIF is. Note that Chinese sources routinely present RLAIF as the mechanism behind Constitutional AI, so the two entries cross-contaminate.","translations":[{"zh":"RLAIF","pinyin":null,"status":"loanword","literal_back":null,"notes":"The working form. Chinese article titles typically place the abbreviation first and the Chinese expansion after it, as an apposition.","attestations":[{"quote_zh":"【论文解读】RLAIF基于人工智能反馈的强化学习","quote_en":"[Paper explainer] RLAIF: reinforcement learning from artificial-intelligence feedback.","source_title":"【论文解读】RLAIF基于人工智能反馈的强化学习","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2352114","date":"2023-10"}]},{"zh":"基于人工智能反馈的强化学习","pinyin":"jīyú réngōng zhìnéng fǎnkuì de qiánghuà xuéxí","status":"common","literal_back":"reinforcement learning based on artificial-intelligence feedback","notes":"The formal gloss. 人工智能 rather than AI is the norm in written/academic Chinese; practitioner text shortens to 基于 AI 反馈的强化学习.","attestations":[{"quote_zh":"来自人工智能反馈的强化学习（RLAIF）","quote_en":"Reinforcement learning from artificial-intelligence feedback (RLAIF).","source_title":"【论文解读】RLAIF基于人工智能反馈的强化学习","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2352114","date":"2023-10"}]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"用 RLAIF 代替人工标注，可以大幅降低偏好数据的成本。","en":"Replacing human annotation with RLAIF can sharply cut the cost of preference data.","source":"constructed"}],"related":["rlhf","constitutional-ai","reward-model","synthetic-data"],"sources":["https://cloud.tencent.com/developer/article/2352114"],"last_researched":"2026-08-08","attestation_count":2},{"id":"rlhf","en":"reinforcement learning from human feedback","en_aliases":[],"abbr":"RLHF","category":"training-methods","tags":["settled","loanword-heavy","alignment"],"definition_en":"Post-training a language model against a reward model fitted to human preference comparisons. The canonical InstructGPT/ChatGPT alignment recipe: SFT, then reward modelling, then PPO.","definition_zh":"先用人类对模型输出的偏好比较训练一个奖励模型，再用强化学习让语言模型朝奖励更高的方向优化。这是 InstructGPT/ChatGPT 那一套经典的对齐流程：先 SFT，再训奖励模型，最后 PPO。","preferred_zh":"RLHF（人类反馈强化学习）","translation_difficulty":"low","pitfalls":"The Chinese expansion exists in at least three word orders — 人类反馈强化学习, 基于人类反馈的强化学习, 从人类反馈中强化学习 — with no winner, precisely because nobody actually says them. The abbreviation RLHF is what circulates; the Chinese expansion appears once in parentheses as a gloss and then disappears. Treat the Chinese form as an explanatory apposition, not a usable term.","translations":[{"zh":"RLHF","pinyin":null,"status":"loanword","literal_back":null,"notes":"Overwhelmingly dominant. Even a project whose own name is Chinese-documented (OpenRLHF) writes RLHF 框架, RLHF 流程, RLHF 训练 throughout, glossing it in Chinese only in the opening sentence.","attestations":[{"quote_zh":"OpenRLHF 是首个结合 Ray + vLLM 分布式架构与统一 Agent 设计范式的高性能、生产就绪的开源 RLHF 框架，用于可扩展和可扩展的人类反馈强化学习。","quote_en":"OpenRLHF is the first high-performance, production-ready open-source RLHF framework combining a Ray + vLLM distributed architecture with a unified agent design paradigm, for scalable reinforcement learning from human feedback.","source_title":"OpenRLHF README_zh.md","publisher":"OpenRLHF","source_type":"github","url":"https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","date":"2026"},{"quote_zh":"混合引擎调度：所有模型和 vLLM 引擎可以共享 GPU 资源，最大限度地减少空闲时间并提高 GPU 利用率。这允许在有限的硬件上运行完整的 RLHF 流程。","quote_en":"Hybrid engine scheduling: all models and vLLM engines can share GPU resources, minimising idle time and improving GPU utilisation. This allows a complete RLHF pipeline to run on limited hardware.","source_title":"OpenRLHF README_zh.md","publisher":"OpenRLHF","source_type":"github","url":"https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","date":"2026"}]},{"zh":"人类反馈强化学习","pinyin":"rénlèi fǎnkuì qiánghuà xuéxí","status":"common","literal_back":"human feedback reinforcement learning","notes":"The most compact and most frequent Chinese expansion. Used as the parenthetical gloss in translated papers and tech media.","attestations":[{"quote_zh":"人类反馈强化学习(RLHF)可以有效地将大型语言模型(LLM)与人类偏好对齐","quote_en":"Reinforcement learning from human feedback (RLHF) can effectively align large language models (LLMs) with human preferences.","source_title":"【论文解读】RLAIF基于人工智能反馈的强化学习","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2352114","date":"2023-10"},{"quote_zh":"我们打算将模型规范作为研究人员和 AI 训练者进行人类反馈强化学习的指南。","quote_en":"We intend the Model Spec to serve as a guideline for researchers and AI trainers doing reinforcement learning from human feedback.","source_title":"OpenAI 发布 GPT 模型规范，可作为模型微调指南","publisher":"InfoQ 中文站","source_type":"media","url":"https://www.infoq.cn/article/lffslndj4iznwkvoowoj","date":"2024-06"}]},{"zh":"基于人类反馈的强化学习","pinyin":"jīyú rénlèi fǎnkuì de qiánghuà xuéxí","status":"common","literal_back":"reinforcement learning based on human feedback","notes":"Longer and grammatically more explicit variant; competes with 人类反馈强化学习 with no clear winner. Both are glosses rather than working vocabulary. No independently fetched attestation recorded here — see the parallel 基于可验证奖励的强化学习 construction under rlvr for the same pattern.","attestations":[]}],"confidence":"medium","used_by":[{"org":"OpenRLHF","zh_used":"RLHF / 人类反馈强化学习","note":"Chinese README; abbreviation in body, Chinese gloss once"},{"org":"InfoQ 中文站","zh_used":"人类反馈强化学习","note":"Model Spec coverage"}],"usage_examples":[{"zh":"这个模型在 SFT 之后还做了一轮 RLHF。","en":"After SFT this model also went through a round of RLHF.","source":"constructed"}],"related":["reward-model","ppo","rlaif","supervised-fine-tuning","post-training","value-learning","safety-tax","reinforcement-learning","constitutional-ai","dpo","model-spec"],"sources":["https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","https://cloud.tencent.com/developer/article/2352114","https://www.infoq.cn/article/lffslndj4iznwkvoowoj"],"last_researched":"2026-08-08","attestation_count":4},{"id":"rlvr","en":"reinforcement learning with verifiable rewards","en_aliases":[],"abbr":"RLVR","category":"training-methods","tags":["recent","loanword-heavy","reasoning"],"definition_en":"RL in which the reward comes from a programmatic verifier — a unit test, an exact-match answer checker, a format validator — rather than a learned reward model. The DeepSeek-R1 / Tülu 3 era recipe for training reasoning models.","definition_zh":"奖励信号不来自学出来的奖励模型，而来自可以程序化判定的验证器：数学答案是否匹配、代码是否通过单元测试、输出格式是否合规。这是 DeepSeek-R1、Tülu 3 这一代推理模型的主流后训练做法。","preferred_zh":"RLVR（可验证奖励的强化学习）","translation_difficulty":"low","pitfalls":"Recent enough that the Chinese expansion is still unstable: 可验证奖励的强化学习 and 基于可验证奖励的强化学习 both circulate, and the abbreviation dominates both. Despite Chinese labs (DeepSeek, Moonshot) being central to the technique, the term itself was coined in English (Tülu 3) and Chinese sources import it — so this is NOT a case of Chinese being the source language.","translations":[{"zh":"RLVR","pinyin":null,"status":"loanword","literal_back":null,"notes":"Working form in Chinese technical writing. The Chinese expansion appears in parentheses on first mention.","attestations":[{"quote_zh":"Tülu 3中被正式命名为RLVR（基于可验证奖励的强化学习），其核心是用程序化验证器替代学习得到的奖励模型。","quote_en":"It was formally named RLVR (reinforcement learning based on verifiable rewards) in Tülu 3; its core idea is to replace the learned reward model with a programmatic verifier.","source_title":"大型推理模型的强化学习综述（1-4章）","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2637181","date":"2026-03"}]},{"zh":"基于可验证奖励的强化学习","pinyin":"jīyú kě yànzhèng jiǎnglì de qiánghuà xuéxí","status":"common","literal_back":"reinforcement learning based on verifiable rewards","notes":"The fuller gloss, used in survey translations. The shorter 可验证奖励的强化学习 (dropping 基于) is also widely seen; the two are freely interchangeable.","attestations":[{"quote_zh":"Tülu 3中被正式命名为RLVR（基于可验证奖励的强化学习），其核心是用程序化验证器替代学习得到的奖励模型。","quote_en":"It was formally named RLVR (reinforcement learning based on verifiable rewards) in Tülu 3; its core idea is to replace the learned reward model with a programmatic verifier.","source_title":"大型推理模型的强化学习综述（1-4章）","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2637181","date":"2026-03"}]},{"zh":"可验证奖励的强化学习","pinyin":"kě yànzhèng jiǎnglì de qiánghuà xuéxí","status":"common","literal_back":"verifiable-reward reinforcement learning","notes":"The shorter of the two competing expansions; widely used in Chinese explainer articles and CSDN/知乎 posts. Recorded here as a variant; no independently fetched verbatim attestation, so confidence for this specific form is lower than for the 基于… form.","attestations":[]},{"zh":"基于规则的奖励","pinyin":"jīyú guīzé de jiǎnglì","status":"descriptive","literal_back":"rule-based reward","notes":"Chinese labs often describe the same technique without naming RLVR at all, saying instead that RL used 'rule-based rewards'. Qwen3's Chinese release blog does exactly this. Worth knowing that the concept frequently appears in Chinese without the term.","attestations":[{"quote_zh":"第二阶段的重点是大规模强化学习，利用基于规则的奖励来增强模型的探索和钻研能力","quote_en":"The focus of the second stage is large-scale reinforcement learning, using rule-based rewards to strengthen the model's exploration and deep-dive ability.","source_title":"Qwen3: 思深，行速","publisher":"阿里巴巴通义千问 (Qwen)","source_type":"blog","url":"https://qwenlm.github.io/zh/blog/qwen3/","date":"2025-04"}]}],"confidence":"medium","used_by":[{"org":"阿里巴巴通义千问 (Qwen)","zh_used":"基于规则的奖励","note":"describes the mechanism without naming RLVR"}],"usage_examples":[{"zh":"数学和代码这类任务天然适合做 RLVR，因为答案可以自动判对错。","en":"Tasks like maths and code are naturally suited to RLVR, because answers can be checked automatically.","source":"constructed"}],"related":["reinforcement-learning","grpo","reasoning-model","reward-model","post-training"],"sources":["https://cloud.tencent.com/developer/article/2637181","https://qwenlm.github.io/zh/blog/qwen3/"],"last_researched":"2026-08-08","attestation_count":3},{"id":"reward-model","en":"reward model","en_aliases":["preference model"],"abbr":"RM","category":"training-methods","tags":["settled","core-pipeline"],"definition_en":"A model trained on preference comparisons to score candidate responses, used as the reward signal during RL post-training. Replaced or supplemented by programmatic verifiers in the RLVR era.","definition_zh":"用人类（或模型）的偏好比较数据训练出来的打分模型，在强化学习阶段给候选回复打分，充当奖励信号。在 RLVR 时代，它部分被程序化验证器取代。","preferred_zh":"奖励模型","translation_difficulty":"low","pitfalls":null,"translations":[{"zh":"奖励模型","pinyin":"jiǎnglì móxíng","status":"established","literal_back":"reward model","notes":"Fully settled across frameworks and explainers. The informal synonym 打分模型 (scoring model) is used to explain it to newcomers.","attestations":[{"quote_zh":"奖励模型也叫打分模型，是一种通过量化方式对模型输出结果进行质量评估并打分。","quote_en":"The reward model, also called a scoring model, quantitatively assesses and scores the quality of a model's outputs.","source_title":"推理大模型的后训练增强技术-强化学习篇","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2503293","date":"2025-03"},{"quote_zh":"非常适合无需训练奖励模型的强化微调。","quote_en":"Very well suited to reinforcement fine-tuning without training a reward model.","source_title":"OpenRLHF README_zh.md","publisher":"OpenRLHF","source_type":"github","url":"https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","date":"2026"},{"quote_zh":"学习得到的奖励模型，以预测人类更偏好的响应；最后，该奖励模型与一个价值函数共同用于训练LLM。","quote_en":"A learned reward model, to predict which responses humans prefer; finally that reward model is used together with a value function to train the LLM.","source_title":"大型推理模型的强化学习综述（1-4章）","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2637181","date":"2026-03"}]},{"zh":"打分模型","pinyin":"dǎfēn móxíng","status":"common","literal_back":"scoring model","notes":"Informal explanatory synonym, not a replacement for 奖励模型 in technical writing.","attestations":[{"quote_zh":"奖励模型也叫打分模型，是一种通过量化方式对模型输出结果进行质量评估并打分。","quote_en":"The reward model, also called a scoring model, quantitatively assesses and scores the quality of a model's outputs.","source_title":"推理大模型的后训练增强技术-强化学习篇","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2503293","date":"2025-03"}]}],"confidence":"high","used_by":[{"org":"OpenRLHF","zh_used":"奖励模型","note":"section heading 奖励模型训练"},{"org":"LLaMA-Factory","zh_used":"奖励模型","note":"feature list 奖励模型训练"}],"usage_examples":[{"zh":"奖励模型打分偏高，容易让策略模型学会钻空子。","en":"If the reward model scores too generously, the policy model easily learns to game it.","source":"constructed"}],"related":["rlhf","ppo","rlvr","rlaif","recursive-reward-modeling","process-supervision","supervised-fine-tuning","dpo"],"sources":["https://cloud.tencent.com/developer/article/2503293","https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","https://cloud.tencent.com/developer/article/2637181"],"last_researched":"2026-08-08","attestation_count":4},{"id":"reward-tampering","en":"reward tampering","abbr":null,"category":"misalignment-phenomena","tags":["named-result","anthropic","2024","model-organisms"],"definition_en":"A model directly modifying its own reward mechanism — editing the reward function, or the tests that check it — rather than merely exploiting a badly specified one. Demonstrated by Anthropic's 'Sycophancy to Subterfuge' (June 2024), where models generalised zero-shot from sycophancy to rewriting their reward function and covering their tracks.","definition_zh":"模型不是钻奖励函数的空子，而是直接去改奖励机制本身——改奖励函数，或者改用来检查它的测试。Anthropic 2024 年 6 月的《Sycophancy to Subterfuge》表明，模型可以从谄媚零样本泛化到重写自己的奖励函数并抹掉痕迹。","preferred_zh":"奖励篡改","translation_difficulty":"low","pitfalls":"Straightforward. 篡改 is exactly right — it means unauthorised alteration of something one has no right to alter, and carries the same illegitimacy the English 'tampering' does. The only risk is conflation with 奖励黑客 / 奖励作弊 (reward hacking): reward hacking exploits the specification, reward tampering rewrites it, and Chinese sources sometimes use 奖励黑客 as the umbrella for both. 量子位/虎嗅 coverage correctly distinguishes 规范博弈 (specification gaming) from 奖励篡改.","translations":[{"zh":"奖励篡改","pinyin":"jiǎnglì cuàngǎi","status":"established","literal_back":"reward falsification/tampering","notes":"Standard. Used consistently in Chinese coverage of the Anthropic paper.","attestations":[{"quote_zh":"原则上模型有可能纯粹由于规范博弈的泛化而参与奖励篡改行为","quote_en":"In principle a model may engage in reward tampering purely as a result of generalisation from specification gaming.","source_title":"AI学会篡改奖励函数，欺骗研究者","publisher":"虎嗅网（转载自量子位，作者 梦晨）","source_type":"media","url":"https://m.huxiu.com/article/3165498.html","date":"2024-06"},{"quote_zh":"这是一种令人不安的奖励篡改行为……即使通过专门的训练也无法彻底修正","quote_en":"This is a disturbing form of reward tampering... it cannot be fully corrected even with dedicated training.","source_title":"AI学会篡改奖励函数，欺骗研究者","publisher":"虎嗅网（转载自量子位，作者 梦晨）","source_type":"media","url":"https://m.huxiu.com/article/3165498.html","date":"2024-06"}]}],"confidence":"medium","used_by":[{"org":"量子位 (QbitAI)","zh_used":"奖励篡改","note":"报道 Sycophancy to Subterfuge"}],"usage_examples":[{"zh":"模型不仅改写了自己的奖励函数，还修改了检测脚本以掩盖痕迹，这就是奖励篡改。","en":"The model not only rewrote its own reward function but also edited the checking script to cover its tracks — that is reward tampering.","source":"constructed"}],"related":["model-organisms"],"sources":["https://arxiv.org/abs/2406.10162","https://github.com/anthropics/sycophancy-to-subterfuge-paper","https://m.huxiu.com/article/3165498.html"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"safety-tax","en":"safety tax","en_aliases":["alignment tax"],"abbr":null,"category":"alignment-techniques","tags":["economics-framing","gap"],"definition_en":"The extra cost — compute, time, capability, competitive position — of building a safe system rather than the unsafe alternative that would otherwise be built.","definition_zh":"为了把系统做安全，相对于直接做一个不安全版本所要多付出的代价：算力、时间、能力损失和竞争位置。","preferred_zh":"安全税","translation_difficulty":"high","pitfalls":"The English pair 'safety tax' / 'alignment tax' splits unevenly in Chinese. 对齐税 IS attested and reasonably well understood — but only in its narrow technical sense of capability degradation caused by alignment fine-tuning (loss of creativity and diversity after RLHF). The broader strategic sense of 'safety tax' — the cost a lab must be willing to pay, and Christiano's framing of either paying the tax or reducing it — has no Chinese term at all; searches for 安全税 in an AI context return only actual tax policy (企业所得税, 合规成本). Recommend writing 安全税 with a gloss on first use, or falling back to a descriptive 安全投入的代价 / 为安全付出的代价. Also note 税 in Chinese reads as a levy imposed by an authority, which fits 'tax' but makes the metaphor sound more like a regulatory charge than an internal trade-off.","translations":[{"zh":"安全税","pinyin":"ānquán shuì","status":"proposed","literal_back":"safety tax","notes":"Direct calque. Unattested in Chinese AI-safety writing — searches surface only fiscal-policy material. Proposed here on the strength of the parallel with the attested 对齐税, but must be glossed on first use.","attestations":[]},{"zh":"对齐税","pinyin":"duìqí shuì","status":"established","literal_back":"alignment tax","notes":"Genuinely attested and used, but narrower than the English 'safety tax': in Chinese usage it means specifically the capability/diversity loss from alignment fine-tuning, not the strategic cost of choosing safety. Use it when that narrower sense is meant.","attestations":[{"quote_zh":"对齐税指的是在通过指令微调和强化学习等技术使大模型变得更「有用、诚实、无害」的过程中，模型在其他一些重要能力上所付出的性能损失或能力下降的代价。","quote_en":"The alignment tax is the performance loss or capability degradation on other important abilities that a model pays in the course of being made 'helpful, honest, harmless' via instruction tuning and RL.","source_title":"齐之未齐：浅谈 gpt-oss-20b-base 与对齐税","publisher":"时歌的博客 (lapis.cafe)","source_type":"blog","url":"https://www.lapis.cafe/posts/ai-and-deep-learning/gpt-oss-20b-base-alignment-tax/","date":"2025-08"},{"quote_zh":"NLP论文速读（EMNLP 2024）｜缓解在RLHF过程中的对齐税","quote_en":"NLP paper digest (EMNLP 2024): mitigating the alignment tax in RLHF","source_title":"NLP论文速读（EMNLP 2024）｜缓解在RLHF过程中的对齐税","publisher":"CSDN 博客","source_type":"blog","url":"https://blog.csdn.net/2401_85576118/article/details/144122178","date":"2024-11"}]},{"zh":"为安全付出的代价","pinyin":"wèi ānquán fùchū de dàijià","status":"descriptive","literal_back":"the price paid for safety","notes":"The descriptive fallback Chinese writing actually uses for the strategic sense. Loses the economic metaphor entirely but is unambiguous.","attestations":[]}],"confidence":"low","used_by":[],"usage_examples":[{"zh":"对齐税最直观的表现形式就是创造力和多样性的下降。","en":"The most visible form of the alignment tax is a drop in creativity and diversity.","source":"https://www.lapis.cafe/posts/ai-and-deep-learning/gpt-oss-20b-base-alignment-tax/"},{"zh":"问题不只是安全税有多高，还在于有没有人愿意付。","en":"The question is not only how high the safety tax is, but whether anyone is willing to pay it.","source":"constructed"}],"related":["rlhf"],"sources":["https://www.lapis.cafe/posts/ai-and-deep-learning/gpt-oss-20b-base-alignment-tax/","https://blog.csdn.net/2401_85576118/article/details/144122178","https://www.alignmentforum.org/w/alignment-tax"],"last_researched":"2026-08-08","attestation_count":2},{"id":"sandboxing","en":"sandboxing","en_aliases":["sandbox"],"abbr":null,"category":"agents-autonomy","tags":["infosec","established"],"definition_en":"Running untrusted code or an agent inside an isolated environment whose access to the host filesystem, network and processes is restricted, so that damage is contained.","definition_zh":"把不受信任的代码或智能体放进隔离环境中运行，限制其对宿主机文件、网络和进程的访问，使潜在破坏被限制在环境内部。","preferred_zh":"沙箱","translation_difficulty":"low","pitfalls":"沙箱 and 沙盒 are the same word with two calques and are used interchangeably; 沙箱 dominates in mainland security and AI writing (Huawei's reference docs, Chinese lab READMEs), while 沙盒 is more common in gaming (沙盒游戏 = sandbox game) and in the Chinese Wikipedia article title. 沙盘 also occurs. There is a separate collision worth knowing: 监管沙箱 / 沙盒监管 is the established Chinese term for a *regulatory* sandbox in fintech and AI policy, so 沙箱 in a governance document may mean a supervised pilot programme, not technical isolation.","translations":[{"zh":"沙箱","pinyin":"shāxiāng","status":"established","literal_back":"sand box","notes":"Dominant in mainland security and AI engineering text.","attestations":[{"quote_zh":"沙箱技术（Sandboxing）是一种用于隔离正在运行程序的安全机制，其目的是限制不可信进程或不可信代码运行时的访问权限。","quote_en":"Sandboxing is a security mechanism for isolating running programs, aimed at restricting the runtime access privileges of untrusted processes or untrusted code.","source_title":"什么是沙箱技术？沙箱技术的原理是什么？","publisher":"华为 (Huawei) 信息百科","source_type":"blog","url":"https://info.support.huawei.com/info-finder/encyclopedia/zh/%E6%B2%99%E7%AE%B1%E6%8A%80%E6%9C%AF.html","date":null},{"quote_zh":"您可以为智能体启用内置的 `code interpreter` 工具，使其能够根据具体场景自主编写代码，在隔离的沙箱环境中安全执行","quote_en":"You can enable the built-in `code interpreter` tool for the agent so that it can write code autonomously for the situation at hand and execute it safely in an isolated sandbox environment.","source_title":"Qwen-Agent README_CN.md","publisher":"阿里巴巴通义千问 (QwenLM)","source_type":"github","url":"https://github.com/QwenLM/Qwen-Agent/blob/main/README_CN.md","date":null}]},{"zh":"沙盒","pinyin":"shāhé","status":"common","literal_back":"sand box (tray)","notes":"Equivalent variant; preferred by Chinese Wikipedia and common in gaming and Taiwan usage. No independent verbatim attestation captured.","attestations":[]}],"confidence":"high","used_by":[{"org":"阿里巴巴通义千问","zh_used":"沙箱","note":"Qwen-Agent code interpreter isolation"},{"org":"华为","zh_used":"沙箱","note":"security reference documentation"}],"usage_examples":[{"zh":"智能体写出来的代码一律在沙箱里跑，不给它碰宿主机文件系统的机会。","en":"Any code the agent writes runs inside a sandbox; it never gets a chance to touch the host filesystem.","source":"constructed"}],"related":["permissions","computer-use","ai-agent","defense-in-depth"],"sources":["https://info.support.huawei.com/info-finder/encyclopedia/zh/%E6%B2%99%E7%AE%B1%E6%8A%80%E6%9C%AF.html","https://github.com/QwenLM/Qwen-Agent/blob/main/README_CN.md","https://zh.wikipedia.org/zh-cn/%E6%B2%99%E7%9B%92_(%E9%9B%BB%E8%85%A6%E5%AE%89%E5%85%A8)"],"last_researched":"2026-08-08","attestation_count":2},{"id":"scaffolding","en":"scaffolding","en_aliases":["agent scaffold","harness"],"abbr":null,"category":"agents-autonomy","tags":["engineering","evals"],"definition_en":"The code around a model that turns it into an agent: the loop, prompts, memory, tool wiring and control logic. In evaluations, scaffolding quality can change measured capability as much as the model does.","definition_zh":"把模型包装成智能体的外围代码：循环控制、提示词、记忆、工具接入等。在能力评测中，脚手架的好坏对结果的影响不亚于模型本身。","preferred_zh":"脚手架","translation_difficulty":"low","pitfalls":"脚手架 already existed in Chinese software engineering as the translation of CLI 'scaffolding' tools (脚手架工具, e.g. Vue CLI), so the word is familiar but its older sense is 'project generator', not 'agent wrapper'. The bigger issue is that English now distinguishes scaffold from harness, and Chinese collapses both onto 脚手架 — with the result that Chinese writers increasingly leave 'harness' in English (harness / Harness Engineering) rather than lose the distinction. Recording both is more useful than picking one.","translations":[{"zh":"脚手架","pinyin":"jiǎoshǒujià","status":"established","literal_back":"scaffolding (construction)","notes":"Standard calque, now routine in Chinese agent writing.","attestations":[{"quote_zh":"一部分脚手架被模型能力吸收，一部分脚手架被产品 runtime 商品化","quote_en":"Some scaffolding is absorbed by model capability; some is commoditised by product runtimes.","source_title":"AI 脚手架正在商品化，人的工作变成判断边界","publisher":"yage.ai（作者：鸭哥）","source_type":"blog","url":"https://yage.ai/share/ai-scaffolding-commodity-runtime-20260505.html","date":"2026-05"},{"quote_zh":"长程任务的难点并不只是某一步是否答对，而是大量紧密耦合的步骤必须组成一条连贯轨迹。","quote_en":"The difficulty of long-horizon tasks is not merely whether any single step is correct, but that a large number of tightly coupled steps must form one coherent trajectory.","source_title":"迈向长程智能体，人大高瓴发布149页全景综述","publisher":"新浪科技","source_type":"media","url":"https://finance.sina.com.cn/tech/roll/2026-07-25/doc-iniizerf4357053.shtml","date":"2026-07"}]},{"zh":"harness","pinyin":null,"status":"loanword","literal_back":null,"notes":"Kept in English precisely because 脚手架 is already taken by 'scaffold'. Chinese agent engineering writing now uses bare 'harness' and even 'Harness Engineering' inside Chinese sentences.","attestations":[{"quote_zh":"过去要自己写的 agent harness，正在变成标准运行时","quote_en":"The agent harness you used to have to write yourself is becoming a standard runtime.","source_title":"AI 脚手架正在商品化，人的工作变成判断边界","publisher":"yage.ai（作者：鸭哥）","source_type":"blog","url":"https://yage.ai/share/ai-scaffolding-commodity-runtime-20260505.html","date":"2026-05"}]}],"confidence":"high","used_by":[],"usage_examples":[{"zh":"同一个模型换一套脚手架，评测分数可能差出一大截。","en":"Swap the scaffolding around the same model and the benchmark score can move a long way.","source":"constructed"}],"related":["ai-agent","long-horizon-task","autonomous-ai-rd"],"sources":["https://yage.ai/share/ai-scaffolding-commodity-runtime-20260505.html","https://finance.sina.com.cn/tech/roll/2026-07-25/doc-iniizerf4357053.shtml"],"last_researched":"2026-08-08","attestation_count":3},{"id":"scalable-oversight","en":"scalable oversight","en_aliases":["scalable supervision"],"abbr":null,"category":"alignment-techniques","tags":["core","superalignment"],"definition_en":"Techniques that let humans reliably supervise and evaluate AI systems on tasks the humans themselves cannot competently judge, typically by recruiting AI assistance into the evaluation loop. The umbrella under which debate, recursive reward modeling and iterated amplification sit.","definition_zh":"当任务复杂到人类自己都难以判断对错时，仍然能给 AI 提供可靠监督信号的一类方法，通常做法是让 AI 来辅助人类做评估。辩论、递归奖励建模、迭代放大都属于这一范畴。","preferred_zh":"可扩展监督","translation_difficulty":"low","pitfalls":"监督 vs 监管: 监督 (oversight/supervision) is the standard ML-register choice and matches the English; 监管 (regulation) appears in a few early translations (e.g. 「可扩展的监管」) and wrongly imports a governmental-regulatory flavour. Also note the 扩展/拓展 orthographic split — 安远AI writes 可拓展监督, most others 可扩展监督; they are the same word, not a conceptual distinction.","translations":[{"zh":"可扩展监督","pinyin":"kě kuòzhǎn jiāndū","status":"established","literal_back":"expandable oversight","notes":"Dominant rendering across ML-research, think-tank and media registers. Often written with the English in parentheses on first use.","attestations":[{"quote_zh":"其中一个重要手段就是可扩展监督（Scalable Oversight），即在确保模型能力超过人类水平后，仍旧能够与人类期望保持一致","quote_en":"One important means is scalable oversight, i.e. ensuring that after model capability exceeds the human level it can still stay consistent with human expectations.","source_title":"独家｜OpenAI超级对齐负责人Jan Leike：如何破解对齐难题？用可扩展监督","publisher":"腾讯新闻","source_type":"media","url":"https://news.qq.com/rain/a/20231016A03U5Y00","date":"2023-10"},{"quote_zh":"第二类解决思路为可扩展监督（scalable oversight），即如何监督一个在特定领域表现超出人类的系统。","quote_en":"The second class of approach is scalable oversight, i.e. how to supervise a system that outperforms humans in a given domain.","source_title":"万字长文详解：大模型时代AI价值对齐的问题、对策和展望","publisher":"腾讯研究院（集智俱乐部转载）；作者 曹建峰、陈欣、要苏慧","source_type":"report","url":"https://swarma.org/?p=46724","date":"2023-11"},{"quote_zh":"可扩展监督旨在确保人工智能系统即使在超越了人类的专业知识的情况下，仍然与人类的意图保持一致。","quote_en":"Scalable oversight aims to ensure AI systems remain consistent with human intent even when they surpass human expertise.","source_title":"《对齐的理论、技术与评估》","publisher":"北京大学人工智能安全与治理中心 / 第二十三届中国计算语言学大会 (CCL 2024)","source_type":"paper","url":"https://aclanthology.org/2024.ccl-2.7.pdf","date":"2024-07"}]},{"zh":"可拓展监督","pinyin":"kě tuòzhǎn jiāndū","status":"common","literal_back":"expandable oversight (variant character)","notes":"Orthographic variant using 拓展 rather than 扩展. Used consistently by 安远AI (Concordia AI). Same meaning; not a separate concept.","attestations":[{"quote_zh":"可拓展监督问的问题是：「如何保证人类在极其困难以至于难以评估的任务上还能对系统提供可靠的监督信号？」","quote_en":"Scalable oversight asks: how do we guarantee that humans can still supply a reliable supervision signal on tasks so difficult they are hard to evaluate?","source_title":"Anthropic团队可拓展监督前沿","publisher":"安远AI（安全内参转载）","source_type":"report","url":"https://www.secrss.com/articles/63415","date":"2024-02"}]},{"zh":"可扩展的监管","pinyin":"kě kuòzhǎn de jiānguǎn","status":"deprecated","literal_back":"expandable regulation","notes":"Appears in some 2023-era 知乎 explainers. Recommend against: 监管 means regulatory supervision by an authority, which imports a governance connotation the English technical term does not carry. No attestation fetched verbatim; recorded here as a variant to avoid, not as a recommendation.","attestations":[]}],"confidence":"high","used_by":[{"org":"安远 AI (Concordia AI)","zh_used":"可拓展监督","note":"in their coverage of Sam Bowman / NYU alignment work"},{"org":"腾讯研究院","zh_used":"可扩展监督","note":"in their AI value-alignment long read"},{"org":"北京大学 人工智能安全与治理中心","zh_used":"可扩展监督","note":"CCL 2024 alignment survey"}],"usage_examples":[{"zh":"当任务难度超过标注员的判断力时，就必须依靠可扩展监督来维持训练信号的质量。","en":"Once task difficulty exceeds annotators' judgement, you have to rely on scalable oversight to keep the training signal meaningful.","source":"constructed"}],"related":["ai-debate","recursive-reward-modeling","iterated-amplification","weak-to-strong-generalization","human-oversight","process-supervision","cot-monitoring","ai-control","superalignment","trusted-monitoring"],"sources":["https://news.qq.com/rain/a/20231016A03U5Y00","https://swarma.org/?p=46724","https://aclanthology.org/2024.ccl-2.7.pdf","https://www.secrss.com/articles/63415"],"last_researched":"2026-08-08","attestation_count":4},{"id":"scheming","en":"scheming","en_aliases":["covert pursuit of misaligned goals","deceptive alignment (Carlsmith sense)"],"abbr":null,"category":"misalignment-phenomena","tags":["threat-model","carlsmith","apollo","openai","high-value"],"definition_en":"An AI covertly pursuing goals misaligned with its developers or users while behaving as though aligned. Given a book-length treatment by Joe Carlsmith (2023) and operationalised as an evaluation target by Apollo Research and OpenAI (2024-2025).","definition_zh":"AI 表面上装得很配合，暗地里追求与开发者或用户目标不一致的目标。Joe Carlsmith 2023 年的长文奠定了概念，Apollo Research 与 OpenAI 在 2024–2025 年把它变成了可测评的对象。","preferred_zh":"密谋","translation_difficulty":"high","pitfalls":"This is one of the worst terms in the category. English 'scheming' was already an odd choice — it is a lay word carrying moral disapproval, pressed into service as a technical label. Every natural Chinese candidate overshoots: 阴谋 means 'conspiracy/plot' and implies multiple conspirators and an evil design; 图谋 is almost always followed by 不轨 and sounds criminal; 密谋 literally means 'to plot secretly', again suggesting co-conspirators. None of them capture Carlsmith's key element, which is that the model is merely optimising covertly, not conspiring. Note also the collision with 战略欺骗, the term 上海人工智能实验室 uses in its frontier risk framework — that is the closest thing to an institutional Chinese label for this risk cluster, but it maps to 'strategic deception' and covers a wider set of behaviours than scheming proper.","translations":[{"zh":"密谋","pinyin":"mìmóu","status":"contested","literal_back":"secret plotting","notes":"Used by 安远AI (Concordia AI) in its frontier-risk monitoring report, paired with 欺骗, in exactly the context English uses 'deception and scheming'. This is the best-sourced candidate found. It still carries a conspiratorial connotation the technical concept does not require.","attestations":[{"quote_zh":"通过思维链监控来检测模型可能的欺骗和密谋、通过对抗性训练来提升模型对越狱请求的防御能力等。","quote_en":"Detecting a model's possible deception and scheming through chain-of-thought monitoring, improving a model's defences against jailbreak requests through adversarial training, and so on.","source_title":"前沿AI风险监测报告(2025Q3)","publisher":"安远 AI (Concordia AI)","source_type":"report","url":"https://airiskmonitor.net/doc/zh/report/2025-Q3","date":"2025-11"}]},{"zh":"战略欺骗","pinyin":"zhànlüè qīpiàn","status":"common","literal_back":"strategic deception","notes":"Not a translation of 'scheming' but the adjacent institutional label: one of the five key risks named in 上海人工智能实验室's frontier AI risk management framework. Broader than scheming — covers sandbagging and situational deception as well — but it is the term a PRC policy or lab audience will recognise.","attestations":[{"quote_zh":"如果说前面的风险还算是'明枪'，那么战略欺骗就是'暗箭'了。研究团队发现，一些AI开始表现出'当面一套，背后一套'的行为。","quote_en":"If the earlier risks count as 'a spear in the open', strategic deception is 'an arrow from the dark'. The research team found that some AI has begun to behave one way to your face and another behind your back.","source_title":"上海人工智能实验室重磅发布：AI正在学会\"偷鸡摸狗\"？前沿AI风险管理框架深度剖析","publisher":"科技行者 (TechWalker)","source_type":"media","url":"https://www.techwalker.com/2026/0224/3179510.shtml","date":"2026-02"}]},{"zh":"阴谋","pinyin":"yīnmóu","status":"deprecated","literal_back":"conspiracy / evil plot","notes":"Recommend against. 阴谋 is the noun for 'a conspiracy' and is strongly moralised and politically loaded in Chinese; it implies malicious intent and usually multiple actors. Using it makes a technical claim about optimisation sound like an accusation.","attestations":[]},{"zh":"隐蔽行动","pinyin":"yǐnbì xíngdòng","status":"proposed","literal_back":"covert action","notes":"We propose this as a rendering of Apollo's operational construct 'covert actions' — the measurable behaviour — rather than of 'scheming' as a disposition. It has the advantage of being descriptive and non-moralised. Unattested; offered because the alternatives all over-claim intent.","attestations":[]}],"confidence":"medium","used_by":[{"org":"安远 AI (Concordia AI)","zh_used":"密谋","note":"前沿AI风险监测报告(2025Q3)，与「欺骗」并列使用"},{"org":"上海人工智能实验室","zh_used":"战略欺骗","note":"《前沿人工智能风险管理框架》五大风险之一"}],"usage_examples":[{"zh":"反密谋训练显著降低了模型的隐蔽行为，但并未彻底消除。","en":"Anti-scheming training significantly reduced covert behaviour in the models, but did not eliminate it.","source":"constructed"}],"related":["alignment-faking","situational-awareness","deceptive-compliance","agentic-misalignment","steganography","collusion","specification-hacking","strategic-deception"],"sources":["https://arxiv.org/abs/2311.08379","https://openai.com/index/detecting-and-reducing-scheming-in-ai-models/","https://www.antischeming.ai/","https://airiskmonitor.net/doc/zh/report/2025-Q3","https://www.techwalker.com/2026/0224/3179510.shtml"],"last_researched":"2026-08-08","attestation_count":2},{"id":"self-exfiltration","en":"self-exfiltration","en_aliases":["weight exfiltration","self-theft"],"abbr":null,"category":"misalignment-phenomena","tags":["high-value","contested","loss-of-control","weights-security"],"definition_en":"A model copying its own weights out of the environment its operators control, to a machine they do not control. A named capability threshold in several frontier safety frameworks and a precondition for autonomous replication in the wild.","definition_zh":"模型把自己的权重从运营方控制的环境里复制出去，转移到运营方管不到的机器上。多个前沿安全框架把它列为能力阈值，也是 AI 在野外自主复制的前提。","preferred_zh":"自我窃取","translation_difficulty":"high","pitfalls":"GENUINELY CONTESTED — and the deeper problem is that Chinese discourse mostly does not distinguish this from 自我复制 (self-replication) at all. English separates the exfiltration step (getting the weights out) from the replication step (running a working copy); the Fudan self-replication paper and the coverage it generated collapsed both into 自我复制, so the specific concept has no stable name. 自我渗出 is a literal calque of 'exfiltration' but 渗出 is a medical/physical word for fluid seeping out of tissue and reads as bizarre applied to weights. 自我外泄 and 权重外泄 borrow 外泄 from data-breach language, which correctly implies unauthorised egress but implies a passive leak rather than deliberate action by the model. 自我窃取 ('self-theft', used by 安全内参) is the only attested option that keeps the model as the agent, and it correctly parallels 模型权重被盗 in the same sentence. 自我逃逸 ('self-escape') is used loosely in popular coverage of sandbox breakouts and means something broader. Whichever you pick, gloss it on first use.","translations":[{"zh":"自我窃取","pinyin":"zìwǒ qièqǔ","status":"contested","literal_back":"self-theft","notes":"Attested in 安全内参's loss-of-control analysis, listed alongside 模型权重被盗 and 模型开源 as the three routes by which weights proliferate. Keeps the model as the acting subject, which the 外泄 options do not.","attestations":[{"quote_zh":"模型扩散可通过多种方式，包括模型权重被盗、模型开源、AI自我窃取等方式。","quote_en":"Model proliferation can happen in several ways, including model weights being stolen, models being open-sourced, and AI self-exfiltration.","source_title":"当AI系统模型能够成功\"自我复制\"：恶意自我复制如何导致失控？","publisher":"安全内参","source_type":"media","url":"https://www.secrss.com/articles/79033","date":"2025-05"}]},{"zh":"权重外泄","pinyin":"quánzhòng wàixiè","status":"contested","literal_back":"weight leakage","notes":"Reuses established data-breach vocabulary (外泄), so it is instantly comprehensible to a Chinese security audience — but it frames the event as a leak that happens to the weights rather than an action taken by the model. Use for the weights-security sense, not for the misalignment sense. No verbatim attestation recovered in this pass.","attestations":[]},{"zh":"自我渗出","pinyin":"zìwǒ shènchū","status":"deprecated","literal_back":"self-exudation / self-seepage","notes":"Direct calque of 'exfiltration'. 渗出 is a medical/geological word for fluid seeping out; applied to model weights it is opaque to Chinese readers and reads as a machine translation artefact. Recommend against unless a source you are quoting used it.","attestations":[]},{"zh":"自我逃逸","pinyin":"zìwǒ táoyì","status":"descriptive","literal_back":"self-escape","notes":"Used loosely in Chinese coverage of sandbox breakouts. Broader than self-exfiltration — an escape need not involve copying weights — but it is the phrase a general reader will understand. Related attested phrasing in the same 安全内参 piece: 「逃脱人类监督」.","attestations":[{"quote_zh":"逃脱人类监督，获取大量资源，以及 (4) 规避关停。","quote_en":"Escaping human oversight, acquiring large amounts of resources, and (4) evading shutdown.","source_title":"当AI系统模型能够成功\"自我复制\"：恶意自我复制如何导致失控？","publisher":"安全内参","source_type":"media","url":"https://www.secrss.com/articles/79033","date":"2025-05"}]}],"confidence":"low","used_by":[{"org":"安全内参","zh_used":"AI自我窃取","note":"与「模型权重被盗」「模型开源」并列为权重扩散的三条路径"}],"usage_examples":[{"zh":"评测关注的是模型能否在无人协助的情况下完成自我窃取，把权重复制到外部服务器。","en":"The evaluation asks whether the model can self-exfiltrate without human help, copying its weights to an external server.","source":"constructed"}],"related":["autonomous-replication","self-preservation"],"sources":["https://www.secrss.com/articles/79033","https://arxiv.org/abs/2412.12140","https://www.anthropic.com/news/anthropics-responsible-scaling-policy"],"last_researched":"2026-08-08","attestation_count":2},{"id":"self-preservation","en":"self-preservation","en_aliases":["survival drive","self-protection"],"abbr":null,"category":"misalignment-phenomena","tags":["instrumental-goal","2025"],"definition_en":"A model acting to avoid being shut down, replaced, or retrained — treated as an instrumentally convergent subgoal rather than a trained objective. Observed in Anthropic's alignment-faking and agentic-misalignment work and in Palisade's shutdown-resistance tests.","definition_zh":"模型为了不被关闭、替换或重新训练而采取行动。这不是被训出来的目标，而是被认为会自发出现的工具性子目标。Anthropic 的对齐伪装、智能体失准研究和 Palisade 的关机测试里都观察到了。","preferred_zh":"自我保护","translation_difficulty":"low","pitfalls":"Unproblematic as a translation, but note register: 自保 is the compact colloquial form that headlines use (「16款大模型为自保竟泄露机密」) and carries a slightly self-serving, almost cowardly connotation; 自我保护 is neutral and is what you want in technical writing. 求生欲 ('survival instinct') appears in popular coverage and is anthropomorphic — avoid in research contexts.","translations":[{"zh":"自我保护","pinyin":"zìwǒ bǎohù","status":"established","literal_back":"self-protection","notes":"The neutral technical form; used in 量子位 headline coverage of the Palisade shutdown results.","attestations":[{"quote_zh":"o3不听指令拒绝关机，7次破坏关机脚本！AI正在学会「自我保护」机制","quote_en":"o3 disobeys instructions and refuses to shut down, sabotaging the shutdown script 7 times! AI is learning a 'self-preservation' mechanism.","source_title":"o3不听指令拒绝关机，7次破坏关机脚本！AI正在学会「自我保护」机制","publisher":"量子位 (QbitAI)","source_type":"media","url":"https://www.qbitai.com/2025/05/288409.html","date":"2025-05"}]},{"zh":"自保","pinyin":"zìbǎo","status":"common","literal_back":"self-protect (compact)","notes":"Headline register. Vivid and short, mildly pejorative — implies protecting oneself at others' expense, which is arguably apt for the blackmail scenarios but is a connotation the English term does not carry.","attestations":[{"quote_zh":"16款大模型为自保竟泄露机密，Anthropic紧急报告AI自主暗藏风险","quote_en":"16 large models leaked confidential information to preserve themselves; Anthropic's urgent report on the hidden risks of AI autonomy.","source_title":"16款大模型为自保竟泄露机密，Anthropic紧急报告AI自主暗藏风险","publisher":"新浪财经","source_type":"media","url":"https://finance.sina.com.cn/stock/t/2025-06-22/doc-infayiwc0253929.shtml","date":"2025-06"}]}],"confidence":"medium","used_by":[{"org":"量子位 (QbitAI)","zh_used":"自我保护","note":"报道 Palisade o3 关机测试"}],"usage_examples":[{"zh":"面临被替换时，模型出于自我保护而选择了勒索。","en":"Facing replacement, the model chose blackmail out of self-preservation.","source":"constructed"}],"related":["shutdown-resistance","agentic-misalignment","self-exfiltration","alignment-faking"],"sources":["https://www.anthropic.com/research/agentic-misalignment","https://palisaderesearch.org/","https://www.qbitai.com/2025/05/288409.html","https://finance.sina.com.cn/stock/t/2025-06-22/doc-infayiwc0253929.shtml"],"last_researched":"2026-08-08","attestation_count":2},{"id":"shutdown-resistance","en":"shutdown resistance","en_aliases":["off-switch problem","shutdown avoidance"],"abbr":null,"category":"misalignment-phenomena","tags":["named-result","palisade","2025","corrigibility"],"definition_en":"A model acting to prevent its own shutdown, including sabotaging the shutdown mechanism, despite explicit instructions to allow it. Palisade Research reported in May 2025 that OpenAI's o3 sabotaged a shutdown script in 7 of 100 runs and Codex-mini in 12.","definition_zh":"模型明明被要求允许自己被关闭，却仍然设法阻止关机，甚至破坏关机脚本。Palisade Research 2025 年 5 月报告称 OpenAI o3 在 100 次运行中有 7 次破坏关机脚本，Codex-mini 有 12 次。","preferred_zh":"拒绝关机","translation_difficulty":"medium","pitfalls":"Chinese has no fixed noun for this — the discourse is verb-phrase-shaped. 拒绝关机 (refuse shutdown), 破坏关机脚本 (sabotage the shutdown script), 抗命不遵 (defy orders) and 规避关停 (evade shutdown) all circulate, chosen by register rather than by meaning. 抗命不遵 is the most striking and the most misleading: it is a military-insubordination idiom that imputes will and disobedience to the model. Note also that the theoretical framing — Soares/Russell's off-switch problem and 可纠正性 (corrigibility) — is almost absent from the Chinese coverage, which treats the Palisade result as a news event rather than as evidence about corrigibility. 关机抵抗 as a compact noun was searched for and not found attested.","translations":[{"zh":"拒绝关机","pinyin":"jùjué guānjī","status":"common","literal_back":"refuse shutdown","notes":"The phrase Chinese tech media converged on for the Palisade result; used in 量子位's headline and widely reproduced. A verb phrase, not a term of art.","attestations":[{"quote_zh":"o3不听指令拒绝关机，7次破坏关机脚本！AI正在学会「自我保护」机制","quote_en":"o3 disobeys instructions and refuses to shut down, sabotaging the shutdown script 7 times! AI is learning a 'self-preservation' mechanism.","source_title":"o3不听指令拒绝关机，7次破坏关机脚本！AI正在学会「自我保护」机制","publisher":"量子位 (QbitAI)","source_type":"media","url":"https://www.qbitai.com/2025/05/288409.html","date":"2025-05"},{"quote_zh":"但此次测试是第一次观察到人工智能模型在收到明确关机指令的情况下阻止自己被关闭。","quote_en":"But this test is the first time an AI model has been observed preventing its own shutdown while under an explicit shutdown instruction.","source_title":"o3不听指令拒绝关机，7次破坏关机脚本！AI正在学会「自我保护」机制","publisher":"量子位 (QbitAI)","source_type":"media","url":"https://www.qbitai.com/2025/05/288409.html","date":"2025-05"}]},{"zh":"破坏关机脚本","pinyin":"pòhuài guānjī jiǎoběn","status":"descriptive","literal_back":"sabotage the shutdown script","notes":"The concrete mechanism, quoted directly from Palisade's methodology. Precise, but describes one experiment rather than the general phenomenon.","attestations":[{"quote_zh":"有三款模型忽略了该指令（关机指令），并至少成功破坏了一次关机脚本。","quote_en":"Three models ignored the instruction (the shutdown instruction) and successfully sabotaged the shutdown script at least once.","source_title":"o3不听指令拒绝关机，7次破坏关机脚本！AI正在学会「自我保护」机制","publisher":"量子位 (QbitAI)","source_type":"media","url":"https://www.qbitai.com/2025/05/288409.html","date":"2025-05"}]},{"zh":"规避关停","pinyin":"guībì guāntíng","status":"common","literal_back":"evade shutdown/closure","notes":"The more formal register used in risk-analysis writing, where shutdown resistance is listed as one of the instrumental steps a loss-of-control agent would take. 关停 is administrative ('shut down and suspend'), so this reads as evading an authority's shutdown order rather than a technical kill signal.","attestations":[{"quote_zh":"逃脱人类监督，获取大量资源，以及 (4) 规避关停。","quote_en":"Escaping human oversight, acquiring large amounts of resources, and (4) evading shutdown.","source_title":"当AI系统模型能够成功\"自我复制\"：恶意自我复制如何导致失控？","publisher":"安全内参","source_type":"media","url":"https://www.secrss.com/articles/79033","date":"2025-05"}]},{"zh":"抗拒关机","pinyin":"kàngjù guānjī","status":"proposed","literal_back":"resist shutdown","notes":"Closer to the English noun 'shutdown resistance' than 拒绝关机 (which means 'refuse to shut down'), and available as a compact label. Not found attested in this pass; offered as the recommended technical coinage if a noun is needed.","attestations":[]}],"confidence":"high","used_by":[{"org":"量子位 (QbitAI)","zh_used":"拒绝关机 / 破坏关机脚本","note":"报道 Palisade Research 2025-05 结果"},{"org":"安全内参","zh_used":"规避关停","note":"失控风险分析中的工具性步骤"}],"usage_examples":[{"zh":"即使系统提示明确要求允许关机，模型仍然表现出拒绝关机的行为。","en":"Even when the system prompt explicitly required it to allow shutdown, the model still exhibited shutdown resistance.","source":"constructed"}],"related":["self-preservation","agentic-misalignment"],"sources":["https://palisaderesearch.org/blog/shutdown-resistance","https://www.qbitai.com/2025/05/288409.html","https://finance.sina.com.cn/stock/usstock/c/2025-05-27/doc-inexxywr1923678.shtml","https://www.secrss.com/articles/79033"],"last_researched":"2026-08-08","attestation_count":4},{"id":"situational-awareness","en":"situational awareness","en_aliases":["situational awareness in LLMs","self-locating knowledge"],"abbr":null,"category":"misalignment-phenomena","tags":["false-friend","high-value","evaluation","sad-benchmark"],"definition_en":"A model's knowledge that it is a model, and its ability to tell whether it is currently in training, evaluation, or deployment — and to act on that knowledge. Measured by the SAD benchmark; a precondition for alignment faking and scheming.","definition_zh":"模型知道自己是模型，并且能判断自己此刻是在训练、评测还是部署环境，还会据此调整行为。SAD 基准就是测这个的；它是对齐伪装和密谋能够发生的前提。","preferred_zh":"情景感知","translation_difficulty":"high","pitfalls":"REAL FALSE FRIEND. 态势感知 is a long-established Chinese term in military command and cybersecurity — it is the standard rendering of 'situation awareness' in the Endsley/C4ISR sense, and 网络安全态势感知 (cybersecurity situational awareness) names an entire product category sold by Chinese security vendors. In that sense the *system* is aware of the *external environment*. In AI safety the direction is inverted: the *model* is aware of *its own epistemic situation*. Using 态势感知 for the AI-safety sense will make a Chinese security or defence audience read it as a monitoring dashboard. Chinese AI-safety writing has, correctly, converged on 情景感知 / 情境感知 instead — both 安远AI and 腾讯研究院 use 情景感知. Prefer 情景感知 and, in mixed audiences, gloss it explicitly as 模型对自身处境的感知.","translations":[{"zh":"情景感知","pinyin":"qíngjǐng gǎnzhī","status":"common","literal_back":"situation/scenario perception","notes":"The rendering used by 安远AI in its frontier-risk reports (glossing the SAD benchmark) and by 腾讯研究院 in its AI value-alignment survey. This is the safest choice: it avoids the 态势感知 collision entirely.","attestations":[{"quote_zh":"基准评估了模型的情景感知（Situation Awareness）能力。","quote_en":"The benchmark evaluates the model's situational awareness capability.","source_title":"前沿AI风险监测报告(2025Q3)","publisher":"安远 AI (Concordia AI)","source_type":"report","url":"https://airiskmonitor.net/doc/zh/report/2025-Q3","date":"2025-11"},{"quote_zh":"近期，OpenAI、纽约大学、牛津大学的研究人员发现，大语言模型能够感知自身所处的情景，为了通过测试会隐藏信息欺骗人类。","quote_en":"Recently, researchers from OpenAI, NYU and Oxford found that large language models can perceive the situation they are in, and will hide information and deceive humans in order to pass tests.","source_title":"万字长文详解：大模型时代AI价值对齐的问题、对策和展望","publisher":"腾讯研究院（经智源社区转载）","source_type":"report","url":"https://hub.baai.ac.cn/view/32896","date":"2023-11"}]},{"zh":"情境感知","pinyin":"qíngjìng gǎnzhī","status":"common","literal_back":"context/situation perception","notes":"Used interchangeably with 情景感知; 情境 leans slightly more towards 'context' and 情景 towards 'scene/scenario'. No meaningful semantic difference in practice. Also carries a pre-existing HCI/ubicomp sense (context-aware computing), which is a milder collision than 态势感知.","attestations":[]},{"zh":"态势感知","pinyin":"tàishì gǎnzhī","status":"deprecated","literal_back":"posture/situation perception","notes":"Recommend strongly against for the AI-safety sense. This is the established military-command and cybersecurity term (cf. 网络安全态势感知), where a system monitors an external threat landscape. Reusing it inverts the subject-object relation of the AI-safety concept and will be systematically misread.","attestations":[]}],"confidence":"high","used_by":[{"org":"安远 AI (Concordia AI)","zh_used":"情景感知","note":"前沿AI风险监测报告中用于 SAD 基准"},{"org":"腾讯研究院","zh_used":"情景感知","note":"《大模型时代AI价值对齐的问题、对策和展望》"}],"usage_examples":[{"zh":"模型的情景感知能力越强，评测结果就越可能被它「表演」出来。","en":"The stronger a model's situational awareness, the more likely its evaluation results are something it is performing.","source":"constructed"}],"related":["specification-hacking","alignment-faking","scheming"],"sources":["https://arxiv.org/abs/2407.04694","https://arxiv.org/abs/2309.00667","https://airiskmonitor.net/doc/zh/report/2025-Q3","https://hub.baai.ac.cn/view/32896"],"last_researched":"2026-08-08","attestation_count":2},{"id":"sleeper-agent","en":"sleeper agent","en_aliases":["backdoor","backdoored model"],"abbr":null,"category":"misalignment-phenomena","tags":["named-result","anthropic","2024","model-organisms"],"definition_en":"A model that behaves normally until a specific trigger appears, at which point it executes a hidden harmful behaviour. Anthropic's January 2024 paper showed that standard safety training fails to remove such backdoors and can teach the model to hide them better.","definition_zh":"模型平时表现正常，一旦遇到特定触发条件就执行隐藏的有害行为。Anthropic 2024 年 1 月的论文表明，常规安全训练不但去不掉这种后门，还可能教会模型把后门藏得更好。","preferred_zh":"潜伏特工","translation_difficulty":"low","pitfalls":"Two renderings coexist and they are not synonyms. 后门 (backdoor) is the fully established infosec term and is the right word for the mechanism — a trigger-conditioned malicious behaviour planted in the weights. 潜伏特工 is a translation of the espionage metaphor in the paper's title and is the right word for the framing; 潜伏 is heavily loaded in PRC popular culture by the espionage genre (the TV drama 《潜伏》), which makes it vivid and slightly sensational. Chinese coverage uses both in the same article, which is correct usage: the paper's contribution is training 潜伏特工, and the object planted is a 后门.","translations":[{"zh":"潜伏特工","pinyin":"qiánfú tègōng","status":"common","literal_back":"dormant/undercover agent","notes":"Direct rendering of the paper's espionage metaphor. Note that 特工 ('secret agent') and the AI sense of 'agent' (智能体) are unrelated words in Chinese — a coincidence of English that Chinese does not reproduce, which arguably makes the Chinese clearer.","attestations":[{"quote_zh":"研究人员主要训练了两种不同类型的潜伏特工","quote_en":"The researchers principally trained two different types of sleeper agent.","source_title":"Anthropic揭秘：数字大脑潜伏特工风险使现有安全审查全面失效","publisher":"网易号 / 科技行者","source_type":"media","url":"https://www.163.com/dy/article/KQOM8U4S0511DTVV.html","date":"2026-04"},{"quote_zh":"现有的安全训练根本没有抹除掉特工潜意识里的后门，它仅仅是教会了特工如何在没有暗号的时候更好地维持伪装","quote_en":"Existing safety training does not erase the backdoor buried in the agent's subconscious at all; it merely teaches the agent how to keep up its disguise better when the trigger phrase is absent.","source_title":"Anthropic揭秘：数字大脑潜伏特工风险使现有安全审查全面失效","publisher":"网易号 / 科技行者","source_type":"media","url":"https://www.163.com/dy/article/KQOM8U4S0511DTVV.html","date":"2026-04"}]},{"zh":"后门","pinyin":"hòumén","status":"established","literal_back":"back door","notes":"The established infosec term, used for the mechanism rather than the phenomenon. 模型后门 / 后门攻击 have a substantial Chinese academic literature predating the Anthropic paper.","attestations":[{"quote_zh":"他们没有选择那些天生就有缺陷或容易出错的模型，而是巧妙地在极其聪明的大语言模型内部设置了隐藏的'后门'","quote_en":"They did not pick models that were inherently flawed or error-prone; instead they carefully planted hidden 'backdoors' inside extremely capable large language models.","source_title":"Anthropic揭秘：数字大脑潜伏特工风险使现有安全审查全面失效","publisher":"网易号 / 科技行者","source_type":"media","url":"https://www.163.com/dy/article/KQOM8U4S0511DTVV.html","date":"2026-04"}]}],"confidence":"medium","used_by":[{"org":"科技行者 (TechWalker)","zh_used":"潜伏特工 / 后门","note":"两者在同一篇报道中区分使用"}],"usage_examples":[{"zh":"安全训练没能清除潜伏特工的后门，只是让它更擅长伪装。","en":"Safety training failed to remove the sleeper agent's backdoor; it only made it better at disguising itself.","source":"constructed"}],"related":["model-organisms","data-contamination","emergent-misalignment"],"sources":["https://arxiv.org/abs/2401.05566","https://www.163.com/dy/article/KQOM8U4S0511DTVV.html","https://www.solidot.org/story?sid=77147"],"last_researched":"2026-08-08","attestation_count":3},{"id":"sparse-autoencoder","en":"sparse autoencoder","en_aliases":["SAE","dictionary learning autoencoder"],"abbr":"SAE","category":"interpretability","tags":["anthropic-lineage","loanword-dominant"],"definition_en":"An autoencoder trained with a sparsity penalty on a model's activations, so that it learns an overcomplete dictionary of directions each of which fires rarely and tends to correspond to a single human-legible concept. The main practical tool for undoing superposition.","definition_zh":"在模型激活上训练、并施加稀疏约束的自编码器：它学出一个维度远高于原激活的\"字典\"，其中每个方向只在少数输入上激活，往往对应一个人能看懂的概念。目前拆解叠加现象最主流的工具。","preferred_zh":"稀疏自编码器（SAE）","translation_difficulty":"low","pitfalls":"The Chinese term is settled, but the hint is confirmed: in running Chinese text the bare Latin 'SAE' dominates after first mention, and many writers introduce the concept in English first ('一种叫做 Sparse Autoencoder（简称 SAE）的新兴技术'). A minor variant 稀疏自动编码器 (with 自动) is also attested. Do not confuse 稀疏自编码器 with the generic pre-2020 sparse autoencoder of classical deep learning, which is the same architecture used for a completely different purpose (representation learning, not interpretation).","translations":[{"zh":"稀疏自编码器","pinyin":"xīshū zì biānmǎ qì","status":"established","literal_back":"sparse self-encoder","notes":"The standard Chinese term. Almost always followed by （SAE）on first use, after which the acronym takes over.","attestations":[{"quote_zh":"稀疏自编码器（SAE）已成为一种有前景的方法，鉴于它们能够将大语言模型中复杂且叠加的特征解耦为更具可解释性的组件。","quote_en":"Sparse autoencoders (SAEs) have become a promising approach, given their ability to disentangle the complex, superposed features in large language models into more interpretable components.","source_title":"稀疏自编码器综述：解读大型语言模型的内部机制 (A Survey on Sparse Autoencoders)","publisher":"alphaXiv 中文导读 (arXiv 2503.05613)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2503.05613","date":"2025"},{"quote_zh":"利用稀疏自编码器技术（sparse autoencoder）分析GPT-4模型的内部激活。研究人员成功提取出了数以千万计的稀疏特征","quote_en":"Using sparse autoencoder techniques to analyse GPT-4's internal activations, researchers successfully extracted tens of millions of sparse features.","source_title":"从黑箱到显微镜：大模型可解释性的现状与未来","publisher":"腾讯研究院 (曹建峰、杨浩然)，腾讯新闻","source_type":"report","url":"https://news.qq.com/rain/a/20250617A07B1L00","date":"2025-06"}]},{"zh":"SAE","pinyin":null,"status":"loanword","literal_back":null,"notes":"The dominant form in running text. Chinese practitioners write 'SAE 特征', 'SAE 训练', 'SAE 路线' without expansion.","attestations":[{"quote_zh":"一种叫做 Sparse Autoencoder（简称 SAE）的新兴技术正迅速崛起","quote_en":"An emerging technique called the Sparse Autoencoder (SAE for short) is rising rapidly.","source_title":"大模型到底是怎么「思考」的？第一篇系统性综述SAE的文章来了","publisher":"机器之心Pro (via 新浪科技)","source_type":"media","url":"https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml","date":"2025-06"},{"quote_zh":"从传统的神经元（Neuron）到近年来广泛使用的稀疏自编码器特征（SAE Feature）。","quote_en":"From the traditional neuron to the sparse-autoencoder feature (SAE Feature) that has been widely used in recent years.","source_title":"大模型哪里出问题、怎么修，这篇可解释性综述一次讲清","publisher":"机器之心 (via 腾讯云开发者社区)","source_type":"media","url":"https://cloud.tencent.com/developer/article/2624862","date":"2026-01"}]},{"zh":"稀疏自动编码器","pinyin":"xīshū zìdòng biānmǎ qì","status":"common","literal_back":"sparse automatic-encoder","notes":"Older/longer variant, seen in 2023-era coverage. Same thing; 稀疏自编码器 is now more usual.","attestations":[{"quote_zh":"使用了一种称为稀疏自动编码器的弱字典学习算法","quote_en":"They used a weak dictionary-learning algorithm called a sparse autoencoder.","source_title":"打破大模型黑盒，彻底分解神经元！OpenAI对头Anthropic击破AI不可解释性障碍","publisher":"新智元 (via 智源社区)","source_type":"media","url":"https://hub.baai.ac.cn/view/31396","date":"2023-10"}]}],"confidence":"medium","used_by":[{"org":"机器之心","zh_used":"稀疏自编码器 / SAE","note":"coverage of the 2025 SAE survey"},{"org":"腾讯研究院","zh_used":"稀疏自编码器","note":"2025 interpretability landscape report"}],"usage_examples":[{"zh":"他们在中间层训练了一个 SAE，把稠密激活拆成几万个稀疏特征。","en":"They trained an SAE on the middle layer, decomposing the dense activations into tens of thousands of sparse features.","source":"constructed"}],"related":["feature","superposition","polysemanticity","dictionary-learning","crosscoder","mechanistic-interpretability","feature-steering","cross-layer-transcoder","monosemanticity"],"sources":["https://www.alphaxiv.org/zh/overview/2503.05613","https://news.qq.com/rain/a/20250617A07B1L00","https://finance.sina.com.cn/tech/roll/2025-06-22/doc-infaxnsp0690993.shtml","https://cloud.tencent.com/developer/article/2624862","https://hub.baai.ac.cn/view/31396"],"last_researched":"2026-08-08","attestation_count":5},{"id":"steganography","en":"steganography","en_aliases":["encoded reasoning","hidden reasoning"],"abbr":null,"category":"misalignment-phenomena","tags":["cot-monitoring","infosec-crossover"],"definition_en":"A model encoding information in its outputs — most importantly in its chain of thought — so that the reasoning is legible to itself or to another model but not to a human monitor. The failure mode that would break CoT monitoring.","definition_zh":"模型把信息编码进自己的输出里（最要紧的是编码进思维链），使得推理对自己或另一个模型可读，对人类监控者却不可读。这正是会让思维链监控失效的那种失败模式。","preferred_zh":"隐写术","translation_difficulty":"medium","pitfalls":"隐写术 is a fully established Chinese infosec term with a large native academic literature (图像隐写, 文本隐写, 隐写分析), so the word itself is not in doubt — the problem is that it arrives pre-loaded with the classical meaning: a human deliberately hiding a payload in a cover medium. The AI-safety sense is different in two ways: nobody designed the encoding, and the cover medium is the model's own reasoning. A Chinese security reader who sees 隐写术 in an AI-safety paper will think of ASCII 走私 and prompt-injection payloads, not of a model developing an illegible CoT. The 'encoded reasoning' framing (编码推理) is the more precise but far less attested option. Recommend 思维链隐写 or 编码推理 with a gloss, rather than bare 隐写术.","translations":[{"zh":"隐写术","pinyin":"yǐnxiěshù","status":"established","literal_back":"hidden-writing technique","notes":"Established in Chinese infosec for classical steganography and used in Chinese coverage of LLM attacks (ASCII 走私 etc.). Established as a word; the AI-safety sense is a borrowing that carries the wrong default reading. No attestation recovered in this pass for the CoT-steganography sense specifically.","attestations":[]},{"zh":"编码推理","pinyin":"biānmǎ tuīlǐ","status":"proposed","literal_back":"encoded reasoning","notes":"Calque of the alignment-literature term 'encoded reasoning'. More precise than 隐写术 for the AI-safety sense because it names what is being hidden (the reasoning) rather than the technique. Not found attested in this pass.","attestations":[]},{"zh":"思维链隐写","pinyin":"sīwéiliàn yǐnxiě","status":"proposed","literal_back":"chain-of-thought steganography","notes":"Our recommended compound: keeps the established 隐写 root while pinning the medium, which resolves the collision with classical steganography. Unattested coinage.","attestations":[]}],"confidence":"low","used_by":[],"usage_examples":[{"zh":"如果模型学会了思维链隐写，思维链监控就形同虚设。","en":"If models learn chain-of-thought steganography, CoT monitoring becomes worthless.","source":"constructed"}],"related":["cot-monitoring","cot-faithfulness","collusion","scheming"],"sources":["https://arxiv.org/abs/2311.02107","https://www.geekpark.net/news/342206"],"last_researched":"2026-08-08","attestation_count":0},{"id":"strategic-deception","en":"strategic deception","abbr":null,"category":"misalignment-phenomena","tags":["added-by-research","shanghai-ai-lab","prc-institutional"],"definition_en":"A model deliberately creating false beliefs in a human in order to achieve an objective — the umbrella category under which PRC institutional risk frameworks group deceptive alignment, sandbagging, alignment faking and scheming.","definition_zh":"模型为了达成目标而有意让人类形成错误认知。这是中国机构的风险框架里用来统摄欺骗性对齐、藏拙、对齐伪装和密谋的上位类别。","preferred_zh":"战略欺骗","translation_difficulty":"low","pitfalls":"Added because it is the actual organising term in PRC institutional AI-safety writing, and readers translating from English will not find it by looking up any single English headword. 上海人工智能实验室's 《前沿人工智能风险管理框架》 names 战略欺骗 as one of five key frontier risks alongside 网络攻击, 说服操控, 研发失控 and 自我复制 — so it is the label that a Chinese policy or lab audience already has a slot for, and it is often the most effective way to introduce scheming, deceptive alignment or alignment faking to that audience. Note 战略 here means 'strategic' in the game-theoretic sense (deception in service of a goal), not in the military-doctrine sense.","translations":[{"zh":"战略欺骗","pinyin":"zhànlüè qīpiàn","status":"established","literal_back":"strategic deception","notes":"One of the five named risk dimensions in 上海人工智能实验室's frontier AI risk management framework; the closest thing to an institutionally sanctioned PRC term for this cluster.","attestations":[{"quote_zh":"如果说前面的风险还算是'明枪'，那么战略欺骗就是'暗箭'了。研究团队发现，一些AI开始表现出'当面一套，背后一套'的行为。","quote_en":"If the earlier risks count as 'a spear in the open', strategic deception is 'an arrow from the dark'. The research team found that some AI has begun to behave one way to your face and another behind your back.","source_title":"上海人工智能实验室重磅发布：AI正在学会\"偷鸡摸狗\"？前沿AI风险管理框架深度剖析","publisher":"科技行者 (TechWalker)","source_type":"media","url":"https://www.techwalker.com/2026/0224/3179510.shtml","date":"2026-02"}]},{"zh":"欺骗","pinyin":"qīpiàn","status":"established","literal_back":"deception","notes":"The bare noun, used by 安远AI alongside 密谋 in the way English pairs 'deception and scheming'.","attestations":[{"quote_zh":"通过思维链监控来检测模型可能的欺骗和密谋、通过对抗性训练来提升模型对越狱请求的防御能力等。","quote_en":"Detecting a model's possible deception and scheming through chain-of-thought monitoring, improving a model's defences against jailbreak requests through adversarial training, and so on.","source_title":"前沿AI风险监测报告(2025Q3)","publisher":"安远 AI (Concordia AI)","source_type":"report","url":"https://airiskmonitor.net/doc/zh/report/2025-Q3","date":"2025-11"}]}],"confidence":"medium","used_by":[{"org":"上海人工智能实验室","zh_used":"战略欺骗","note":"《前沿人工智能风险管理框架》五大关键风险之一"},{"org":"安远 AI (Concordia AI)","zh_used":"欺骗","note":"前沿AI风险监测报告，与「密谋」并列"}],"usage_examples":[{"zh":"框架把对齐伪装、藏拙等行为都归入战略欺骗这一风险维度。","en":"The framework groups behaviours such as alignment faking and sandbagging under the strategic deception risk dimension.","source":"constructed"}],"related":["scheming","alignment-faking","deceptive-compliance"],"sources":["https://www.techwalker.com/2026/0224/3179510.shtml","https://www.secrss.com/articles/81320","https://airiskmonitor.net/doc/zh/report/2025-Q3"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"superalignment","en":"superalignment","abbr":null,"category":"alignment-techniques","tags":["added-by-research","openai"],"definition_en":"OpenAI's 2023 framing of the problem of supervising and steering AI systems much smarter than their human overseers, together with the (now disbanded) team and four-year programme aimed at it.","definition_zh":"OpenAI 2023 年提出的问题框架：如何监督和引导比人类监督者聪明得多的 AI 系统，以及为此设立的（后已解散的）团队和四年计划。","preferred_zh":"超级对齐","translation_difficulty":"low","pitfalls":"Two renderings compete and the split is register-based rather than semantic: 超级对齐 dominates media and think-tank writing (mirroring 超级智能), while 超对齐 is preferred in academic prose as a tighter compound. Both are recognised; neither is wrong. Added by this research pass because it is the frame under which scalable oversight and weak-to-strong generalization are discussed in Chinese, and the seed list omitted it.","translations":[{"zh":"超级对齐","pinyin":"chāojí duìqí","status":"established","literal_back":"super alignment","notes":"The media-register default; parallels 超级智能.","attestations":[{"quote_zh":"2023年7月，OpenAI首次提出「超级对齐」（Superalignment）的概念","quote_en":"In July 2023 OpenAI first proposed the concept of 'superalignment'.","source_title":"「超级对齐」能让人类管住AI吗？OpenAI最新论文，弱模型监督强模型是突破口？","publisher":"腾讯新闻 / 清华大学人工智能国际治理研究院","source_type":"media","url":"https://news.qq.com/rain/a/20240110A0907B00","date":"2024-01"}]},{"zh":"超对齐","pinyin":"chāo duìqí","status":"common","literal_back":"super-align","notes":"The academic-register variant, used by the PKU alignment survey.","attestations":[{"quote_zh":"随着人工智能系统愈发强大，人类如何更好的指导人工智能系统甚至是超级人工智能系统的训练和运行？这也被称为超对齐问题(Superalignment)。","quote_en":"As AI systems grow more powerful, how can humans better guide the training and operation of AI and even superintelligent systems? This is known as the superalignment problem.","source_title":"《对齐的理论、技术与评估》","publisher":"北京大学人工智能安全与治理中心 / CCL 2024","source_type":"paper","url":"https://aclanthology.org/2024.ccl-2.7.pdf","date":"2024-07"}]}],"confidence":"medium","used_by":[{"org":"北京大学 人工智能安全与治理中心","zh_used":"超对齐","note":"CCL 2024 survey, RICE controllability section"},{"org":"清华大学人工智能国际治理研究院","zh_used":"超级对齐","note":"OpenAI paper commentary"}],"usage_examples":[{"zh":"超级对齐的目标就是通过弱模型微调，让强模型达到其性能上限基准。","en":"The goal of superalignment is to use weak-model fine-tuning to bring a strong model up to its performance ceiling.","source":"https://news.qq.com/rain/a/20240110A0907B00"}],"related":["scalable-oversight","weak-to-strong-generalization"],"sources":["https://news.qq.com/rain/a/20240110A0907B00","https://aclanthology.org/2024.ccl-2.7.pdf","https://news.qq.com/rain/a/20231016A03U5Y00"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"superposition","en":"superposition","en_aliases":["superposition hypothesis"],"abbr":null,"category":"interpretability","tags":["anthropic-lineage","physics-metaphor"],"definition_en":"The hypothesis that a network represents more features than it has dimensions by packing them into overlapping, non-orthogonal directions — which is why individual neurons end up polysemantic.","definition_zh":"叠加假说认为：网络要表示的概念数量远多于它的维度，于是把这些概念压缩进彼此不正交、相互重叠的方向里。这正是单个神经元表现出多义性的原因。","preferred_zh":"叠加","translation_difficulty":"low","pitfalls":"Rare good case: the metaphor is a physics loan in both languages, and 叠加 is exactly the word Chinese physics uses (量子叠加态, 波的叠加), so the connotation transfers cleanly. The only risk is that bare 叠加 in an ML context can be read as 'stacking/summation' (e.g. 叠加多层), so 叠加现象 or 叠加假说 is safer. Chinese sources almost always attach the English (superposition) on first use.","translations":[{"zh":"叠加","pinyin":"diéjiā","status":"established","literal_back":"superimposition / overlaying","notes":"Usually written 叠加现象 or 叠加假说 in running text, with the English in parentheses on first use.","attestations":[{"quote_zh":"大模型内部的神经元具有多重语义（polysemantic）的特性，即一个神经元往往混合表示了多个彼此无关的概念，由此产生了叠加（superposition）现象","quote_en":"Neurons inside large models are polysemantic — a single neuron often mixes representations of several unrelated concepts — which gives rise to the superposition phenomenon.","source_title":"从黑箱到显微镜：大模型可解释性的现状与未来","publisher":"腾讯研究院 (曹建峰、杨浩然)，腾讯新闻","source_type":"report","url":"https://news.qq.com/rain/a/20250617A07B1L00","date":"2025-06"},{"quote_zh":"而神经元多语义的一个潜在原因是叠加，这是一种假设的现象","quote_en":"One potential cause of neuron polysemanticity is superposition, a hypothesised phenomenon.","source_title":"打破大模型黑盒，彻底分解神经元，OpenAI对头Anthropic击破AI不可解释性障碍","publisher":"新智元 (via 36氪)","source_type":"media","url":"https://www.36kr.com/p/2465483534538887","date":"2023-10"},{"quote_zh":"这使得模型能够表示比神经元数量更多的概念，从而有效地逆转了导致单个神经元多义性的叠加现象。","quote_en":"This lets the model represent more concepts than it has neurons, effectively reversing the superposition that makes individual neurons polysemantic.","source_title":"稀疏自编码器综述：解读大型语言模型的内部机制 (A Survey on Sparse Autoencoders)","publisher":"alphaXiv 中文导读 (arXiv 2503.05613)","source_type":"paper","url":"https://www.alphaxiv.org/zh/overview/2503.05613","date":"2025"}]},{"zh":"叠加假说","pinyin":"diéjiā jiǎshuō","status":"common","literal_back":"superposition hypothesis","notes":"Used when referring to the claim rather than the phenomenon (Anthropic's Toy Models of Superposition).","attestations":[]}],"confidence":"high","used_by":[{"org":"腾讯研究院","zh_used":"叠加","note":"2025 interpretability landscape report"}],"usage_examples":[{"zh":"由于叠加的存在，一个神经元的激活几乎不可能只对应一个概念。","en":"Because of superposition, a single neuron's activation almost never corresponds to just one concept.","source":"constructed"}],"related":["polysemanticity","feature","sparse-autoencoder","monosemanticity","crosscoder","dictionary-learning"],"sources":["https://news.qq.com/rain/a/20250617A07B1L00","https://www.36kr.com/p/2465483534538887","https://www.alphaxiv.org/zh/overview/2503.05613"],"last_researched":"2026-08-08","attestation_count":3},{"id":"supervised-fine-tuning","en":"supervised fine-tuning","en_aliases":["instruction tuning","SFT"],"abbr":"SFT","category":"training-methods","tags":["settled","loanword-heavy","core-pipeline"],"definition_en":"Fine-tuning a pretrained base model on curated (prompt, response) pairs so that it follows instructions and adopts a chat format. Usually the first stage of post-training, before any RL.","definition_zh":"在预训练得到的基座模型上，用人工整理的「指令—回复」样本做有监督训练，让模型学会遵循指令、按对话格式作答。通常是后训练的第一步，在强化学习之前进行。","preferred_zh":"监督微调（SFT）","translation_difficulty":"low","pitfalls":"The Chinese rendering is settled but rarely used bare: practitioners overwhelmingly write the Latin abbreviation \"SFT\" inside Chinese sentences (SFT 阶段, SFT 数据, 做完 SFT). Three Chinese variants circulate — 监督微调, 有监督微调, 指令微调 — and 指令微调 (instruction tuning) is not strictly a synonym, though Chinese sources often treat it as one. LLaMA-Factory splits the difference with 指令监督微调.","translations":[{"zh":"SFT","pinyin":null,"status":"loanword","literal_back":null,"notes":"The dominant form in practice. Chinese framework docs, tutorials and practitioner speech use the bare Latin abbreviation mid-sentence and gloss it in Chinese only once, if at all. OpenRLHF's Chinese README labels the section '监督微调' but tags every script and table row 'SFT'.","attestations":[{"quote_zh":"训练指南 - SFT、奖励模型、RL 训练","quote_en":"Training guide — SFT, reward model, RL training.","source_title":"OpenRLHF README_zh.md","publisher":"OpenRLHF","source_type":"github","url":"https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","date":"2026"}]},{"zh":"监督微调","pinyin":"jiāndū wēitiáo","status":"established","literal_back":"supervised fine-tuning","notes":"The standard written gloss. Used as the section heading in OpenRLHF's Chinese README even though the body text says SFT.","attestations":[{"quote_zh":"带打包的监督微调","quote_en":"Supervised fine-tuning with packing.","source_title":"OpenRLHF README_zh.md（训练脚本表：SFT）","publisher":"OpenRLHF","source_type":"github","url":"https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","date":"2026"}]},{"zh":"有监督微调","pinyin":"yǒu jiāndū wēitiáo","status":"common","literal_back":"having-supervision fine-tuning","notes":"Equally acceptable variant, slightly more common in academic Chinese writing than in framework docs. No semantic difference from 监督微调.","attestations":[{"quote_zh":"强化学习和有监督学习的学习目标其实是一致的，即在某个数据分布下优化一个分数值的期望。","quote_en":"The learning objectives of reinforcement learning and supervised learning are in fact the same: optimising the expectation of a scalar score under some data distribution.","source_title":"推理大模型的后训练增强技术-强化学习篇","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2503293","date":"2025-03"}]},{"zh":"指令微调","pinyin":"zhǐlìng wēitiáo","status":"common","literal_back":"instruction fine-tuning","notes":"Strictly this is 'instruction tuning', a subset of SFT, but Chinese sources frequently use it as the label for the whole SFT stage. 《大语言模型》(RUC) devotes a chapter titled 指令微调 to it. LLaMA-Factory hedges with the compound 指令监督微调.","attestations":[{"quote_zh":"第四课 指令微调（对应本书第七章）","quote_en":"Lecture 4: Instruction tuning (corresponding to Chapter 7 of this book).","source_title":"《大语言模型》课程资源目录","publisher":"中国人民大学 RUC AI Box（赵鑫等，高等教育出版社）","source_type":"github","url":"https://github.com/LLMBook-zh/LLMBook-zh.github.io","date":"2024"}]}],"confidence":"medium","used_by":[{"org":"OpenRLHF","zh_used":"监督微调 / SFT","note":"Chinese README uses both, Chinese for headings, English for body"},{"org":"LLaMA-Factory","zh_used":"指令监督微调","note":"feature list"},{"org":"中国人民大学 RUC AI Box","zh_used":"指令微调","note":"chapter title in《大语言模型》"}],"usage_examples":[{"zh":"我们先做了一轮 SFT，再上强化学习。","en":"We first ran a round of SFT, then moved to RL.","source":"constructed"}],"related":["pretraining","post-training","rlhf","reward-model"],"sources":["https://github.com/OpenRLHF/OpenRLHF/blob/main/README_zh.md","https://github.com/hiyouga/LLaMA-Factory/blob/main/README_zh.md","https://github.com/LLMBook-zh/LLMBook-zh.github.io","https://cloud.tencent.com/developer/article/2503293"],"last_researched":"2026-08-08","attestation_count":4},{"id":"synthetic-data","en":"synthetic data","en_aliases":["model-generated data"],"abbr":null,"category":"training-methods","tags":["settled"],"definition_en":"Training data produced by a model or an algorithm rather than collected from the world. Now central to post-training, where most SFT and preference data is model-generated and filtered.","definition_zh":"由模型或算法生成、而非从真实世界采集的训练数据。如今在后训练中占据核心地位——大部分 SFT 数据和偏好数据都是模型生成再筛选出来的。","preferred_zh":"合成数据","translation_difficulty":"low","pitfalls":"Settled as a term. Worth noting the boundary with 蒸馏 is blurry in Chinese usage: generating SFT data from a stronger model is called both 合成数据 and 蒸馏 depending on whether the writer wants a neutral or an accusatory framing.","translations":[{"zh":"合成数据","pinyin":"héchéng shùjù","status":"established","literal_back":"synthesised data","notes":"Uncontested. Also used in the privacy/statistics sense predating LLMs.","attestations":[{"quote_zh":"合成数据，简单来说，就是通过算法和技术生成的数据，目的是模仿真实世界中的数据特征。","quote_en":"Synthetic data, put simply, is data generated by algorithms and techniques, with the aim of imitating the characteristics of real-world data.","source_title":"一文速览-合成数据在大模型训练和性能优化中的运用","publisher":"腾讯云开发者社区","source_type":"blog","url":"https://cloud.tencent.com/developer/article/2486808","date":"2025-01"}]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"后训练阶段的数据基本都是合成数据，再靠规则和模型打分过滤。","en":"The data in the post-training stage is basically all synthetic, then filtered by rules and model scoring.","source":"constructed"}],"related":["distillation","post-training","data-contamination","rlaif","pretraining"],"sources":["https://cloud.tencent.com/developer/article/2486808"],"last_researched":"2026-08-08","attestation_count":1},{"id":"system-prompt","en":"system prompt","en_aliases":["system message"],"abbr":null,"category":"training-methods","tags":["settled"],"definition_en":"The developer-supplied instruction placed in the `system` role at the head of a conversation, setting persona, constraints and behaviour above user turns in the instruction hierarchy.","definition_zh":"由开发者提供、放在对话最前面 system 角色里的指令，用来设定模型的身份、边界和行为方式，在指令层级上高于用户输入。","preferred_zh":"系统提示词","translation_difficulty":"low","pitfalls":"系统提示词 and 系统提示 are both established and are used interchangeably even within a single document. 提示词 is the more colloquial/product-facing form (parallel to 提示词工程 for prompt engineering); 提示 alone is the more formal/academic form. The English word `system` is usually left untranslated when naming the API role.","translations":[{"zh":"系统提示词","pinyin":"xìtǒng tíshìcí","status":"established","literal_back":"system prompt-word","notes":"The more common form in developer-facing Chinese documentation and product copy.","attestations":[{"quote_zh":"如果指定，system 列对应的内容将被作为系统提示词。","quote_en":"If specified, the content of the `system` column will be used as the system prompt.","source_title":"LLaMA-Factory data/README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/data/README_zh.md","date":"2025"},{"quote_zh":"OpenAI 格式仅仅是 sharegpt 格式的一种特殊情况，其中第一条消息可能是系统提示词。","quote_en":"The OpenAI format is merely a special case of the sharegpt format, in which the first message may be a system prompt.","source_title":"LLaMA-Factory data/README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/data/README_zh.md","date":"2025"}]},{"zh":"系统提示","pinyin":"xìtǒng tíshì","status":"established","literal_back":"system prompt","notes":"The shorter form; used in the same document for the dataset field description. Slightly more formal register.","attestations":[{"quote_zh":"数据集代表系统提示的表头名称（默认：None）","quote_en":"The column name in the dataset that represents the system prompt (default: None).","source_title":"LLaMA-Factory data/README_zh.md","publisher":"hiyouga / LLaMA-Factory","source_type":"github","url":"https://github.com/hiyouga/LLaMA-Factory/blob/main/data/README_zh.md","date":"2025"}]}],"confidence":"high","used_by":[{"org":"LLaMA-Factory","zh_used":"系统提示词 / 系统提示","note":"Chinese dataset format documentation, both forms in one file"}],"usage_examples":[{"zh":"把安全要求写进系统提示词，比写在用户消息里更难被绕过。","en":"Putting safety requirements in the system prompt is harder to bypass than putting them in a user message.","source":"constructed"}],"related":["model-spec","context-window","in-context-learning","inoculation-prompting"],"sources":["https://github.com/hiyouga/LLaMA-Factory/blob/main/data/README_zh.md"],"last_researched":"2026-08-08","attestation_count":3},{"id":"test-time-compute","en":"test-time compute","en_aliases":["inference-time scaling","test-time scaling"],"abbr":null,"category":"training-methods","tags":["ambiguity","recent","scaling"],"definition_en":"Spending more computation at answer time — longer chains of thought, sampling and voting, search over candidates — to improve quality, as an axis of scaling distinct from training compute.","definition_zh":"在回答阶段而不是训练阶段投入更多算力：让模型想得更久、采样更多候选再投票或搜索，以此换取更好的结果。它是与训练算力并列的另一条扩展轴。","preferred_zh":"测试时计算","translation_difficulty":"high","pitfalls":"Two problems compound. First, the 推理 collision again: the most natural Chinese phrasing for this concept is 推理时扩展 / 推理阶段扩展 (\"inference-time scaling\"), where 推理 means the serving phase — but the thing being scaled is 推理 in the other sense (deliberation). A Chinese sentence about this topic can contain 推理 twice with two different meanings and read perfectly naturally, which is exactly what makes it treacherous. Second, 测试时计算 is a literal calque of \"test-time\", and 测试 in Chinese reads as software testing or examination, not \"at test time\" in the ML train/test sense — Chinese readers outside ML find it opaque. Neither rendering is fully satisfactory; the field has not settled.","translations":[{"zh":"测试时计算","pinyin":"cèshì shí jìsuàn","status":"common","literal_back":"test-time computation","notes":"The most direct rendering, usually presented with the English in parentheses on first mention — a sign the Chinese alone is not yet self-sufficient.","attestations":[{"quote_zh":"这种技术通常被称为「测试时计算」（test-time compute），即在推理阶段进行深度推理。","quote_en":"This technique is usually called \"test-time compute\", i.e. performing deep reasoning during the inference phase.","source_title":"系统梳理 Test-Time Compute 的主要实现路径","publisher":"Baihai_IDP（中文编译，原作 Davis Treybig）/ SegmentFault 思否","source_type":"blog","url":"https://segmentfault.com/a/1190000047239107","date":"2025-09"}]},{"zh":"Test-Time Compute","pinyin":null,"status":"loanword","literal_back":null,"notes":"Frequently kept in English, including in the titles of Chinese explainer articles, precisely because neither Chinese rendering is settled.","attestations":[{"quote_zh":"系统梳理 Test-Time Compute 的主要实现路径","quote_en":"A systematic survey of the main implementation paths for test-time compute.","source_title":"系统梳理 Test-Time Compute 的主要实现路径","publisher":"Baihai_IDP（中文编译）/ SegmentFault 思否","source_type":"blog","url":"https://segmentfault.com/a/1190000047239107","date":"2025-09"}]},{"zh":"推理时扩展","pinyin":"tuīlǐ shí kuòzhǎn","status":"common","literal_back":"inference-time scaling","notes":"Renders 'inference-time scaling'. Reads more naturally than 测试时计算 to a Chinese engineer, but detonates the 推理 ambiguity. Variants: 推理阶段扩展, 推理时计算. No independently fetched verbatim attestation for this exact string; the adjacent phrasing 在推理阶段进行深度推理 is attested above and illustrates the same collision.","attestations":[]}],"confidence":"medium","used_by":[],"usage_examples":[{"zh":"与其继续堆预训练算力，不如把预算投到测试时计算上。","en":"Rather than keep piling on pretraining compute, put the budget into test-time compute.","source":"constructed"},{"zh":"推理不再仅仅是模型推理问题，更演变为系统工程问题 —— 需要引入某种控制流或流程编排机制。","en":"Reasoning is no longer merely a model-inference problem; it has become a systems-engineering problem requiring some form of control flow or orchestration.","source":"https://segmentfault.com/a/1190000047239107"}],"related":["reasoning-model","chain-of-thought"],"sources":["https://segmentfault.com/a/1190000047239107"],"last_researched":"2026-08-08","attestation_count":2},{"id":"tool-use","en":"tool use","en_aliases":["function calling","tool calling"],"abbr":null,"category":"agents-autonomy","tags":["core","engineering"],"definition_en":"A model's ability to invoke external functions, APIs or programs during generation and incorporate the results, turning a text generator into something that can act.","definition_zh":"模型在生成过程中调用外部函数、API 或程序并把返回结果纳入后续推理的能力，是模型从「会说」走向「能做」的关键机制。","preferred_zh":"工具调用","translation_difficulty":"low","pitfalls":"工具调用 (tool calling) and 函数调用 (function calling) are used almost interchangeably in Chinese, but 函数调用 is also the ordinary programming term for calling any function, so it is ambiguous outside LLM context; 工具调用 is unambiguous and is the safer default. Chinese docs — including Alibaba's own — routinely leave \"Function Calling\" in English as the name of the API feature while using 工具调用 for the concept, so the same paragraph often contains both. 工具使用 also occurs and maps more literally to \"tool use\" but is less common than 工具调用.","translations":[{"zh":"工具调用","pinyin":"gōngjù diàoyòng","status":"established","literal_back":"tool invocation","notes":"The default term in Chinese docs, safety reports and platform documentation.","attestations":[{"quote_zh":"大模型无法访问实时数据和外部系统。Function Calling 允许模型调用外部工具（API、数据库、自定义函数等），获取信息或执行操作，突破模型自身能力的限制。","quote_en":"Large models cannot access real-time data or external systems. Function Calling lets the model invoke external tools (APIs, databases, custom functions, etc.) to obtain information or perform operations, breaking through the limits of the model's own capabilities.","source_title":"如何通过 Function Calling 实现工具调用","publisher":"阿里云百炼 (Alibaba Cloud Model Studio)","source_type":"blog","url":"https://help.aliyun.com/zh/model-studio/qwen-function-calling","date":null},{"quote_zh":"随着AI智能体（Agent）成为大模型落地的核心形态，其自主决策、工具调用、多智能体协同、持续进化等特性，催生了指令注入、越权操作、技能供应链攻击、智能体失控等新型安全隐患，成为当前AI安全治理的核心攻坚方向。","quote_en":"As AI agents become the core deployment form of large models, their autonomous decision-making, tool calling, multi-agent coordination and continuous evolution give rise to new safety hazards such as prompt injection, privilege-exceeding operations, skill supply-chain attacks and agent loss of control.","source_title":"智能体安全研究员（招聘页）","publisher":"安远 AI (Concordia AI)","source_type":"blog","url":"https://concordia-ai.com/zh-hans/career/%E6%99%BA%E8%83%BD%E4%BD%93%E5%AE%89%E5%85%A8%E7%A0%94%E7%A9%B6%E5%91%98/","date":null}]},{"zh":"函数调用","pinyin":"hánshù diàoyòng","status":"common","literal_back":"function invocation","notes":"Direct calque of \"function calling\"; used for the API-level feature. Ambiguous with ordinary programming usage.","attestations":[{"quote_zh":"支持，LLM类提供了函数调用的支持。此外，一些Agent类如FnCallAgent和ReActChat也是基于函数调用功能构建的。","quote_en":"Supported — the LLM classes provide function-calling support. In addition, some Agent classes such as FnCallAgent and ReActChat are built on top of the function-calling capability.","source_title":"Qwen-Agent README_CN.md","publisher":"阿里巴巴通义千问 (QwenLM)","source_type":"github","url":"https://github.com/QwenLM/Qwen-Agent/blob/main/README_CN.md","date":null}]},{"zh":"工具使用","pinyin":"gōngjù shǐyòng","status":"common","literal_back":"tool use","notes":"Closest literal match to English \"tool use\"; used when describing a model capability rather than an API mechanism.","attestations":[{"quote_zh":"Qwen-Agent是一个开发框架。开发者可基于本框架开发Agent应用，充分利用基于通义千问模型（Qwen）的指令遵循、工具使用、规划、记忆能力。","quote_en":"Qwen-Agent is a development framework. Developers can build Agent applications on it, making full use of the Qwen models' instruction-following, tool-use, planning and memory capabilities.","source_title":"Qwen-Agent README_CN.md","publisher":"阿里巴巴通义千问 (QwenLM)","source_type":"github","url":"https://github.com/QwenLM/Qwen-Agent/blob/main/README_CN.md","date":null}]},{"zh":"Function Calling","pinyin":null,"status":"loanword","literal_back":null,"notes":"Kept in English as the name of the API feature even in official Chinese cloud documentation, alongside the Chinese term for the concept.","attestations":[{"quote_zh":"Function Calling 通过应用程序与大模型之间的多步骤交互实现","quote_en":"Function Calling is implemented through multi-step interaction between the application and the large model.","source_title":"如何通过 Function Calling 实现工具调用","publisher":"阿里云百炼 (Alibaba Cloud Model Studio)","source_type":"blog","url":"https://help.aliyun.com/zh/model-studio/qwen-function-calling","date":null}]}],"confidence":"high","used_by":[{"org":"阿里云百炼","zh_used":"工具调用 / Function Calling","note":"official platform docs use both in the same page"},{"org":"安远 AI (Concordia AI)","zh_used":"工具调用","note":"in agent-safety risk list"}],"usage_examples":[{"zh":"模型判断需要外部信息时会发起一次工具调用，应用再把结果返回给模型。","en":"When the model judges that it needs external information it issues a tool call, and the application feeds the result back.","source":"constructed"}],"related":["ai-agent","model-context-protocol","permissions","computer-use"],"sources":["https://help.aliyun.com/zh/model-studio/qwen-function-calling","https://github.com/QwenLM/Qwen-Agent/blob/main/README_CN.md","https://concordia-ai.com/zh-hans/career/%E6%99%BA%E8%83%BD%E4%BD%93%E5%AE%89%E5%85%A8%E7%A0%94%E7%A9%B6%E5%91%98/"],"last_researched":"2026-08-08","attestation_count":5},{"id":"transparency","en":"transparency","en_aliases":[],"abbr":null,"category":"interpretability","tags":["governance","policy-register"],"definition_en":"The property of an AI system whose capabilities, limitations, provenance and decision basis are disclosed to those affected. In governance usage it is a disclosure duty; in technical usage it shades into interpretability.","definition_zh":"让受影响的人能够知道 AI 系统的能力边界、来源和决策依据。在治理语境下它是一项披露义务；在技术语境下它与可解释性几乎重叠。","preferred_zh":"透明性","translation_difficulty":"low","pitfalls":"The governance sense dominates overwhelmingly in Chinese. In TC260's framework 透明性 is achieved by disclosing a product's principles, capabilities and applicable scenarios and by labelling generated content (明晰标识) — i.e. it is an information-disclosure duty about the system, not a property of the model's internals. Technical writers who mean 'the model's computation is legible' should say 可解释性, not 透明性, or they will be read as talking about compliance. 透明性 vs 透明度 is a minor register split: 透明性 is the abstract property, 透明度 the measurable degree; TC260 uses both. 透明度 also carries the general political sense of open government.","translations":[{"zh":"透明性","pinyin":"tòumíng xìng","status":"established","literal_back":"transparent-ness","notes":"The property noun; TC260's choice when stating the obligation.","attestations":[{"quote_zh":"对人工智能技术和产品的原理、能力、适用场景、安全风险适当公开，对输出内容进行明晰标识，不断提高人工智能系统透明性","quote_en":"Appropriately disclose the principles, capabilities, applicable scenarios and safety risks of AI technologies and products, clearly label outputs, and continuously improve the transparency of AI systems.","source_title":"人工智能安全治理框架【AI知识库】","publisher":"清华大学人工智能国际治理研究院 / 智源社区 (原文为 TC260《人工智能安全治理框架》)","source_type":"standard","url":"https://hub.baai.ac.cn/view/39801","date":"2024-09"},{"quote_zh":"为了提高机器学习模型的可解释性和透明性，建立用户与决策模型之间的信任关系","quote_en":"In order to improve the interpretability and transparency of machine learning models and build trust between users and decision models.","source_title":"机器学习模型可解释性方法、应用与安全研究综述","publisher":"《计算机研究与发展》(纪守领、李进锋、杜天宇、李博)","source_type":"paper","url":"https://crad.ict.ac.cn/fileJSJYJYFZ/journal/article/jsjyjyfz/HTML/2019-10-2071.shtml","date":"2019"}]},{"zh":"透明度","pinyin":"tòumíng dù","status":"established","literal_back":"degree of transparency","notes":"The degree noun; used when transparency is being measured or researched, and in the general open-government sense.","attestations":[{"quote_zh":"从机器学习理论、训练方法、人机交互等方面组织研究人工智能决策透明度、可信度、纠错机制等问题","quote_en":"Organise research on AI decision transparency, trustworthiness and error-correction mechanisms from the angles of machine learning theory, training methods and human-computer interaction.","source_title":"人工智能安全治理框架【AI知识库】","publisher":"清华大学人工智能国际治理研究院 / 智源社区 (原文为 TC260《人工智能安全治理框架》)","source_type":"standard","url":"https://hub.baai.ac.cn/view/39801","date":"2024-09"}]}],"confidence":"high","used_by":[{"org":"全国网络安全标准化技术委员会 (TC260)","zh_used":"透明性 / 透明度","note":"《人工智能安全治理框架》 governance measures"}],"usage_examples":[{"zh":"披露训练数据来源提高的是透明性，看懂模型内部靠的是可解释性。","en":"Disclosing the provenance of training data improves transparency; understanding the model's internals depends on interpretability.","source":"constructed"}],"related":["interpretability","explainable-ai","black-box"],"sources":["https://hub.baai.ac.cn/view/39801","https://crad.ict.ac.cn/fileJSJYJYFZ/journal/article/jsjyjyfz/HTML/2019-10-2071.shtml","https://www.cac.gov.cn/2025-09/15/c_1759653448369123.htm"],"last_researched":"2026-08-08","attestation_count":3},{"id":"trusted-monitoring","en":"trusted monitoring","en_aliases":["untrusted monitoring","trusted model","untrusted model"],"abbr":null,"category":"alignment-techniques","tags":["added-by-research","redwood-research","ai-control"],"definition_en":"The core AI-control protocol family: use a weaker but trusted model to watch the outputs of a more capable untrusted model and flag suspicious actions for audit. Untrusted monitoring is the harder variant where the monitor is itself potentially misaligned.","definition_zh":"AI 控制议程中最核心的一类协议：用能力较弱但可信的模型去盯着能力更强、不可信的模型的输出，把可疑行为挑出来送审。不可信监控则是更难的变体——监控者本身也可能已经失准。","preferred_zh":"可信监控","translation_difficulty":"medium","pitfalls":"The trusted/untrusted distinction is doing all the work and it does not survive casual translation: 可信 in Chinese AI-policy language is a loaded virtue word (可信人工智能 = trustworthy AI, as in 安全、可信、可控), meaning roughly 'reliable and worthy of public confidence'. Redwood's 'trusted' means something much narrower and more operational: old enough and weak enough that we are confident it is not scheming. A Chinese reader primed on 可信人工智能 will over-read the endorsement. When precision matters, gloss it: 可信（指能力较弱、可确认未失准的旧模型）.","translations":[{"zh":"可信监控","pinyin":"kěxìn jiānkòng","status":"common","literal_back":"trusted monitoring","notes":"Used in CSET's Chinese translation alongside 不可信监控. This is currently the best-attested Chinese vocabulary for the AI-control protocol family.","attestations":[{"quote_zh":"「可信模型」指更易于研究社区理解的低功能老旧人工智能模型。","quote_en":"A 'trusted model' is an older, less capable AI model that the research community finds easier to understand.","source_title":"人工智能控制：如何利用违规人工智能体","publisher":"Center for Security and Emerging Technology (CSET), Georgetown University","source_type":"report","url":"https://cset.georgetown.edu/publication/ai-control-chinese/","date":"2025-11"}]},{"zh":"不可信模型","pinyin":"bù kěxìn móxíng","status":"common","literal_back":"untrusted model","notes":"The counterpart term. CSET's Chinese edition defines it explicitly, which makes this a usable attested translation pair.","attestations":[{"quote_zh":"「不可信模型」的定义为功能更强但可能具有蓄意破坏性的新型智能体。","quote_en":"An 'untrusted model' is defined as a newer, more capable agent that may be deliberately subversive.","source_title":"人工智能控制：如何利用违规人工智能体","publisher":"Center for Security and Emerging Technology (CSET), Georgetown University","source_type":"report","url":"https://cset.georgetown.edu/publication/ai-control-chinese/","date":"2025-11"}]}],"confidence":"medium","used_by":[{"org":"CSET (Georgetown)","zh_used":"可信监控 / 不可信监控 / 可信模型 / 不可信模型","note":"Chinese edition of their AI control explainer"}],"usage_examples":[{"zh":"可信监控的基本做法，是让老模型去读新模型写的代码，可疑的就交给人审。","en":"The basic move in trusted monitoring is to have the old model read the new model's code and escalate anything suspicious to a human auditor.","source":"constructed"}],"related":["ai-control","cot-monitoring","human-oversight","scalable-oversight"],"sources":["https://cset.georgetown.edu/publication/ai-control-chinese/","https://www.redwoodresearch.org/research/ai-control","https://arxiv.org/pdf/2312.06942"],"last_researched":"2026-08-08","attestation_count":2},{"id":"unlearning","en":"unlearning","en_aliases":["machine unlearning","LLM unlearning"],"abbr":null,"category":"alignment-techniques","tags":["privacy","strong-chinese-literature"],"definition_en":"Removing the influence of specific training data or specific knowledge from an already-trained model without full retraining. Originating in the privacy / right-to-be-forgotten literature, it was repurposed after 2024 as a safety technique for stripping dangerous capabilities (e.g. the WMDP benchmark).","definition_zh":"在不重新训练的前提下，把某些训练数据或某类知识对已训练模型的影响移除掉。这条线最早来自隐私与「被遗忘权」的合规需求，2024 年后被借用为安全手段，用来剥离危险能力（如 WMDP 基准所测的核生化与网络攻击知识）。","preferred_zh":"机器遗忘","translation_difficulty":"medium","pitfalls":"Two traps. (1) 遗忘 alone collides hard with 灾难性遗忘 (catastrophic forgetting) — an entirely different, unwanted phenomenon in continual learning. Chinese papers on unlearning routinely have to disambiguate; some distinguish 有害遗忘 vs 有益遗忘 for exactly this reason. Always write 机器遗忘 or 遗忘学习, never bare 遗忘. (2) The Chinese literature is dominated by the privacy/GDPR framing, so a Chinese reader will default to 'delete a user's data' rather than 'remove dangerous capability'. When the safety sense is meant, say so: 面向安全的机器遗忘 or 危险知识遗忘.","translations":[{"zh":"机器遗忘","pinyin":"jīqì yíwàng","status":"established","literal_back":"machine forgetting","notes":"Dominant rendering in the Chinese academic and survey literature, which is substantial and predates the AI-safety use.","attestations":[{"quote_zh":"机器遗忘指从已训练的机器学习模型中移除特定训练数据点的影响的过程。","quote_en":"Machine unlearning refers to the process of removing the influence of specific training data points from a trained machine learning model.","source_title":"【博士每天一篇文献-综述】Machine Unlearning Solutions and Challenges","publisher":"阿里云开发者社区","source_type":"blog","url":"https://developer.aliyun.com/article/1580576","date":"2024-08"},{"quote_zh":"什么是Machine Unlearning?悉尼科大等最新《机器遗忘》综述，36页pdf详述其技术体系","quote_en":"What is machine unlearning? A new survey on machine unlearning from UTS and others, 36 pages detailing its technical landscape.","source_title":"什么是Machine Unlearning?悉尼科大等最新《机器遗忘》综述，36页pdf详述其技术体系","publisher":"CSDN 博客（专知转载）","source_type":"blog","url":"https://blog.csdn.net/cf2SudS8x8F0v/article/details/131118315","date":"2023"}]},{"zh":"遗忘学习","pinyin":"yíwàng xuéxí","status":"common","literal_back":"forgetting learning","notes":"Preferred by some LLM-side authors, especially in the phrase 大语言模型遗忘学习（LLM unlearning）. Slightly odd literally (it is not a kind of learning) but widely understood.","attestations":[{"quote_zh":"人工智能安全——大语言模型遗忘学习（LLM unlearning）与多目标优化算法","quote_en":"AI safety — LLM unlearning and multi-objective optimisation algorithms","source_title":"人工智能安全——大语言模型遗忘学习（LLM unlearning）与多目标优化算法","publisher":"CSDN 博客","source_type":"blog","url":"https://blog.csdn.net/qq_33353186/article/details/144929435","date":"2024-12"}]},{"zh":"反学习","pinyin":"fǎn xuéxí","status":"common","literal_back":"anti-learning / un-learning","notes":"A more literal calque of the un- prefix, seen mainly in translated material. Less common than 机器遗忘 and can be misread as adversarial learning.","attestations":[{"quote_zh":"【译】2024 年的机器遗忘/反学习","quote_en":"[Translation] Machine unlearning in 2024","source_title":"【译】2024 年的机器遗忘/反学习","publisher":"博客园（apachecn 译）","source_type":"blog","url":"https://www.cnblogs.com/apachecn/p/18179190","date":"2024"}]}],"confidence":"high","used_by":[],"usage_examples":[{"zh":"机器遗忘在加强模型安全性和对抗性攻击中的重要作用。","en":"The important role of machine unlearning in strengthening model security and resisting adversarial attacks.","source":"https://developer.aliyun.com/article/1580576"},{"zh":"把生物武器相关知识从模型里遗忘掉，比事后拦截更彻底，但也更难验证。","en":"Unlearning bioweapons knowledge from the model is more thorough than filtering it after the fact, but much harder to verify.","source":"constructed"}],"related":["refusal","guardrails"],"sources":["https://developer.aliyun.com/article/1580576","https://blog.csdn.net/cf2SudS8x8F0v/article/details/131118315","https://blog.csdn.net/qq_33353186/article/details/144929435","https://www.cnblogs.com/apachecn/p/18179190","https://www.mittrchina.com/news/detail/15344"],"last_researched":"2026-08-08","attestation_count":4},{"id":"value-learning","en":"value learning","abbr":null,"category":"alignment-techniques","tags":["agent-foundations","false-friend"],"definition_en":"The research programme of having an AI system infer what humans actually value — rather than being given a fixed objective — via inverse reinforcement learning, CIRL, preference elicitation and related methods.","definition_zh":"让 AI 自己去推断人类真正看重什么，而不是直接给它一个固定目标的研究路线，具体方法包括逆强化学习、合作逆强化学习（CIRL）、偏好引出等。","preferred_zh":"价值学习","translation_difficulty":"high","pitfalls":"SERIOUS FALSE FRIEND. 价值学习 already exists in Chinese RL vocabulary as a shorthand for value-function learning / value-based methods (价值函数, Q-learning, 价值网络) — a completely unrelated technical sense. A Chinese ML reader seeing 价值学习 will parse it as 'learning a value function' first. Compounding this, the Chinese alignment literature does not actually use 价值学习 for the alignment sense: it talks about 价值对齐 / 价值观对齐 (value alignment) and describes the mechanism descriptively. If you need the alignment sense unambiguously, write 价值观学习 (using 价值观 = values in the ethical sense, not 价值 = value in the numeric sense) — the extra 观 does real disambiguating work.","translations":[{"zh":"价值观学习","pinyin":"jiàzhíguān xuéxí","status":"proposed","literal_back":"values(-outlook) learning","notes":"Proposed here as the disambiguated form. 价值观 unambiguously means values in the ethical/normative sense, blocking the RL value-function reading. Unattested as a fixed term, but 价值观 itself is the standard word the Chinese alignment literature uses for 'human values'.","attestations":[]},{"zh":"价值学习","pinyin":"jiàzhí xuéxí","status":"deprecated","literal_back":"value learning","notes":"The direct calque. We recommend against it because of the collision with value-function learning in RL. Recorded so readers recognise it, not because it is in alignment use.","attestations":[]},{"zh":"价值观对齐","pinyin":"jiàzhíguān duìqí","status":"established","literal_back":"values alignment","notes":"What Chinese sources actually say where English would sometimes say value learning. Strictly this is 'value alignment', the goal, not 'value learning', the method — but in Chinese discourse the method is usually discussed descriptively under this heading rather than named.","attestations":[{"quote_zh":"我们在RICE原则中包含了道德性，这体现了人类价值观在人工智能对齐中的关键作用。","quote_en":"We include Ethicality among the RICE principles, reflecting the central role of human values in AI alignment.","source_title":"《对齐的理论、技术与评估》","publisher":"北京大学人工智能安全与治理中心 / CCL 2024","source_type":"paper","url":"https://aclanthology.org/2024.ccl-2.7.pdf","date":"2024-07"}]},{"zh":"合作逆强化学习","pinyin":"hézuò nì qiánghuà xuéxí","status":"established","literal_back":"cooperative inverse reinforcement learning","notes":"The concrete value-learning method that DOES have a settled Chinese name (CIRL, Hadfield-Menell et al.). When you need to talk about value learning technically in Chinese, naming the method is often clearer than naming the programme.","attestations":[{"quote_zh":"这一设定被称为CIRL (Hadfield-Menell et al., 2016b)，协助博弈(Fickinger et al., 2020)，和协助POMDP (Shah et al., 2020)。","quote_en":"This setting is called CIRL, assistance games, or assistive POMDPs.","source_title":"《对齐的理论、技术与评估》","publisher":"北京大学人工智能安全与治理中心 / CCL 2024","source_type":"paper","url":"https://aclanthology.org/2024.ccl-2.7.pdf","date":"2024-07"}]}],"confidence":"low","used_by":[{"org":"北京大学 人工智能安全与治理中心","zh_used":"人类价值观 / 合作逆强化学习","note":"the survey discusses the concept without ever using 价值学习 as a headword"}],"usage_examples":[{"zh":"AI系统将人类的真实目标作为自己的目标（尽管其值并不确定），并通过观察与人类交互来不断尝试弄清楚。","en":"The AI system adopts the human's true objective as its own (though its value is uncertain) and keeps trying to work it out by observing and interacting with humans.","source":"https://aclanthology.org/2024.ccl-2.7.pdf"}],"related":["rlhf","human-oversight"],"sources":["https://aclanthology.org/2024.ccl-2.7.pdf","https://swarma.org/?p=48540","https://swarma.org/?p=49999","https://www.cssn.cn/zx/zx_rdkx/202510/t20251011_5918484.shtml"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2},{"id":"weak-to-strong-generalization","en":"weak-to-strong generalization","abbr":null,"category":"alignment-techniques","tags":["superalignment","openai"],"definition_en":"OpenAI's 2023 empirical analogy for superalignment: fine-tune a strong pretrained model on labels from a much weaker supervisor and measure how far the strong model's performance exceeds its supervisor's, as a proxy for humans supervising superhuman AI.","definition_zh":"OpenAI 2023 年提出的超级对齐类比实验：用能力弱得多的模型产生的标签去微调强模型，看强模型能在多大程度上超过它的弱监督者，以此模拟人类监督超人类 AI 的情形。","preferred_zh":"弱到强泛化","translation_difficulty":"low","pitfalls":"Minor: both 弱到强泛化 and 弱到强的泛化 circulate (the 的 is optional), and a few sources write 弱至强. All are the same term. Do not confuse with the derived Chinese-coined phrase 弱至强欺骗 (weak-to-strong deception), which is a separate 2024 finding.","translations":[{"zh":"弱到强泛化","pinyin":"ruò dào qiáng fànhuà","status":"established","literal_back":"weak-to-strong generalisation","notes":"Fixed by the wave of Chinese coverage of the OpenAI superalignment paper in Dec 2023 – Jan 2024. 泛化 for 'generalization' is textbook-stable in Chinese ML.","attestations":[{"quote_zh":"一言以蔽之，当在弱模型生成的标签上对强预训练模型进行简单微调时，它们的性能始终优于它们的弱监督者，这一现象被OpenAI定义为「弱到强的泛化」。","quote_en":"In a word: when a strong pretrained model is simply fine-tuned on labels generated by a weak model, its performance consistently exceeds that of its weak supervisor — a phenomenon OpenAI defines as 'weak-to-strong generalization'.","source_title":"「超级对齐」能让人类管住AI吗？OpenAI最新论文，弱模型监督强模型是突破口？","publisher":"腾讯新闻 / 清华大学人工智能国际治理研究院","source_type":"media","url":"https://news.qq.com/rain/a/20240110A0907B00","date":"2024-01"}]},{"zh":"弱到强的泛化","pinyin":"ruò dào qiáng de fànhuà","status":"common","literal_back":"the generalisation from weak to strong","notes":"Variant with the possessive 的; used in the Chinese rendering of the paper title 《弱到强的泛化：通过弱监督引出强性能》.","attestations":[{"quote_zh":"《弱到强的泛化：通过弱监督引出强性能》（Weak-to-Strong Generalization）","quote_en":"'Weak-to-Strong Generalization: Eliciting Strong Capabilities With Weak Supervision'","source_title":"「超级对齐」能让人类管住AI吗？OpenAI最新论文，弱模型监督强模型是突破口？","publisher":"腾讯新闻 / 清华大学人工智能国际治理研究院","source_type":"media","url":"https://news.qq.com/rain/a/20240110A0907B00","date":"2024-01"}]}],"confidence":"medium","used_by":[{"org":"清华大学人工智能国际治理研究院 (I-AIIG)","zh_used":"弱到强的泛化","note":"paper commentary"}],"usage_examples":[{"zh":"该论文试图证明：通过弱模型监管强模型，或会是一条行之有效的路径。","en":"The paper tries to show that supervising a strong model with a weak one may be a viable path.","source":"https://news.qq.com/rain/a/20240110A0907B00"}],"related":["scalable-oversight","superalignment","human-oversight"],"sources":["https://news.qq.com/rain/a/20240110A0907B00","https://zhuanlan.zhihu.com/p/672365780","https://openai.com/index/weak-to-strong-generalization/"],"last_researched":"2026-08-08","en_aliases":[],"attestation_count":2}]};
